        }
        if let Some(meta) = state.active_meta.as_mut() {
            if let Some(value) = meta.take_string() {
                state.active_bytes = Some(value.into_bytes());
                return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
