//#region 🔖️EffectiveForwards
/// 🪞️ The effective supersession of every superseded operation ([`protocol::HistoryFold::supersessions`]): the
/// replacement input every fold site reads in place of the recorded forward, which is never modified.
pub type EffectiveSupersessions = BTreeMap<MutationId, protocol::EffectiveSupersession>;

/// 🎭️ One forward operation as every fold site reads it: the recorded original, its decoded replacement, or nothing
/// when withdrawn or when its supersession breaks the supersede law ([`admit_replacement`]). A decoded replacement
/// retires itself through [`Mutation::retire_cold`].
pub struct EffectiveOperation<'a, P, Mutation>
where
    Mutation: self::Mutation<P>,
{
    pub op_index: u32,
    pub mutation_id: MutationId,
    original: &'a Mutation,
    replacement: Option<Mutation>,
    withdrawn: bool,
    fault: Option<crate::os_spr::MutationMessage>,
    marker: PhantomData<fn() -> P>,
}

impl<P, Mutation> EffectiveOperation<'_, P, Mutation>
where
    Mutation: self::Mutation<P>,
{
    /// ▶️ The operation a fold applies, `None` when withdrawn or faulted.
    pub fn operation(&self) -> Option<&Mutation> {
        if self.withdrawn || self.fault.is_some() {
            return None;
        }
        Some(self.replacement.as_ref().unwrap_or(self.original))
    }

    /// 🔀️ Whether a supersession replaced or withdrew the recorded forward (validly or not).
    pub fn superseded(&self) -> bool {
        self.withdrawn || self.replacement.is_some() || self.fault.is_some()
    }

    /// 🚫️ Whether a valid supersession withdrew the operation.
    pub fn withdrawn(&self) -> bool {
        self.withdrawn
    }

    /// 🧯️ The `Fatal` message of a supersession breaking the supersede law; the operation then folds as a no-op.
    pub fn fault(&self) -> Option<&crate::os_spr::MutationMessage> {
        self.fault.as_ref()
    }
}

impl<P, Mutation> Drop for EffectiveOperation<'_, P, Mutation>
where
    Mutation: self::Mutation<P>,
{
    fn drop(&mut self) {
        if let Some(replacement) = self.replacement.take() {
            self::Mutation::<P>::retire_cold(replacement);
        }
    }
}

/// 🔍️ The effective input of `operation` — operation `op_index` of its edit, identified as `mutation_id` — under
/// `supersessions` in a document of `schema`. Total: a supersession breaking the supersede law ([`admit_replacement`])
/// folds the operation as a no-op carrying one `Fatal` `mutation.invariant` message that targets the operation —
/// identically at every fold site, so a garbage or foreign replacement never aborts a projection.
pub fn effective_operation<'a, P, Mutation>(operation: &'a Mutation, op_index: u32, mutation_id: MutationId, schema: &str, supersessions: &EffectiveSupersessions) -> EffectiveOperation<'a, P, Mutation>
where
    Mutation: self::Mutation<P> + OpBinary,
{
    let mut effective = EffectiveOperation { op_index, mutation_id, original: operation, replacement: None, withdrawn: false, fault: None, marker: PhantomData };
    let Some(supersession) = supersessions.get(&effective.mutation_id) else { return effective };
    match admit_replacement::<P, Mutation>(operation, &supersession.replacement, schema) {
        Ok(Some(replacement)) => effective.replacement = Some(replacement),
        Ok(None) => effective.withdrawn = true,
        Err(reason) => {
            let mut fault =
                crate::os_spr::MutationMessage::fatal("mutation.invariant", format!("supersession {} of {} {reason}; the operation folds as a no-op", supersession.transition_id, effective.mutation_id.0)).at([effective.mutation_id.0.clone()]);
            fault.op_index = Some(op_index);
            effective.fault = Some(fault);
        }
    }
    effective
}

/// 🛂️ The supersede law every input obeys — authored, ingested, loaded or folded: `original` plans no foreign steps, and
/// a replacement is an operation of `schema` in its canonical encoding planning no foreign steps. Answers the decoded
/// replacement (`None` for a withdrawal) or why the input breaks the law.
pub fn admit_replacement<P, Mutation>(original: &Mutation, replacement: &protocol::InputReplacement, schema: &str) -> Result<Option<Mutation>, String>
where
    Mutation: self::Mutation<P> + OpBinary,
{
    if original.may_emit_foreign_steps() {
        return Err("targets an operation that plans foreign steps".to_string());
    }
    let protocol::InputReplacement::Input { schema: named, payload } = replacement else { return Ok(None) };
    if named != schema {
        return Err(format!("names schema {named}, not {schema}"));
    }
    let decoded = Mutation::decode_op(payload).map_err(|error| format!("does not decode: {error}"))?;
    let refusal = match decoded.encode_op() {
        Err(error) => Some(format!("does not re-encode: {error}")),
        Ok(recoded) if recoded != *payload => Some("is not canonically encoded".to_string()),
        Ok(_) if decoded.may_emit_foreign_steps() => Some("plans foreign steps".to_string()),
        Ok(_) => None,
    };
    match refusal {
        None => Ok(Some(decoded)),
        Some(reason) => {
            self::Mutation::<P>::retire_cold(decoded);
            Err(reason)
        }
    }
}

/// 📜️ `edit`'s effective forwards in operation order ([`effective_operation`]). The single accessor every fold site
/// reads an edit through.
pub fn effective_forwards<'a, P, Mutation>(edit: &'a Edit<Mutation>, schema: &'a str, supersessions: &'a EffectiveSupersessions) -> impl Iterator<Item = EffectiveOperation<'a, P, Mutation>> + 'a
where
    P: 'a,
    Mutation: self::Mutation<P> + OpBinary + 'a,
{
    let ids = crate::os_spr::mutation_ids_for_edit::<P, Mutation>(edit);
    edit.forwards.iter().zip(ids).enumerate().map(move |(index, (operation, mutation_id))| effective_operation::<P, Mutation>(operation, index as u32, mutation_id, schema, supersessions))
}

/// 🪜️ A fold's running projection: what the next operation diffs against, and how its successor displaces it.
trait FoldProjection<P, Mutation> {
    fn projection(&self) -> &P;
    fn advance(&mut self, next: P);
}

impl<P, Mutation> FoldProjection<P, Mutation> for ReplayProjection<P, Mutation>
where
    Mutation: self::Mutation<P>,
{
    fn projection(&self) -> &P {
        self
    }

    fn advance(&mut self, next: P) {
        ReplayProjection::advance(self, next);
    }
}

impl<P, Mutation> FoldProjection<P, Mutation> for Arc<P>
where
    Mutation: self::Mutation<P>,
{
    fn projection(&self) -> &P {
        self
    }

    fn advance(&mut self, next: P) {
        retire_shared_projection::<P, Mutation>(std::mem::replace(self, Arc::new(next)));
    }
}

/// 🔂️ Folds the first `take` effective forwards of `edit` into `projection` with keep-and-record semantics
/// ([`fold_operation`]) — the one loop every messageless fold site shares.
fn fold_effective_edit<P, Mutation>(projection: &mut impl FoldProjection<P, Mutation>, edit: &Edit<Mutation>, schema: &str, supersessions: &EffectiveSupersessions, take: usize)
where
    Mutation: self::Mutation<P> + OpBinary,
{
    if supersessions.is_empty() {
        for (index, operation) in edit.forwards.iter().enumerate().take(take) {
            if let (Some(next), _) = fold_operation::<P, Mutation>(projection.projection(), operation, index as u32) {
                projection.advance(next);
            }
        }
        return;
    }
    for effective in effective_forwards::<P, Mutation>(edit, schema, supersessions).take(take) {
        if let Some(operation) = effective.operation() {
            if let (Some(next), _) = fold_operation::<P, Mutation>(projection.projection(), operation, effective.op_index) {
                projection.advance(next);
            }
        }
    }
}

/// 🎬️ One operation with [`protocol::MutationOutcome::apply_to`] semantics that never drops a projection: the next
/// projection when its diff applied, and its op-stamped messages — an apply refusal becomes one `Fatal` message and
/// folds as a no-op. The keep-and-record step every fold site, the retained initializers included, takes.
pub fn fold_operation<P, Mutation>(state: &P, operation: &Mutation, op_index: u32) -> (Option<P>, Vec<crate::os_spr::MutationMessage>)
where
    Mutation: self::Mutation<P>,
{
    let (diff, mut messages) = operation.diff(state).stamp_op_index(op_index).into_parts();
    let applied = diff.apply(state);
    <Mutation::Diff as MutationDiff<P>>::retire_cold(diff);
    match applied {
        Ok(next) => (Some(next), messages),
        Err(error) => {
            let mut fatal = crate::os_spr::MutationMessage::fatal(error.code, error.message).at(error.target);
            fatal.op_index = Some(op_index);
            messages.push(fatal);
            (None, messages)
        }
    }
}

/// 📼️ Folds `applied[from..to]` onto `base` under `supersessions` with keep-and-record semantics, handing out the
/// projection after every prefix length below `to` that is a multiple of `stride` (aliases of the running state, no
/// copies). A failure retires the running state and everything recorded.
fn fold_recorded<P, Mutation>(
    base: Arc<P>,
    applied: &[String],
    from: usize,
    to: usize,
    edits: &ArtifactHistoryLedger<Edit<Mutation>>,
    schema: &str,
    supersessions: &EffectiveSupersessions,
    stride: usize,
) -> Result<(Arc<P>, Vec<(usize, Arc<P>)>), VcsError>
where
    Mutation: self::Mutation<P> + OpBinary,
{
    let mut running = base;
    let mut recorded: Vec<(usize, Arc<P>)> = Vec::new();
    let mut failure = None;
    for (offset, edit_id) in applied[from..to].iter().enumerate() {
        let Some(edit) = edits.find_near(|edit| edit.id == *edit_id) else {
            failure = Some(VcsError::UnknownEdit(edit_id.clone()));
            break;
        };
        fold_effective_edit(&mut running, edit, schema, supersessions, usize::MAX);
        let length = from + offset + 1;
        if length < to && length % stride == 0 {
            recorded.push((length, Arc::clone(&running)));
        }
    }
    if let Some(error) = failure {
        retire_shared_projection::<P, Mutation>(running);
        for (_, snapshot) in recorded {
            retire_shared_projection::<P, Mutation>(snapshot);
        }
        return Err(error);
    }
    Ok((running, recorded))
}

/// 🧊️ Releases one alias of a scratch projection: the last owner retires it ([`retire_replayed_projection`]), any
/// other only drops its count — the owner that outlives it retires it.
fn retire_shared_projection<P, Mutation>(projection: Arc<P>)
where
    Mutation: self::Mutation<P>,
{
    if let Ok(projection) = Arc::try_unwrap(projection) {
        retire_replayed_projection::<P, Mutation>(projection);
    }
}

/// 🔏️ Content digest of one effective supersession: which transition installed it and what it replaces the input with.
fn supersession_digest(mutation_id: &MutationId, supersession: &protocol::EffectiveSupersession) -> [u8; 32] {
    let (kind, schema, payload): (&[u8], &[u8], &[u8]) = match &supersession.replacement {
        protocol::InputReplacement::Input { schema, payload } => (b"input", schema.as_bytes(), payload),
        protocol::InputReplacement::Withdrawn => (b"withdrawn", b"", b""),
    };
    CursorRevisionAccumulator::hash_record(b"supersession", &[mutation_id.0.as_bytes(), supersession.transition_id.as_bytes(), kind, schema, payload])
}

/// 🔐️ Digest of the supersessions in effect for `edit`'s operations, `None` when none is.
fn edit_supersession_digest<P, Mutation>(edit: &Edit<Mutation>, supersessions: &EffectiveSupersessions) -> Option<[u8; 32]>
where
    Mutation: self::Mutation<P>,
{
    if supersessions.is_empty() {
        return None;
    }
    let mut digest = None;
    for (index, mutation_id) in crate::os_spr::mutation_ids_for_edit::<P, Mutation>(edit).iter().enumerate() {
        if let Some(supersession) = supersessions.get(mutation_id) {
            digest = Some(CursorRevisionAccumulator::hash_record(b"edit-supersessions", &[&digest.unwrap_or([0; 32]), &(index as u64).to_be_bytes(), &supersession_digest(mutation_id, supersession)]));
        }
    }
    digest
}

/// 🤝️ How many leading ids `live` and `next` share.
fn shared_prefix_len(live: &crate::os_vcs::HistoryPageStack<String>, next: &[String]) -> usize {
    live.iter().zip(next).take_while(|(live, next)| live == next).count()
}

/// 🪞️ Rewrites `mirror` from position `dirty` on to `live`'s suffix ([`StackMirrorDirt`]); answers the ids it displaced.
fn mirror_id_suffix(mirror: &mut crate::os_vcs::HistoryPageStack<String>, live: &crate::os_vcs::HistoryPageStack<String>, dirty: usize) -> Option<Vec<String>> {
    let keep = dirty.min(live.len()).min(mirror.len());
    let mut displaced = Vec::new();
    while mirror.len() > keep {
        displaced.push(mirror.pop().expect("a mirrored id remains present"));
    }
    #[cfg(test)]
    hot_path_census::count(|census| census.mirrored += live.len() - keep);
    mirror.extend(live.iter_from(keep).cloned());
    (!displaced.is_empty()).then_some(displaced)
}

/// 🧭️ Forwards-only effective prefix digests of `applied`: entry `i` names the projection after the first `i` edits by
/// their ids, forward counts and effective supersessions — never the inverses, metadata or messages a replay rewrites.
fn forward_prefix_digests<P, Mutation, I, S>(identity: [u8; 32], applied: I, edits: &ArtifactHistoryLedger<Edit<Mutation>>, supersessions: &EffectiveSupersessions) -> Result<Vec<[u8; 32]>, VcsError>
where
    Mutation: self::Mutation<P>,
    I: IntoIterator<Item = S>,
    S: AsRef<str>,
{
    let mut digest = forward_prefix_genesis(identity);
    let mut digests = Vec::new();
    digests.push(digest);
    for edit_id in applied {
        let edit_id = edit_id.as_ref();
        let edit = edits.find_near(|edit| edit.id == edit_id).ok_or_else(|| VcsError::UnknownEdit(edit_id.to_string()))?;
        digest = forward_prefix_step::<P, Mutation>(&digest, edit, supersessions);
        digests.push(digest);
    }
    Ok(digests)
}

/// 🧭️ The forwards-only digest of the empty prefix of a document of `identity` ([`forward_prefix_digests`]).
fn forward_prefix_genesis(identity: [u8; 32]) -> [u8; 32] {
    CursorRevisionAccumulator::hash_record(b"forward-prefix", &[&identity])
}

/// 🧭️ The forwards-only prefix digest after `edit`, given the digest of the prefix before it ([`forward_prefix_digests`]).
fn forward_prefix_step<P, Mutation>(previous: &[u8; 32], edit: &Edit<Mutation>, supersessions: &EffectiveSupersessions) -> [u8; 32]
where
    Mutation: self::Mutation<P>,
{
    #[cfg(test)]
    hot_path_census::count(|census| census.digested += 1);
    let superseded = edit_supersession_digest::<P, Mutation>(edit, supersessions).unwrap_or([0; 32]);
    CursorRevisionAccumulator::hash_record(b"forward-prefix", &[previous, edit.id.as_bytes(), &(edit.forwards.len() as u64).to_be_bytes(), &superseded])
}

/// 🧮️ The applied positions of every edit owning an operation whose effective supersession differs between `previous`
/// and `next`, ascending.
fn superseded_positions<P, Mutation>(applied: &[String], edits: &ArtifactHistoryLedger<Edit<Mutation>>, previous: &EffectiveSupersessions, next: &EffectiveSupersessions) -> Result<Vec<usize>, VcsError>
where
    Mutation: self::Mutation<P>,
{
    let changed: HashSet<&MutationId> = previous
        .iter()
        .filter(|(target, supersession)| next.get(*target) != Some(*supersession))
        .map(|(target, _)| target)
        .chain(next.iter().filter(|(target, supersession)| previous.get(*target) != Some(*supersession)).map(|(target, _)| target))
        .collect();
    if changed.is_empty() {
        return Ok(Vec::new());
    }
    let mut positions = Vec::new();
    for (position, edit_id) in applied.iter().enumerate() {
        let edit = edits.find_near(|edit| edit.id == *edit_id).ok_or_else(|| VcsError::UnknownEdit(edit_id.clone()))?;
        if crate::os_spr::mutation_ids_for_edit::<P, Mutation>(edit).iter().any(|mutation_id| changed.contains(mutation_id)) {
            positions.push(position);
        }
    }
    Ok(positions)
}

/// 📝️ `supersessions` with every draft replacement laid over it — the effective inputs a time-travel session previews.
pub fn draft_supersessions(supersessions: &EffectiveSupersessions, drafts: &BTreeMap<MutationId, protocol::InputReplacement>) -> EffectiveSupersessions {
    let mut effective = supersessions.clone();
    for (target, replacement) in drafts {
        effective.insert(target.clone(), protocol::EffectiveSupersession { transition_id: DRAFT_SUPERSESSION_ID.to_string(), actor: String::new(), timestamp: HybridLogicalTimestamp::new(0, 0), scope: None, replacement: replacement.clone() });
    }
    effective
}

/// 🏷️ The transition id a not-yet-authored draft supersession carries inside a preview.
pub const DRAFT_SUPERSESSION_ID: &str = "draft";
//#endregion 🔖️EffectiveForwards

//#region 🔖️EditReplay
/// ⚖️ How an [`EditReplay`] settles each edit. `Merge(policy)` is the policy-local ingest verdict: an edit whose worst
/// message the policy rejects is quarantined and an apply refusal aborts the replay. `Report` keeps every edit, records
/// every outcome and never aborts, so its result is policy-independent and identical on every replica.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ReplayMode {
    Merge(crate::os_spr::MergePolicy),
    Report,
}

/// 📚️ Where a replay reads the edits its order names.
pub trait ReplayEdits<Mutation> {
    fn replay_edit(&self, edit_id: &str) -> Option<&Edit<Mutation>>;
}

impl<Mutation> ReplayEdits<Mutation> for HashMap<String, Edit<Mutation>> {
    fn replay_edit(&self, edit_id: &str) -> Option<&Edit<Mutation>> {
        self.get(edit_id)
    }
}

impl<Mutation> ReplayEdits<Mutation> for ArtifactHistoryLedger<Edit<Mutation>> {
    fn replay_edit(&self, edit_id: &str) -> Option<&Edit<Mutation>> {
        self.find_near(|edit| edit.id == edit_id)
    }
}

/// 📶️ `done` of `total` operations a replay folded.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct ReplayProgress {
    pub done: u32,
    pub total: u32,
}

/// ⏯️ Where one [`EditReplay::step`] left its replay.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ReplayStep {
    Pending(ReplayProgress),
    Finished(ReplayProgress),
}

/// 🧲️ The previous projection a Report replay may converge onto. From prefix length `horizon` on every changed input
/// has been replayed, so a prefix whose state equals the previous state after the same prefix leaves the whole tail
/// unchanged: the previous head is spliced in and the replay stops. `checkpoints` ascend by prefix length and end with
/// the previous head.
struct ReplayConvergence<P> {
    horizon: usize,
    checkpoints: Vec<(usize, Arc<P>)>,
    equal: fn(&P, &P) -> bool,
}

/// ⏪️ Resumable replay of `order[from..]` over the projection after `order[..from]`, one operation per inner step:
/// each operation's effective input is re-diffed and re-inverted against the running state and its messages are kept
/// per mutation with their operation index. [`ArtifactStore::replay_suffix_partitioned`] drives a `Merge` replay to
/// completion; history editing steps a `Report` replay under a deadline with progress. Cancelling is dropping it: the
/// running projections, staged inverses and checkpoint aliases all retire.
pub struct EditReplay<P, Mutation>
where
    Mutation: self::Mutation<P>,
{
    mode: ReplayMode,
    order: Vec<String>,
    from: usize,
    prefix_until: usize,
    cursor: usize,
    operation: usize,
    edit_ids: Option<Vec<MutationId>>,
    schema: String,
    supersessions: EffectiveSupersessions,
    state: Option<Arc<P>>,
    candidate: Option<Arc<P>>,
    edit_messages: Vec<crate::os_spr::MutationMessage>,
    edit_inverse: Vec<Mutation>,
    committed: Vec<String>,
    quarantined: Vec<String>,
    rebased_inverse: Vec<(String, Vec<Mutation>)>,
    replayed: Vec<crate::os_spr::EditMessages>,
    outcomes: Vec<protocol::MutationReplayOutcome>,
    convergence: Option<ReplayConvergence<P>>,
    converged_at: Option<usize>,
    record_stride: usize,
    recorded: Vec<(usize, Arc<P>)>,
    drafts: BTreeMap<MutationId, protocol::InputReplacement>,
    generation: u64,
    revision: [u8; 32],
    progress: ReplayProgress,
    finished: bool,
}

impl<P, Mutation> EditReplay<P, Mutation>
where
    Mutation: self::Mutation<P> + OpBinary,
{
    /// 🐣️ A replay of `order[from..]` starting from `base`, the projection after `order[..from]`, reading every
    /// operation of a document of `schema` through `supersessions`. `edits` must hold every edit the suffix names.
    pub fn new(mode: ReplayMode, base: Arc<P>, order: Vec<String>, from: usize, schema: &str, supersessions: EffectiveSupersessions, edits: &impl ReplayEdits<Mutation>) -> Result<Self, VcsError> {
        let mut replay = Self {
            mode,
            order,
            from,
            prefix_until: from,
            cursor: from,
            operation: 0,
            edit_ids: None,
            schema: schema.to_string(),
            supersessions,
            state: Some(base),
            candidate: None,
            edit_messages: Vec::new(),
            edit_inverse: Vec::new(),
            committed: Vec::new(),
            quarantined: Vec::new(),
            rebased_inverse: Vec::new(),
            replayed: Vec::new(),
            outcomes: Vec::new(),
            convergence: None,
            converged_at: None,
            record_stride: usize::MAX,
            recorded: Vec::new(),
            drafts: BTreeMap::new(),
            generation: 0,
            revision: [0; 32],
            progress: ReplayProgress::default(),
            finished: false,
        };
        if replay.from > replay.order.len() {
            return Err(VcsError::ValidationFailed(format!("edit replay starts at {} past its {}-edit order", replay.from, replay.order.len())));
        }
        let mut total = 0u32;
        for edit_id in &replay.order[replay.from..] {
            let edit = edits.replay_edit(edit_id).ok_or_else(|| VcsError::UnknownEdit(edit_id.clone()))?;
            total = total.saturating_add(u32::try_from(edit.forwards.len()).unwrap_or(u32::MAX));
        }
        replay.progress.total = total;
        Ok(replay)
    }

    /// 🐣️ [`Self::new`] starting from `base`, the projection after `order[..base_length]` for a `base_length <= from`: the
    /// replay first folds `order[base_length..from]` plainly — stepped under the same deadline as its suffix and recording the
    /// prefix ring on the way — and then replays `order[from..]` as [`Self::new`] does, so no synchronous fold precedes it.
    #[allow(clippy::too_many_arguments)]
    pub fn new_after_prefix(mode: ReplayMode, base_length: usize, base: Arc<P>, order: Vec<String>, from: usize, schema: &str, supersessions: EffectiveSupersessions, edits: &impl ReplayEdits<Mutation>) -> Result<Self, VcsError> {
        let mut replay = Self::new(mode, base, order, from, schema, supersessions, edits)?;
        if base_length > from {
            return Err(VcsError::ValidationFailed(format!("edit replay base after {base_length} edits lies past its start {from}")));
        }
        replay.cursor = base_length;
        Ok(replay)
    }

    fn with_convergence(mut self, convergence: Option<ReplayConvergence<P>>) -> Self {
        self.replace_convergence(convergence);
        self
    }

    fn replace_convergence(&mut self, convergence: Option<ReplayConvergence<P>>) {
        if let Some(previous) = std::mem::replace(&mut self.convergence, convergence) {
            for (_, checkpoint) in previous.checkpoints {
                retire_shared_projection::<P, Mutation>(checkpoint);
            }
        }
    }

    /// 🧵️ Takes `appended` operations a tick appended to `edit_id` into the total when that edit is the unreplayed tail of
    /// this replay's order (the grown edit is read by id when the replay gets there), and forgets the convergence probe,
    /// whose previous head predates the tick.
    fn absorb_tail_growth(&mut self, edit_id: &str, appended: usize) {
        if self.cursor < self.order.len() && self.order.last().is_some_and(|tail| tail == edit_id) {
            self.progress.total = self.progress.total.saturating_add(u32::try_from(appended).unwrap_or(u32::MAX));
            if self.cursor + 1 == self.order.len() {
                self.edit_ids = None;
            }
        }
        self.replace_convergence(None);
    }

    /// 🎙️ Keeps the projection after every replayed prefix whose length is a multiple of `stride`, for the prefix ring —
    /// seeded with `prefixes`, the retained projections the base was folded through, and with the base itself when its
    /// length is such a multiple.
    fn recording(mut self, stride: usize, prefixes: Vec<(usize, Arc<P>)>) -> Self {
        self.record_stride = stride.max(1);
        self.recorded.extend(prefixes);
        self.record();
        self
    }

    /// 🔢️ Stamps the store generation and content revision this replay was started against — the freshness a finished
    /// replay is committed under ([`ArtifactStore::commit_finished_replay`]).
    pub fn with_base(mut self, generation: u64, revision: [u8; 32]) -> Self {
        self.generation = generation;
        self.revision = revision;
        self
    }

    /// 🖊️ Records the draft inputs this replay previews, which a finalization authors as the supersession.
    pub fn with_drafts(mut self, drafts: BTreeMap<MutationId, protocol::InputReplacement>) -> Self {
        self.drafts = drafts;
        self
    }

    /// 🆔️ The store generation this replay was started against.
    pub fn generation(&self) -> u64 {
        self.generation
    }

    /// 🗒️ The draft inputs this replay previews.
    pub fn drafts(&self) -> &BTreeMap<MutationId, protocol::InputReplacement> {
        &self.drafts
    }

    /// 📈️ Operations folded so far of the suffix total.
    pub fn progress(&self) -> ReplayProgress {
        self.progress
    }

    /// ⌛️ Whether every operation of the suffix was replayed (or the replay converged).
    pub fn is_finished(&self) -> bool {
        self.finished
    }

    /// ⏭️ Replays operations until the replay finishes or `deadline`, asked after every operation, answers `true`.
    pub fn step(&mut self, edits: &impl ReplayEdits<Mutation>, deadline: &mut dyn FnMut() -> bool) -> Result<ReplayStep, VcsError> {
        while !self.finished {
            let Some(edit_id) = self.order.get(self.cursor) else {
                self.finished = true;
                break;
            };
            let edit = edits.replay_edit(edit_id).ok_or_else(|| VcsError::UnknownEdit(edit_id.clone()))?;
            if self.cursor < self.prefix_until {
                let state = self.state.as_mut().ok_or_else(|| VcsError::ValidationFailed("edit replay lost its running projection".into()))?;
                fold_effective_edit(state, edit, &self.schema, &self.supersessions, usize::MAX);
                self.cursor += 1;
                self.record();
                if deadline() {
                    return Ok(ReplayStep::Pending(self.progress));
                }
                continue;
            }
            let edit_ids = match self.edit_ids.take() {
                Some(edit_ids) => edit_ids,
                None => crate::os_spr::mutation_ids_for_edit::<P, Mutation>(edit),
            };
            if self.operation < edit.forwards.len() {
                let replayed = self.replay_operation(edit, &edit_ids);
                self.edit_ids = Some(edit_ids);
                replayed?;
                self.operation += 1;
                self.progress.done = self.progress.done.saturating_add(1);
                if deadline() {
                    return Ok(ReplayStep::Pending(self.progress));
                }
                continue;
            }
            self.close_edit(&edit.id);
            self.cursor += 1;
            self.operation = 0;
            self.record();
            self.converge();
        }
        Ok(ReplayStep::Finished(self.progress))
    }

    fn replay_operation(&mut self, edit: &Edit<Mutation>, edit_ids: &[MutationId]) -> Result<(), VcsError> {
        let index = self.operation;
        let mutation_id = edit_ids.get(index).cloned().unwrap_or_else(|| MutationId(format!("{}#{index}", edit.id)));
        let effective = effective_operation::<P, Mutation>(&edit.forwards[index], index as u32, mutation_id, &self.schema, &self.supersessions);
        let mut messages: Vec<crate::os_spr::MutationMessage> = effective.fault().cloned().into_iter().collect();
        if let Some(operation) = effective.operation() {
            let base = match self.mode {
                ReplayMode::Merge(_) => self.candidate.as_ref().or(self.state.as_ref()),
                ReplayMode::Report => self.state.as_ref(),
            }
            .ok_or_else(|| VcsError::ValidationFailed("edit replay lost its running projection".into()))?;
            let mut back = operation.inverse(base).map_err(VcsError::InverseRefused)?;
            back.reverse();
            let next = match self.mode {
                ReplayMode::Report => {
                    let (next, operation_messages) = fold_operation::<P, Mutation>(base, operation, index as u32);
                    messages = operation_messages;
                    next
                }
                ReplayMode::Merge(_) => {
                    let (diff, operation_messages) = operation.diff(base).stamp_op_index(index as u32).into_parts();
                    let applied = diff.apply(base);
                    <Mutation::Diff as MutationDiff<P>>::retire_cold(diff);
                    messages = operation_messages;
                    match applied {
                        Ok(next) => Some(next),
                        Err(error) => {
                            retire_scratch_operations::<P, Mutation>(back);
                            return Err(error.into());
                        }
                    }
                }
            };
            match next {
                Some(next) => {
                    self.edit_inverse.extend(back);
                    let next = Arc::new(next);
                    let displaced = match self.mode {
                        ReplayMode::Merge(_) => self.candidate.replace(next),
                        ReplayMode::Report => self.state.replace(next),
                    };
                    if let Some(displaced) = displaced {
                        retire_shared_projection::<P, Mutation>(displaced);
                    }
                }
                None => retire_scratch_operations::<P, Mutation>(back),
            }
        }
        let worst = crate::os_spr::worst_level(&messages);
        self.edit_messages.extend(messages.iter().cloned());
        self.outcomes.push(protocol::MutationReplayOutcome { mutation_id: effective.mutation_id.clone(), edit_id: edit.id.clone(), op_index: index as u32, worst, messages, superseded: effective.superseded(), withdrawn: effective.withdrawn() });
        Ok(())
    }

    fn close_edit(&mut self, edit_id: &str) {
        let mut messages = std::mem::take(&mut self.edit_messages);
        if bound_edit_messages(edit_id, &mut messages) {
            for outcome in self.outcomes.iter_mut().rev().take_while(|outcome| outcome.edit_id == edit_id) {
                outcome.messages = messages.iter().filter(|message| message.op_index == Some(outcome.op_index)).cloned().collect();
                outcome.worst = crate::os_spr::worst_level(&outcome.messages);
            }
        }
        let inverse = std::mem::take(&mut self.edit_inverse);
        let rejects = match self.mode {
            ReplayMode::Merge(policy) => crate::os_spr::worst_level(&messages).is_some_and(|level| policy.rejects(level)),
            ReplayMode::Report => false,
        };
        self.replayed.push(crate::os_spr::EditMessages { edit_id: edit_id.to_string(), messages });
        if rejects {
            if let Some(candidate) = self.candidate.take() {
                retire_shared_projection::<P, Mutation>(candidate);
            }
            retire_scratch_operations::<P, Mutation>(inverse);
            self.quarantined.push(edit_id.to_string());
            return;
        }
        if let Some(candidate) = self.candidate.take() {
            if let Some(previous) = self.state.replace(candidate) {
                retire_shared_projection::<P, Mutation>(previous);
            }
        }
        self.rebased_inverse.push((edit_id.to_string(), inverse));
        self.committed.push(edit_id.to_string());
    }

    fn record(&mut self) {
        if self.mode != ReplayMode::Report || self.cursor % self.record_stride != 0 || self.cursor >= self.order.len() {
            return;
        }
        if let Some(state) = self.state.as_ref() {
            self.recorded.push((self.cursor, Arc::clone(state)));
        }
    }

    fn converge(&mut self) {
        if self.mode != ReplayMode::Report {
            return;
        }
        let Some(convergence) = self.convergence.as_ref() else { return };
        if self.cursor < convergence.horizon || self.cursor >= self.order.len() {
            return;
        }
        let (Some(state), Some((_, previous))) = (self.state.as_ref(), convergence.checkpoints.iter().find(|(length, _)| *length == self.cursor)) else { return };
        if !(Arc::ptr_eq(state, previous) || (convergence.equal)(state, previous)) {
            return;
        }
        let Some(head) = convergence.checkpoints.last().filter(|(length, _)| *length == self.order.len()).map(|(_, head)| Arc::clone(head)) else { return };
        self.converged_at = Some(self.cursor);
        self.finished = true;
        self.progress.done = self.progress.total;
        if let Some(previous) = self.state.replace(head) {
            retire_shared_projection::<P, Mutation>(previous);
        }
    }

    /// 🏁️ The finished replay's result; refused while operations remain.
    pub fn finish(mut self) -> Result<EditReplayResult<P, Mutation>, VcsError> {
        if !self.finished {
            return Err(VcsError::ValidationFailed("edit replay has not finished".into()));
        }
        let outcomes = std::mem::take(&mut self.outcomes);
        let worst = outcomes.iter().filter_map(|outcome| outcome.worst).max();
        Ok(EditReplayResult {
            order: std::mem::take(&mut self.order),
            from: self.from,
            supersessions: std::mem::take(&mut self.supersessions),
            drafts: std::mem::take(&mut self.drafts),
            generation: self.generation,
            revision: self.revision,
            state: self.state.take(),
            converged_at: self.converged_at,
            committed: std::mem::take(&mut self.committed),
            quarantined: std::mem::take(&mut self.quarantined),
            rebased_inverse: std::mem::take(&mut self.rebased_inverse),
            replayed: std::mem::take(&mut self.replayed),
            recorded: std::mem::take(&mut self.recorded),
            report: protocol::ReplayReport { from_position: u32::try_from(self.from).unwrap_or(u32::MAX), outcomes, worst },
        })
    }

    /// 🛑️ Cancels the replay; every scratch owner it holds retires and nothing it computed is published.
    pub fn cancel(self) {
        drop(self);
    }
}

impl<P, Mutation> Drop for EditReplay<P, Mutation>
where
    Mutation: self::Mutation<P>,
{
    fn drop(&mut self) {
        for projection in [self.state.take(), self.candidate.take()].into_iter().flatten() {
            retire_shared_projection::<P, Mutation>(projection);
        }
        retire_scratch_operations::<P, Mutation>(std::mem::take(&mut self.edit_inverse));
        for (_, inverse) in std::mem::take(&mut self.rebased_inverse) {
            retire_scratch_operations::<P, Mutation>(inverse);
        }
        if let Some(convergence) = self.convergence.take() {
            for (_, checkpoint) in convergence.checkpoints {
                retire_shared_projection::<P, Mutation>(checkpoint);
            }
        }
        for (_, recorded) in std::mem::take(&mut self.recorded) {
            retire_shared_projection::<P, Mutation>(recorded);
        }
    }
}

/// 🎁️ What a finished [`EditReplay`] produced: the projection it reached, the edits it kept and quarantined, their
/// rebased inverses and messages, and its per-mutation [`protocol::ReplayReport`]. Owners nobody took retire on drop.
pub struct EditReplayResult<P, Mutation>
where
    Mutation: self::Mutation<P>,
{
    order: Vec<String>,
    from: usize,
    supersessions: EffectiveSupersessions,
    drafts: BTreeMap<MutationId, protocol::InputReplacement>,
    generation: u64,
    revision: [u8; 32],
    state: Option<Arc<P>>,
    converged_at: Option<usize>,
    committed: Vec<String>,
    quarantined: Vec<String>,
    rebased_inverse: Vec<(String, Vec<Mutation>)>,
    replayed: Vec<crate::os_spr::EditMessages>,
    recorded: Vec<(usize, Arc<P>)>,
    report: protocol::ReplayReport,
}

impl<P, Mutation> EditReplayResult<P, Mutation>
where
    Mutation: self::Mutation<P>,
{
    /// ⏲️ The store generation the replay was started against.
    pub fn generation(&self) -> u64 {
        self.generation
    }

    /// 📃️ The draft inputs the replay previewed.
    pub fn drafts(&self) -> &BTreeMap<MutationId, protocol::InputReplacement> {
        &self.drafts
    }

    /// 🖼️ The projection the replay reached (the previous head when it converged).
    pub fn state(&self) -> Option<&Arc<P>> {
        self.state.as_ref()
    }

    /// 🎴️ Takes the reached projection; its retirement moves to the caller.
    pub fn take_state(&mut self) -> Option<Arc<P>> {
        self.state.take()
    }

    /// 🤝️ The prefix length at which the replay met the previous projection, if it did.
    pub fn converged_at(&self) -> Option<usize> {
        self.converged_at
    }

    /// ✅️ The edits the replay kept, in order.
    pub fn committed(&self) -> &[String] {
        &self.committed
    }

    /// 🚧️ The edits a `Merge` policy quarantined, in order.
    pub fn quarantined(&self) -> &[String] {
        &self.quarantined
    }

    /// 📨️ Every replayed edit's messages, in order.
    pub fn replayed(&self) -> &[crate::os_spr::EditMessages] {
        &self.replayed
    }

    /// 📊️ The per-mutation outcomes.
    pub fn report(&self) -> &protocol::ReplayReport {
        &self.report
    }

    /// 🪝️ Takes the per-mutation outcomes.
    pub fn take_report(&mut self) -> protocol::ReplayReport {
        std::mem::take(&mut self.report)
    }

    /// ☑️ Takes the kept edit ids.
    pub fn take_committed(&mut self) -> Vec<String> {
        std::mem::take(&mut self.committed)
    }

    /// 🪤️ Takes the quarantined edit ids.
    pub fn take_quarantined(&mut self) -> Vec<String> {
        std::mem::take(&mut self.quarantined)
    }

    /// 📬️ Takes the replayed edits' messages.
    pub fn take_replayed(&mut self) -> Vec<crate::os_spr::EditMessages> {
        std::mem::take(&mut self.replayed)
    }

    /// 🧳️ Takes the recorded prefix projections `(length, projection)`; their retirement moves to the caller.
    pub fn take_recorded(&mut self) -> Vec<(usize, Arc<P>)> {
        std::mem::take(&mut self.recorded)
    }

    /// 🔙️ Takes every kept edit's rebased inverse; their retirement moves to the caller.
    pub fn take_rebased_inverse(&mut self) -> Vec<(String, Vec<Mutation>)> {
        std::mem::take(&mut self.rebased_inverse)
    }
}

impl<P, Mutation> Drop for EditReplayResult<P, Mutation>
where
    Mutation: self::Mutation<P>,
{
    fn drop(&mut self) {
        if let Some(state) = self.state.take() {
            retire_shared_projection::<P, Mutation>(state);
        }
        for (_, inverse) in std::mem::take(&mut self.rebased_inverse) {
            retire_scratch_operations::<P, Mutation>(inverse);
        }
        for (_, recorded) in std::mem::take(&mut self.recorded) {
            retire_shared_projection::<P, Mutation>(recorded);
        }
    }
}

/// 🟰️ Whether two supersession maps install the same effective inputs — which transition installed them aside.
fn same_effective_inputs(left: &EffectiveSupersessions, right: &EffectiveSupersessions) -> bool {
    left.len() == right.len() && left.iter().zip(right.iter()).all(|((left_target, left), (right_target, right))| left_target == right_target && left.replacement == right.replacement)
}

/// 📸️ A retained projection after the first `length` applied edits, valid while `digest` names the live effective
/// prefix ([`forward_prefix_digests`]).
struct PrefixSnapshot<P> {
    length: usize,
    digest: [u8; 32],
    snapshot: Arc<P>,
}

/// 💍️ The most prefix projections a store retains, whatever its history length; the stride adapts so they spread over the
/// whole applied history ([`ArtifactStore::prefix_ring_capacity`]).
const PREFIX_SNAPSHOT_RING_CAPACITY: usize = 16;

/// 🪙️ The fewest prefix projections a store retains once its history is long enough to stride.
const PREFIX_SNAPSHOT_RING_FLOOR: usize = 8;

/// 🎟️ Displaced owners one reprojection displaces besides its message entries and prefix projections: the tail
/// snapshot and its id, `current`, the applied, redo and checkpoint owners, the supersessions, the revision bump and a
/// full prefix-ring prune.
const REPROJECTION_OWNER_SLOTS: usize = 10 + PREFIX_SNAPSHOT_RING_CAPACITY;
//#endregion 🔖️EditReplay

//#region 🔖️Backbone
//#region 🔖️Backbone
/// 📨️ Wire message exchanged over an attached backbone channel. B-R6 "kill hand-rolled binary
/// codecs": `#[derive(crate::os_dsl::DslOps)]` generates `OpBinary::encode_op`/`decode_op` (`format u8 (=1) |
/// variant ordinal varint | record body`, `crate::os_dsl::op_rt`) — this is the one real binary encoding for
/// every caller, including the wasm-sandbox `BackboneChannelPort` seam (see that trait's doc) — the
/// WIT `backbone-send`/`backbone-poll` host functions carry these exact bytes as `list<u8>`.
/// `Operations.envelopes` carries `crate::os_spr::encode_envelopes`/`decode_envelopes` bytes rather than a
/// real `Vec<crate::os_spr::MutationEnvelope>` field: `MutationEnvelope` lives in `protocol_causal`,
/// which sits BELOW `dsl` in the dependency graph (`dsl` → `protocol` → `protocol_causal`), so it
/// cannot implement `crate::os_dsl::DslField` without a dependency cycle — the derive can only lower fields
/// shaped from types it can see. `#[dsl(base64)]` marks each `Vec<u8>` field `Shape::Bytes64`
/// (otherwise a bare `Vec<u8>` lowers to a `List<UInt>`, one DSL list element per byte).
#[derive(Clone, Debug, PartialEq, semio_framework_dsl_record_derive::DslEnum)]
pub enum BackboneMessage {
    /// 🧬️ The document's initial snapshot pack — its identity, never its current state. A
    /// replica announces it before its event log; an empty persistence end adopts it as the genesis
    /// it stores, every other end verifies it names the same document.
    Genesis {
        #[dsl(base64)]
        pack: Vec<u8>,
    },
    /// ✉️ Semantic events — edit operations and history transitions — as causal envelopes.
    Mutations {
        #[dsl(base64)]
        envelopes: Vec<u8>,
    },
    /// ✅️ Acknowledges inbound operations the store has ingested (store→actor). Lets a future actor
    /// implement at-least-once redelivery with id-based dedupe — safe across store crashes/reloads.
    Ack { op_ids: Vec<String> },
    /// 🪆️ Semantic events authored on ONE composed member of this document, carrying that
    /// member's exact `(slot, child_id)` lane identity. A composed document has exactly one replica
    /// endpoint — the parent's backbone — so a child lane's edits can only cross under this tag, and
    /// the receiving replica folds them into ITS own member of the same lane, never into the parent.
    Member {
        slot: String,
        child_id: String,
        #[dsl(base64)]
        envelopes: Vec<u8>,
    },
    /// 🔙️ Retracts history transitions this replica authored and the hub refused (actor→store): each leaves the store's
    /// event log with every local transition causally depending on it ([`transition_retraction_closure`]), and the
    /// projection follows — the author converges with the hub, which never took them. No inverse exists for a
    /// transition; a retraction is the refusal's exact compensation.
    Retract { mutation_ids: Vec<String> },
}

//#region 🔖️OpCodec
/// 🎞️ Handcrafted OpText (P6).
impl OpText for BackboneMessage {
    fn parse_op(line: &str) -> Result<Self, TextError> {
        let variants = <Self as semio_framework_dsl_record::DslVariants>::variants();
        for (keyword, spec_fn) in &variants {
            let probe = format!("{} ", keyword);
            if line == keyword.as_str() || line.starts_with(&probe) {
                let record = semio_framework_dsl_record::parse(line, &(spec_fn.ordinary)(), &semio_framework_dsl_record::ParseOptions { limits: semio_framework_diagnostic::Limits::default(), mode: semio_framework_dsl_record::SourceMode::Inline })?;
                return <Self as semio_framework_dsl_record::DslVariants>::from_named_record(keyword, &record);
            }
        }
        Err(semio_framework_diagnostic::TextError::new(semio_framework_value::ValueRefusalKind::InvalidValue,(format!("unknown operation line '{line}'")).to_string(),semio_framework_diagnostic::TextSpan::at(1,1)))
    }
    fn print_op(&self) -> String {
        let (keyword, record) = <Self as semio_framework_dsl_record::DslVariants>::to_named_record(self);
        let variants = <Self as semio_framework_dsl_record::DslVariants>::variants();
        let spec_fn = variants.iter().find(|(k, _)| k == &keyword).map(|(_, s)| *s).expect("variant spec must exist for its own keyword");
        semio_framework_dsl_record::print(&record, &(spec_fn.ordinary)(), semio_framework_dsl_record::JoinMode::Inline)
    }
}

/// 🎯️ Handcrafted OpBinary (P6).
impl OpBinary for BackboneMessage {
    fn encode_op(&self) -> Result<Vec<u8>, crate::os_spr::ProtocolError> {
        crate::os_dsl::variants_binary::encode_op(self)
    }

    fn decode_op(bytes: &[u8]) -> Result<Self, crate::os_spr::ProtocolError> {
        crate::os_dsl::variants_binary::decode_op(bytes)
    }
}
//#endregion 🔖️OpCodec

pub const BACKBONE_HOT_MESSAGE_MAXIMUM_BYTES: usize = crate::os_spr::DOCUMENT_BACKBONE_BATCH_MAXIMUM_BYTES;
pub const BACKBONE_GENESIS_MESSAGE_MAXIMUM_BYTES: usize = 4 * 1024 * 1024;
pub const BACKBONE_CHANNEL_MAXIMUM_MESSAGES: usize = crate::os_spr::DOCUMENT_BACKBONE_PENDING_MAXIMUM_MESSAGES;
pub const BACKBONE_CHANNEL_MAXIMUM_BYTES: usize = crate::os_spr::DOCUMENT_BACKBONE_PENDING_MAXIMUM_BYTES;

pub fn decode_backbone_message_exact(bytes: &[u8]) -> Result<BackboneMessage, VcsError> {
    if bytes.len() > BACKBONE_GENESIS_MESSAGE_MAXIMUM_BYTES {
        return Err(VcsError::Deserialize("backbone message exceeds its fixed byte cap".into()));
    }
    BackboneMessage::decode_op(bytes).map_err(|error| VcsError::Deserialize(error.to_string()))
}

pub fn decode_hot_backbone_message_exact(bytes: &[u8]) -> Result<BackboneMessage, VcsError> {
    if bytes.len() > BACKBONE_HOT_MESSAGE_MAXIMUM_BYTES {
        return Err(VcsError::Deserialize("hot backbone message exceeds its fixed byte cap".into()));
    }
    let message = decode_backbone_message_exact(bytes)?;
    if matches!(message, BackboneMessage::Genesis { .. }) {
        return Err(VcsError::ValidationFailed("hot backbone transport refuses genesis packs; a hot replica is bootstrapped through the cold document pair".into()));
    }
    Ok(message)
}

/// 🧵️ Non-blocking, IO-free in-memory queue contract between a `ArtifactStore` and its
/// sync actor. `send`/`receive` MUST return immediately: implementations only enqueue/dequeue
/// `BackboneMessage`s — never HTTP, never filesystem, never a blocking wait. All IO (persistence,
/// semio_hub sync, file watching, presence) lives behind this queue in `framework/sync`'s actor layer,
/// which owns the other end; the store's `pump()`/`flush_outbound()` run synchronously on the
/// caller's thread and must never be blocked by transport work.
///
/// URI schemes are resolved by the host actor (`framework/sync`): `temp://` (in-memory),
/// `file://` (single JSON blob), `folder://` (sqlite `.semio/document.db`), `remote://` (OS semio_hub).
// 🧵️ No `Send`/`Sync` supertrait bound (R7 coordinator ruling 2026-08-19): this crate is
// guest-reachable and Send-ness comes structurally from the concrete `Backbones` enum at each spawn
// site, never from a bound named here.
pub trait Backbone {
    async fn descriptor(&self) -> ArtifactBackboneRef;
    async fn send(&mut self, message: BackboneMessage) -> Result<(), VcsError>;
    async fn receive(&mut self) -> Result<Vec<BackboneMessage>, VcsError>;
}

pub trait BackbonePort {
    async fn read(&self, uri: &str) -> Result<String, VcsError>;
    async fn write(&self, uri: &str, payload: &str) -> Result<(), VcsError>;
}

static HOST_BACKBONE_PORT: Mutex<Option<Arc<BackbonePorts>>> = Mutex::new(None);

/// 🔌️ Injects the browser or dev-server backbone port for wasm file/folder IO.
pub async fn set_host_backbone_port(port: Arc<BackbonePorts>) {
    if let Ok(mut guard) = HOST_BACKBONE_PORT.lock() {
        *guard = Some(port);
    }
}

async fn host_backbone_port() -> Option<Arc<BackbonePorts>> {
    HOST_BACKBONE_PORT.lock().ok().and_then(|guard| guard.clone())
}

#[derive(Default)]
pub struct MemoryBackbonePort {
    files: Mutex<HashMap<String, String>>,
}

impl MemoryBackbonePort {
    pub async fn new() -> Self {
        Self::default()
    }
}

impl BackbonePort for MemoryBackbonePort {
    async fn read(&self, uri: &str) -> Result<String, VcsError> {
        self.files.lock().map_err(|_| VcsError::Backbone("lock poisoned".into()))?.get(uri).cloned().ok_or_else(|| VcsError::Backbone(format!("missing backbone file {uri}")))
    }

    async fn write(&self, uri: &str, payload: &str) -> Result<(), VcsError> {
        self.files.lock().map_err(|_| VcsError::Backbone("lock poisoned".into()))?.insert(uri.to_string(), payload.to_string());
        Ok(())
    }
}

#[cfg(all(target_arch = "wasm32", not(target_env = "p2")))]
async fn local_storage_backbone_key(uri: &str) -> String {
    format!("semio:vcs:{uri}")
}

/// 💾️ Browser `localStorage` backbone port with in-memory fallback for native tests.
#[derive(Default)]
pub struct LocalStorageBackbonePort {
    fallback: MemoryBackbonePort,
}

impl LocalStorageBackbonePort {
    pub async fn new() -> Self {
        Self { fallback: MemoryBackbonePort::new().await }
    }
}

impl BackbonePort for LocalStorageBackbonePort {
    async fn read(&self, uri: &str) -> Result<String, VcsError> {
        if let Some(port) = host_backbone_port().await {
            if let Ok(value) = Box::pin(port.read(uri)).await {
                return Ok(value);
            }
        }
        #[cfg(all(target_arch = "wasm32", not(target_env = "p2")))]
        {
            if let Some(window) = web_sys::window() {
                if let Ok(Some(storage)) = window.local_storage() {
                    if let Ok(Some(value)) = storage.get_item(&local_storage_backbone_key(uri).await) {
                        return Ok(value);
                    }
                }
            }
        }
        self.fallback.read(uri).await
    }

    async fn write(&self, uri: &str, payload: &str) -> Result<(), VcsError> {
        self.fallback.write(uri, payload).await?;
        if let Some(port) = host_backbone_port().await {
            let _ = Box::pin(port.write(uri, payload)).await;
        }
        #[cfg(all(target_arch = "wasm32", not(target_env = "p2")))]
        {
            if let Some(window) = web_sys::window() {
                if let Ok(Some(storage)) = window.local_storage() {
                    let _ = storage.set_item(&local_storage_backbone_key(uri).await, payload);
                }
            }
        }
        Ok(())
    }
}

/// 🧬️ Enum dispatch over every `BackbonePort` implementor (O1 — dyn dispatch is dropped
/// repo-wide in favor of enum/generated dispatch). The trait stays as the contract; this enum
/// implements it by match-delegation so 🪐️space's blanket `impl<T: BackbonePort>
/// SpaceBackbonePort for T` keeps covering every concrete port through the enum too.
pub enum BackbonePorts {
    Memory(MemoryBackbonePort),
    LocalStorage(LocalStorageBackbonePort),
}

impl BackbonePort for BackbonePorts {
    async fn read(&self, uri: &str) -> Result<String, VcsError> {
        match self {
            Self::Memory(port) => port.read(uri).await,
            Self::LocalStorage(port) => port.read(uri).await,
        }
    }

    async fn write(&self, uri: &str, payload: &str) -> Result<(), VcsError> {
        match self {
            Self::Memory(port) => port.write(uri, payload).await,
            Self::LocalStorage(port) => port.write(uri, payload).await,
        }
    }
}

/// 🕸️ Injectable duplex transport across the wasm sandbox boundary (program ↔ host process).
/// `message`/the `poll` result are `BackboneMessage::encode_op`/`decode_op` (`crate::os_spr::OpBinary`) bytes.
pub trait BackboneChannelPort: Send + Sync {
    async fn send(&self, uri: &str, message: &[u8]) -> Result<(), VcsError>;
    async fn poll(&self, uri: &str) -> Result<Vec<Vec<u8>>, VcsError>;
}

struct ActorBackboneChannelState {
    uri: String,
    inbound: VecDeque<Vec<u8>>,
    outbound: VecDeque<Vec<u8>>,
    inbound_bytes: usize,
    outbound_bytes: usize,
    accepting: bool,
}

pub struct ActorBackboneChannelPort {
    state: Arc<Mutex<ActorBackboneChannelState>>,
}

#[derive(Clone)]
pub struct ActorBackboneChannelOwner {
    state: Arc<Mutex<ActorBackboneChannelState>>,
}

fn push_actor_backbone_outbound(state: &Arc<Mutex<ActorBackboneChannelState>>, uri: &str, message: &[u8]) -> Result<(), VcsError> {
    decode_hot_backbone_message_exact(message)?;
    let mut state = state.lock().map_err(|_| VcsError::Backbone("actor backbone channel lock poisoned".into()))?;
    if !state.accepting || state.uri != uri {
        return Err(VcsError::Backbone("actor backbone channel is retired or addressed to another URI".into()));
    }
    let next_bytes = state.outbound_bytes.checked_add(message.len()).ok_or_else(|| VcsError::Backbone("actor backbone outbound byte accounting overflow".into()))?;
    if state.outbound.len() >= BACKBONE_CHANNEL_MAXIMUM_MESSAGES || next_bytes > BACKBONE_CHANNEL_MAXIMUM_BYTES {
        return Err(VcsError::Backbone("actor backbone outbound queue is saturated".into()));
    }
    state.outbound.push_back(message.to_vec());
    state.outbound_bytes = next_bytes;
    Ok(())
}

impl ActorBackboneChannelOwner {
    pub fn pair(uri: &str) -> (Arc<BackboneChannelPorts>, Self) {
        let state = Arc::new(Mutex::new(ActorBackboneChannelState { uri: uri.to_string(), inbound: VecDeque::new(), outbound: VecDeque::new(), inbound_bytes: 0, outbound_bytes: 0, accepting: true }));
        (Arc::new(BackboneChannelPorts::Actor(ActorBackboneChannelPort { state: state.clone() })), Self { state })
    }

    pub fn admits_same_channel(&self, other: &Self) -> bool {
        Arc::ptr_eq(&self.state, &other.state)
    }

    pub fn push_inbound(&self, uri: &str, message: &[u8]) -> Result<(), VcsError> {
        decode_hot_backbone_message_exact(message)?;
        let mut state = self.state.lock().map_err(|_| VcsError::Backbone("actor backbone channel lock poisoned".into()))?;
        if !state.accepting || state.uri != uri {
            return Err(VcsError::Backbone("actor backbone channel is retired or addressed to another URI".into()));
        }
        let next_bytes = state.inbound_bytes.checked_add(message.len()).ok_or_else(|| VcsError::Backbone("actor backbone inbound byte accounting overflow".into()))?;
        if state.inbound.len() >= BACKBONE_CHANNEL_MAXIMUM_MESSAGES || next_bytes > BACKBONE_CHANNEL_MAXIMUM_BYTES {
            return Err(VcsError::Backbone("actor backbone inbound queue is saturated".into()));
        }
        state.inbound.push_back(message.to_vec());
        state.inbound_bytes = next_bytes;
        Ok(())
    }

    pub fn take_outbound(&self) -> Result<Option<Vec<u8>>, VcsError> {
        let mut state = self.state.lock().map_err(|_| VcsError::Backbone("actor backbone channel lock poisoned".into()))?;
        let message = state.outbound.pop_front();
        if let Some(message) = &message {
            state.outbound_bytes = state.outbound_bytes.saturating_sub(message.len());
        }
        Ok(message)
    }

    #[cfg(test)]
    pub fn push_outbound_for_test(&self, uri: &str, message: &[u8]) -> Result<(), VcsError> {
        push_actor_backbone_outbound(&self.state, uri, message)
    }

    pub fn begin_retire(&self) -> Result<(), VcsError> {
        let mut state = self.state.lock().map_err(|_| VcsError::Backbone("actor backbone channel lock poisoned".into()))?;
        state.accepting = false;
        state.inbound.clear();
        state.outbound.clear();
        state.inbound_bytes = 0;
        state.outbound_bytes = 0;
        Ok(())
    }

    pub fn terminal_is_empty(&self) -> Result<bool, VcsError> {
        let state = self.state.lock().map_err(|_| VcsError::Backbone("actor backbone channel lock poisoned".into()))?;
        Ok(!state.accepting && state.inbound.is_empty() && state.outbound.is_empty())
    }
}

pub enum BackboneChannelPorts {
    Actor(ActorBackboneChannelPort),
}

impl BackboneChannelPort for BackboneChannelPorts {
    async fn send(&self, uri: &str, message: &[u8]) -> Result<(), VcsError> {
        match self {
            Self::Actor(port) => push_actor_backbone_outbound(&port.state, uri, message),
        }
    }

    async fn poll(&self, uri: &str) -> Result<Vec<Vec<u8>>, VcsError> {
        match self {
            Self::Actor(port) => {
                let mut state = port.state.lock().map_err(|_| VcsError::Backbone("actor backbone channel lock poisoned".into()))?;
                if !state.accepting || state.uri != uri {
                    return Err(VcsError::Backbone("actor backbone channel is retired or addressed to another URI".into()));
                }
                state.inbound_bytes = 0;
                Ok(state.inbound.drain(..).collect())
            }
        }
    }
}

/// 🧵️ Backbone that forwards messages across the wasm sandbox boundary to the host process,
/// which resolves the real `file://`/`folder://`/`remote://` backbone on its own (native) side. The
/// channel is injected per instance via [`PortBackbone::with_channel`] — a pooled multi-instance
/// actor cannot share one process-global channel (see `important.md`'s "Replace, never wrap" list,
/// `set_host_backbone_channel`). No caller constructs a real channel yet (A2, `🔌️plugin/🦀️.rs`'s
/// `PLUGIN_INIT_ONCE` doc comment: the async `EffectBackbone` bridge is deferred work), so
/// [`PortBackbone::new`] leaves it unset and `send`/`receive` surface a real "no host backbone
/// linked" error rather than silently no-op'ing.
pub struct PortBackbone {
    uri: String,
    channel: Option<Arc<BackboneChannelPorts>>,
}

impl PortBackbone {
    pub async fn new(uri: &str) -> Self {
        Self { uri: uri.to_string(), channel: None }
    }

    pub async fn with_channel(uri: &str, channel: Arc<BackboneChannelPorts>) -> Self {
        Self { uri: uri.to_string(), channel: Some(channel) }
    }
}

impl Backbone for PortBackbone {
    async fn descriptor(&self) -> ArtifactBackboneRef {
        document_backbone_ref(&self.uri).await
    }

    async fn send(&mut self, message: BackboneMessage) -> Result<(), VcsError> {
        let channel = self.channel.as_ref().ok_or_else(|| VcsError::Backbone("backbone channel requires host port".into()))?;
        let bytes = message.encode_op().map_err(|error| VcsError::Serialize(error.to_string()))?;
        channel.send(&self.uri, &bytes).await
    }

    async fn receive(&mut self) -> Result<Vec<BackboneMessage>, VcsError> {
        let channel = self.channel.as_ref().ok_or_else(|| VcsError::Backbone("backbone channel requires host port".into()))?;
        let mut messages = Vec::new();
        for bytes in channel.poll(&self.uri).await? {
            messages.push(decode_hot_backbone_message_exact(&bytes)?);
        }
        Ok(messages)
    }
}

/// 🔗️ Two crossed in-memory channel ends: whatever `a` sends, `b` receives, and vice versa.
pub struct MemoryBackbone {
    uri: String,
    inbox: Option<Arc<Mutex<VecDeque<BackboneMessage>>>>,
    outbox: Option<Arc<Mutex<VecDeque<BackboneMessage>>>>,
}

impl MemoryBackbone {
    pub async fn pair(uri_a: &str, uri_b: &str) -> (Self, Self) {
        let a_to_b = Arc::new(Mutex::new(VecDeque::new()));
        let b_to_a = Arc::new(Mutex::new(VecDeque::new()));
        (Self { uri: uri_a.to_string(), inbox: Some(b_to_a.clone()), outbox: Some(a_to_b.clone()) }, Self { uri: uri_b.to_string(), inbox: Some(a_to_b), outbox: Some(b_to_a) })
    }
}

impl Backbone for MemoryBackbone {
    async fn descriptor(&self) -> ArtifactBackboneRef {
        document_backbone_ref(&self.uri).await
    }

    async fn send(&mut self, message: BackboneMessage) -> Result<(), VcsError> {
        self.outbox.as_ref().ok_or_else(|| VcsError::Backbone("memory backbone is closing".into()))?.lock().map_err(|_| VcsError::Backbone("lock poisoned".into()))?.push_back(message);
        Ok(())
    }

    async fn receive(&mut self) -> Result<Vec<BackboneMessage>, VcsError> {
        let mut inbox = self.inbox.as_ref().ok_or_else(|| VcsError::Backbone("memory backbone is closing".into()))?.lock().map_err(|_| VcsError::Backbone("lock poisoned".into()))?;
        Ok(inbox.drain(..).collect())
    }
}

/// 🔗️ The store-side end of a pair of crossed in-memory queues. Implements the non-blocking
/// {@link Backbone} contract; the matching {@link ChannelBackboneRemote} is held by an external sync
/// actor (built in `framework/sync`, a later workstream) that pushes inbound messages and drains the
/// store's outbound ones. This crate only provides the queue plumbing — never the actor itself.
pub struct ChannelBackbone {
    uri: String,
    inbound: Option<Arc<Mutex<VecDeque<BackboneMessage>>>>,
    outbound: Option<Arc<Mutex<VecDeque<BackboneMessage>>>>,
    outbound_wake: Arc<std::sync::OnceLock<Arc<dyn Fn() + Send + Sync>>>,
}

/// 🎛️ The actor-side end paired with a {@link ChannelBackbone}: `push` delivers a message to
/// the store's inbound queue, `try_pop_front` takes one exact outbound owner. Not a
/// `Backbone` — this is the handle an IO-owning actor endpoint holds across the store boundary.
pub struct ChannelBackboneRemote {
    uri: String,
    inbound: Arc<Mutex<VecDeque<BackboneMessage>>>,
    outbound: Arc<Mutex<VecDeque<BackboneMessage>>>,
    outbound_wake: Arc<std::sync::OnceLock<Arc<dyn Fn() + Send + Sync>>>,
}

impl ChannelBackbone {
    /// 🔗️ Creates a crossed pair sharing a URI: the store attaches the `ChannelBackbone`; the
    /// actor keeps the `ChannelBackboneRemote`.
    pub async fn pair(uri: &str) -> (ChannelBackbone, ChannelBackboneRemote) {
        let inbound = Arc::new(Mutex::new(VecDeque::new()));
        let outbound = Arc::new(Mutex::new(VecDeque::new()));
        let outbound_wake = Arc::new(std::sync::OnceLock::new());
        (ChannelBackbone { uri: uri.to_string(), inbound: Some(inbound.clone()), outbound: Some(outbound.clone()), outbound_wake: outbound_wake.clone() }, ChannelBackboneRemote { uri: uri.to_string(), inbound, outbound, outbound_wake })
    }
}

impl Backbone for ChannelBackbone {
    async fn descriptor(&self) -> ArtifactBackboneRef {
        document_backbone_ref(&self.uri).await
    }

    async fn send(&mut self, message: BackboneMessage) -> Result<(), VcsError> {
        self.outbound.as_ref().ok_or_else(|| VcsError::Backbone("channel backbone is closing".into()))?.lock().map_err(|_| VcsError::Backbone("lock poisoned".into()))?.push_back(message);
        if let Some(wake) = self.outbound_wake.get() {
            wake();
        }
        Ok(())
    }

    async fn receive(&mut self) -> Result<Vec<BackboneMessage>, VcsError> {
        let mut inbound = self.inbound.as_ref().ok_or_else(|| VcsError::Backbone("channel backbone is closing".into()))?.lock().map_err(|_| VcsError::Backbone("lock poisoned".into()))?;
        Ok(inbound.drain(..).collect())
    }
}

impl ChannelBackboneRemote {
    pub async fn descriptor(&self) -> ArtifactBackboneRef {
        document_backbone_ref(&self.uri).await
    }

    /// 📥️ Delivers a message to the store's inbound queue (actor→store).
    pub async fn push(&self, message: BackboneMessage) -> Result<(), VcsError> {
        self.inbound.lock().map_err(|_| VcsError::Backbone("lock poisoned".into()))?.push_back(message);
        Ok(())
    }

    /// 🔔️ Installs the actor's wake: every store→actor send resumes the actor that drains it,
    /// so an idle actor never sleeps on a queued outbound owner. Only the first install is kept.
    pub fn set_outbound_wake(&self, wake: Arc<dyn Fn() + Send + Sync>) {
        let _ = self.outbound_wake.set(wake);
    }

    /// 🪄️ Takes at most one store→actor message without a bulk collection or a
    /// blocking lock wait; contention preserves the exact queued owner for a later worker turn.
    pub fn try_pop_front(&self) -> Result<Option<BackboneMessage>, VcsError> {
        let mut outbound = self.outbound.try_lock().map_err(|error| match error {
            std::sync::TryLockError::WouldBlock => VcsError::Backbone("channel backbone outbound is contended".into()),
            std::sync::TryLockError::Poisoned(_) => VcsError::Backbone("lock poisoned".into()),
        })?;
        Ok(outbound.pop_front())
    }
}

/// 🧬️ Enum dispatch over every `Backbone` implementor (O1 — see `BackbonePorts`' doc comment
/// for why: every former `Box<dyn Backbone>` seam becomes `Backbones` by value, no box needed).
pub enum Backbones {
    Port(PortBackbone),
    Memory(MemoryBackbone),
    Channel(ChannelBackbone),
}

struct ArtifactStoreBackboneRetirement {
    backbone: std::mem::ManuallyDrop<Option<Backbones>>,
    queue: std::mem::ManuallyDrop<Option<VecDeque<BackboneMessage>>>,
    message: std::mem::ManuallyDrop<Option<BackboneMessage>>,
    bytes: std::mem::ManuallyDrop<Option<Vec<u8>>>,
}

impl ArtifactStoreBackboneRetirement {
    fn new(backbone: Backbones) -> Self {
        Self { backbone: std::mem::ManuallyDrop::new(Some(backbone)), queue: std::mem::ManuallyDrop::new(None), message: std::mem::ManuallyDrop::new(None), bytes: std::mem::ManuallyDrop::new(None) }
    }

    /// ♻️ Retires a buffered member-lane inbox on its own, without a transport to drain first.
    fn from_queue(queue: VecDeque<BackboneMessage>) -> Self {
        Self { backbone: std::mem::ManuallyDrop::new(None), queue: std::mem::ManuallyDrop::new(Some(queue)), message: std::mem::ManuallyDrop::new(None), bytes: std::mem::ManuallyDrop::new(None) }
    }

    fn take_string(value: &mut String) -> Option<Vec<u8>> {
        (!value.is_empty()).then(|| std::mem::take(value).into_bytes())
    }

    fn take_unique_queue(owner: &mut Option<Arc<Mutex<VecDeque<BackboneMessage>>>>) -> Result<Option<VecDeque<BackboneMessage>>, ()> {
        let Some(queue) = owner.take() else { return Ok(None) };
        match Arc::try_unwrap(queue) {
            Ok(queue) => Ok(Some(queue.into_inner().unwrap_or_else(std::sync::PoisonError::into_inner))),
            Err(queue) => {
                *owner = Some(queue);
                Err(())
            }
        }
    }
}

impl ErasedSnapshotRetirement for ArtifactStoreBackboneRetirement {
    fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<SnapshotRetirementStep, semio_framework_value::ValueError> {
        if maximum_items == 0 {
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        if let Some(bytes) = self.bytes.as_mut() {
            if bytes.is_empty() {
                drop(self.bytes.take());
                return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if maximum_bytes == 0 {
                return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
            }
            let released_bytes = maximum_bytes.min(bytes.len());
            bytes.truncate(bytes.len() - released_bytes);
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes });
        }
        if let Some(message) = self.message.as_mut() {
            match message {
                BackboneMessage::Genesis { pack } => {
                    if !pack.is_empty() {
                        *self.bytes = Some(std::mem::take(pack));
                        return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
                    }
                }
                BackboneMessage::Mutations { envelopes } => {
                    if !envelopes.is_empty() {
                        *self.bytes = Some(std::mem::take(envelopes));
                        return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
                    }
                }
                BackboneMessage::Ack { op_ids: ids } | BackboneMessage::Retract { mutation_ids: ids } => {
                    if let Some(id) = ids.pop() {
                        *self.bytes = Some(id.into_bytes());
                        return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
                    }
                }
                BackboneMessage::Member { slot, child_id, envelopes } => {
                    if !envelopes.is_empty() {
                        *self.bytes = Some(std::mem::take(envelopes));
                        return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
                    }
                    if let Some(bytes) = Self::take_string(slot) {
                        *self.bytes = Some(bytes);
                        return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
                    }
                    if let Some(bytes) = Self::take_string(child_id) {
                        *self.bytes = Some(bytes);
                        return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
                    }
                }
            }
            drop(self.message.take());
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if let Some(queue) = self.queue.as_mut() {
            if let Some(message) = queue.pop_front() {
                *self.message = Some(message);
                return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
            }
            drop(self.queue.take());
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        let Some(backbone) = self.backbone.as_mut() else { return Ok(SnapshotRetirementStep::Complete) };
        match backbone {
            Backbones::Port(backbone) => {
                if let Some(bytes) = Self::take_string(&mut backbone.uri) {
                    *self.bytes = Some(bytes);
                    return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
                }
                if let Some(channel) = backbone.channel.take() {
                    drop(channel);
                    return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
                }
            }
            Backbones::Memory(backbone) => {
                if let Some(bytes) = Self::take_string(&mut backbone.uri) {
                    *self.bytes = Some(bytes);
                    return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
                }
                match Self::take_unique_queue(&mut backbone.inbox) {
                    Ok(Some(queue)) => {
                        *self.queue = Some(queue);
                        return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
                    }
                    Err(()) => return Ok(SnapshotRetirementStep::Blocked),
                    Ok(None) => {}
                }
                match Self::take_unique_queue(&mut backbone.outbox) {
                    Ok(Some(queue)) => {
                        *self.queue = Some(queue);
                        return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
                    }
                    Err(()) => return Ok(SnapshotRetirementStep::Blocked),
                    Ok(None) => {}
                }
            }
            Backbones::Channel(backbone) => {
                if let Some(bytes) = Self::take_string(&mut backbone.uri) {
                    *self.bytes = Some(bytes);
                    return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
                }
                match Self::take_unique_queue(&mut backbone.inbound) {
                    Ok(Some(queue)) => {
                        *self.queue = Some(queue);
                        return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
                    }
                    Err(()) => return Ok(SnapshotRetirementStep::Blocked),
                    Ok(None) => {}
                }
                match Self::take_unique_queue(&mut backbone.outbound) {
                    Ok(Some(queue)) => {
                        *self.queue = Some(queue);
                        return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
                    }
                    Err(()) => return Ok(SnapshotRetirementStep::Blocked),
                    Ok(None) => {}
                }
            }
        }
        drop(self.backbone.take());
        Ok(SnapshotRetirementStep::Complete)
    }

    fn terminal_is_empty(&self) -> bool {
        self.backbone.is_none() && self.queue.is_none() && self.message.is_none() && self.bytes.is_none()
    }
}

impl Drop for ArtifactStoreBackboneRetirement {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || (self.terminal_is_empty()), "artifact store backbone retirement reached Drop before every exact URI, queue, message, channel, and byte owner was terminal-empty");
    }
}

impl Backbone for Backbones {
    async fn descriptor(&self) -> ArtifactBackboneRef {
        match self {
            Self::Port(backbone) => backbone.descriptor().await,
            Self::Memory(backbone) => backbone.descriptor().await,
            Self::Channel(backbone) => backbone.descriptor().await,
        }
    }

    async fn send(&mut self, message: BackboneMessage) -> Result<(), VcsError> {
        match self {
            Self::Port(backbone) => backbone.send(message).await,
            Self::Memory(backbone) => backbone.send(message).await,
            Self::Channel(backbone) => backbone.send(message).await,
        }
    }

    async fn receive(&mut self) -> Result<Vec<BackboneMessage>, VcsError> {
        match self {
            Self::Port(backbone) => backbone.receive().await,
            Self::Memory(backbone) => backbone.receive().await,
            Self::Channel(backbone) => backbone.receive().await,
        }
    }
}

/// 🔌️ Resolves a backbone URI to a concrete channel implementation. Only available inside the
/// wasm sandbox, where every scheme forwards to the host process over the injected
/// {@link BackboneChannelPort} (a pure in-memory queue). Native IO-performing backbones moved out of
/// this crate entirely — the `framework/sync` actor layer owns them.
#[cfg(target_arch = "wasm32")]
pub async fn resolve_backbone(uri: &str) -> Result<Backbones, VcsError> {
    Ok(Backbones::Port(PortBackbone::new(uri).await))
}
