};
use semio_framework_ui_scene::{scene_lane_hash, Board2dScene, Board2dSceneLane, Canvas2dScene, Canvas2dSceneLane, SceneDoc, SceneLaneRef, World3dScene, World3dSceneLane};
use std::collections::BTreeMap;
use std::sync::Arc;

//#region 🔖️Limits
/// 🪧️ Framework-owned panel body served before any app body, next to `FRAMEWORK_HISTORY_BODY_KEY`.
pub const FRAMEWORK_TOOL_RUN_BODY_KEY: &str = "framework.body.toolRun";
/// ⏱️ Wall budget of one driver turn; every job step inside it keeps its own interactive-lane slice.
pub const TOOL_RUN_TURN_WALL_US: u64 = 4_000;
/// 🧮️ Folded ops between two wall-clock checks of a bounded refold.
pub const TOOL_RUN_REFOLD_CHECK_OPS: usize = 64;
/// 🧹️ Discarded provisional ops cold-retired per driver or close turn.
pub const TOOL_RUN_DISCARD_OPS_PER_TURN: usize = 4_096;
/// 📜️ Newest step-log rows the panel shows.
pub const TOOL_RUN_PANEL_STEP_ROWS: usize = 16;
/// 🧾️ Newest trace records the panel's keyboard trace list shows.
pub const TOOL_RUN_PANEL_TRACE_ROWS: usize = 32;
/// 📦️ Encoded trace delta bytes one renderer refresh receives.
pub const TOOL_RUN_TRACE_DELTA_BYTES: usize = 262_144;
/// 🔁️ Refreshes one window may re-request a trace backlog while its renderer's echoed cursor stands still;
/// a renderer that never echoes therefore costs a bounded number of refreshes, never a refresh loop.
pub const TOOL_RUN_TRACE_STALL_REFRESHES: u8 = 4;
const TOOL_RUN_JOB_SITE: &str = "tool-run.step";
const TOOL_RUN_PUBLICATION_GRANT: store::ArtifactStoreOneItemGrant = store::ArtifactStoreOneItemGrant { maximum_items: 1, maximum_bytes: TYPED_OPERATION_RESULT_PAGE_BYTES };
//#endregion 🔖️Limits

//#region 🔖️Selection
/// 🎯️ The run the ledger currently operates on (`ToolRunLedger::selected`), borrowing only `entries`.
macro_rules! selected_entry {
    ($ledger:expr) => {
        $ledger.selected.and_then(|index| $ledger.entries.get(index)).map(|entry| &**entry)
    };
}

/// 🎯️ The run the ledger currently operates on, mutably, borrowing only `entries`.
macro_rules! selected_entry_mut {
    ($ledger:expr) => {
        match $ledger.selected {
            Some(index) => $ledger.entries.get_mut(index).map(|entry| &mut **entry),
            None => None,
        }
    };
}
//#endregion 🔖️Selection

//#region 🔖️Request
/// 🎯️ Which job of a run the app builds.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ToolRunJobPurpose {
    Run,
    Revalidate,
}

/// 🧵️ A boxed run or revalidate job; it reports `ToolRunTick` pages via `StepOutcome::PreviewReady`. `Send`
/// explicitly: the browser target's `InteractiveJob` drops its thread-transfer bound, but the ledger lives
/// in a `PluginApp`, which stays `Send` on every target.
pub type ToolRunJob = Box<dyn semio_framework_job::InteractiveJob + Send>;

/// 🧳️ Everything an app needs to build one run or revalidate job (§3.7).
///
/// - `snapshot` is the run's base for `Run` and the committed head for `Revalidate`.
/// - `window_id` is the window instance the run was started from (`toolRunStart`'s `windowId`, else the
///   dispatching view's window), and `window_config` that window's config snapshot as of this build.
/// - `checkpoint` is the last `StepOutcome::CheckpointReady` state of this run (reconfigure `resume`).
/// - `provisional` is the provisional op list the job continues from or revalidates.
/// - `instance_owner` is the instance's retained operation owner, shared with its commands.
/// - `port` carries the host effects the job asks for and the wake of a job waiting on them.
/// - `trace_keys` allocates trace keys no record of this run uses, e.g. one per placement a revalidate job
///   re-tests; every job of the run shares it, so keys never collide across rebuilds and purposes.
/// - `entity_marks` holds `(provisional length at the end of the tick that appended it, entity)` per entity, in
///   append order: which provisional op prefix each placement's entity belongs to.
/// - `children` is the composed read the job runs on: the live owned children, whose member a member run
///   (`ToolRunDefinition::member`) edits.
/// - `member_ops` is a member run's provisional op list (that member's `OpBinary` ops), the one the job continues
///   from or revalidates; empty for a run on the document's own store.
pub struct ToolRunJobRequest<'a, A: ArtifactApp> {
    pub tool_id: &'a str,
    pub definition: &'a ToolRunDefinition,
    pub purpose: ToolRunJobPurpose,
    pub identity: ToolRunIdentity,
    pub snapshot: Arc<A::Snapshot>,
    pub config: Arc<A::Config>,
    pub window_id: Option<&'a str>,
    pub window_config: Option<WindowConfigSnapshot>,
    pub checkpoint: Option<&'a [u8]>,
    pub provisional: &'a [A::Mutation],
    pub instance_owner: ArtifactInstanceOperationOwnerHandle,
    pub port: ToolRunJobPort,
    pub trace_keys: ToolRunTraceKeys,
    pub entity_marks: &'a [(u32, u64)],
    pub children: ChildContentView,
    pub member_ops: &'a [Vec<u8>],
}

/// 🔑️ The trace key allocator every job of one run shares: keys handed out lie above every key the run's
/// ticks have upserted and every key allocated before.
#[derive(Clone, Debug, Default)]
pub struct ToolRunTraceKeys {
    next: Arc<std::sync::atomic::AtomicU64>,
}

impl ToolRunTraceKeys {
    /// 🔢️ The first key neither upserted by this run nor allocated.
    pub fn next(&self) -> u64 {
        self.next.load(std::sync::atomic::Ordering::SeqCst)
    }

    /// 🎟️ Reserves `count` consecutive unused keys.
    pub fn allocate(&self, count: u64) -> std::ops::Range<u64> {
        let start = self.next.try_update(std::sync::atomic::Ordering::SeqCst, std::sync::atomic::Ordering::SeqCst, |next| Some(next.saturating_add(count))).unwrap_or_else(|next| next);
        start..start.saturating_add(count)
    }

    fn observe(&self, key: u64) {
        self.next.fetch_max(key.saturating_add(1), std::sync::atomic::Ordering::SeqCst);
    }
}

/// 🎯️ The in-place retarget hooks of the tool run job protocol (§3.3). A job built through
/// `ArtifactApp::build_retargetable_tool_run_job` stays resident across a base change and a settings change —
/// and while its run is `complete` — instead of being closed and rebuilt from its checkpoint.
pub trait ToolRunRetargetableJob<C>: semio_framework_job::InteractiveJob + Send {
    /// 🪢️ Every tick after this call carries `identity` (base changed: new generation and base revision).
    fn rebind(&mut self, identity: ToolRunIdentity);
    /// 🎚️ Retargets the job to `config` under `identity`; `false` when it cannot continue in place, and the
    /// driver then closes it and rebuilds it from its checkpoint.
    fn reconfigure(&mut self, identity: ToolRunIdentity, config: Arc<C>) -> bool;
}

/// 📮️ What a run job shares with its app instance across turns: the host effects it hands the driver (an
/// extension round trip whose answer returns as an app command cannot happen inside `step`) and the external
/// wake of a job waiting on such work. A waiting job is never stepped and keeps its instance idle, so waiting
/// costs no turn; whoever folds the awaited answer calls [`ToolRunJobPort::wake`].
#[derive(Clone, Default)]
pub struct ToolRunJobPort {
    inner: Arc<ToolRunJobPortState>,
}

#[derive(Default)]
struct ToolRunJobPortState {
    effects: std::sync::Mutex<std::collections::VecDeque<Effect>>,
    waiting: std::sync::atomic::AtomicBool,
}

impl ToolRunJobPort {
    /// 📨️ Queues one effect the driver hands the host on its next turn, in order.
    pub fn dispatch(&self, effect: Effect) {
        if let Ok(mut effects) = self.inner.effects.lock() {
            effects.push_back(effect);
        }
    }

    /// ⏸️ The job's next step makes no progress until [`ToolRunJobPort::wake`]; set it while holding whatever
    /// lock the waker folds its answer under, so no wake can slip between the decision and the flag.
    pub fn wait(&self) {
        self.inner.waiting.store(true, std::sync::atomic::Ordering::SeqCst);
    }

    /// ⏰️ Makes a waiting job runnable again.
    pub fn wake(&self) {
        self.inner.waiting.store(false, std::sync::atomic::Ordering::SeqCst);
    }

    pub fn is_waiting(&self) -> bool {
        self.inner.waiting.load(std::sync::atomic::Ordering::SeqCst)
    }

    pub fn has_effects(&self) -> bool {
        self.inner.effects.lock().is_ok_and(|effects| !effects.is_empty())
    }

    fn pop_effect(&self) -> Option<Effect> {
        self.inner.effects.lock().ok()?.pop_front()
    }

    fn restore_effect(&self, effect: Effect) {
        if let Ok(mut effects) = self.inner.effects.lock() {
            effects.push_front(effect);
        }
    }
}

/// 🪟️ What a renderer learns about the run on this document instance (§4.1 layer 1): its identity and state, the
/// provisional entities, the §2.3 progress (stage, counters, step ring) and the latest plugin payload a tick carried.
#[derive(Clone, Debug, PartialEq)]
pub struct ToolRunView {
    pub tool_id: String,
    pub identity: ToolRunIdentity,
    pub state: ToolRunState,
    pub provisional_entities: Arc<BTreeSet<u64>>,
    pub progress: semio_framework_tool_run::ToolRunProgress,
    pub payload: Option<Arc<[u8]>>,
}

impl ToolRunView {
    /// 🏗️ A view of a run with no provisional entities, no progress yet and no payload.
    pub fn new(tool_id: impl Into<String>, identity: ToolRunIdentity, state: ToolRunState) -> Self {
        let progress = semio_framework_tool_run::ToolRunProgress { identity, sequence: 0, state, stage: 0, completed: 0, total: None, counters: Vec::new(), units_per_second: 0.0, conflicts: 0, steps: ToolRunStepRing::new() };
        Self { tool_id: tool_id.into(), identity, state, provisional_entities: Arc::new(BTreeSet::new()), progress, payload: None }
    }
}

/// 🔖️ True for the seven framework-reserved tool run action ids (§2.5).
pub fn is_tool_run_action_id(action: &str) -> bool {
    TOOL_RUN_ACTION_IDS.contains(&action)
}
//#endregion 🔖️Request

//#region 🔖️Job
enum ToolRunJobHandle<C> {
    Plain(ToolRunJob),
    Retargetable(Box<dyn ToolRunRetargetableJob<C>>),
}

struct ToolRunJobSlot<C> {
    job: ToolRunJobHandle<C>,
    purpose: ToolRunJobPurpose,
    operation: semio_framework_job::OperationId,
    generation: semio_framework_job::Generation,
    cancel: semio_framework_job::CancelToken,
    preview_sequence: u64,
    closing: bool,
}

impl<C> ToolRunJobSlot<C> {
    fn new(job: ToolRunJobHandle<C>, purpose: ToolRunJobPurpose, generation: u32) -> Self {
        Self { job, purpose, operation: semio_framework_job::allocate_operation_id(), generation: semio_framework_job::Generation(u64::from(generation)), cancel: semio_framework_job::CancelToken::root_now(), preview_sequence: 0, closing: false }
    }

    fn interactive(&mut self) -> &mut dyn semio_framework_job::InteractiveJob {
        match &mut self.job {
            ToolRunJobHandle::Plain(job) => job.as_mut(),
            ToolRunJobHandle::Retargetable(job) => job.as_mut(),
        }
    }

    fn terminal_is_empty(&self) -> bool {
        match &self.job {
            ToolRunJobHandle::Plain(job) => job.terminal_is_empty(),
            ToolRunJobHandle::Retargetable(job) => job.terminal_is_empty(),
        }
    }

    fn retargetable(&mut self) -> Option<&mut dyn ToolRunRetargetableJob<C>> {
        match &mut self.job {
            ToolRunJobHandle::Retargetable(job) if !self.closing => Some(job.as_mut()),
            _ => None,
        }
    }

    fn begin_close(&mut self) {
        if !self.closing {
            self.cancel.cancel_now();
            self.interactive().begin_close();
            self.closing = true;
        }
    }

    fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<Option<PluginCloseStep>, Fault> {
        self.begin_close();
        match self.interactive().close_step(maximum_items.max(1), maximum_bytes) {
            semio_framework_job::InteractiveJobCloseStep::Pending { released_items, released_bytes } => Ok(Some(PluginCloseStep::Pending { released_items, released_bytes })),
            semio_framework_job::InteractiveJobCloseStep::Blocked => Ok(Some(PluginCloseStep::Blocked { reason: "tool run job close is blocked" })),
            semio_framework_job::InteractiveJobCloseStep::Complete if self.terminal_is_empty() => Ok(None),
            semio_framework_job::InteractiveJobCloseStep::Complete => Err(Fault::new(FaultOrigin::Framework, FaultCode::new("toolRun.job-close"), "tool run job reported Complete without its terminal-empty witness")),
        }
    }
}

fn close_job_payload(payload: &mut semio_framework_job::RetainedJobPayload) {
    while let semio_framework_job::JobPayloadCloseStep::Pending { released_items: 1, .. } = payload.close_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES) {}
}

fn job_payload_bytes(payload: &semio_framework_job::RetainedJobPayload, limit: usize) -> Option<Vec<u8>> {
    if payload.len() > limit {
        return None;
    }
    let mut bytes = Vec::with_capacity(payload.len());
    for index in 0..payload.page_count() {
        bytes.extend_from_slice(payload.page(index)?);
    }
    Some(bytes)
}

/// 📼️ Lane text of one delta: `None` for an empty, non-clearing delta, else its base64url (unpadded) pack body.
fn tool_run_trace_lane_text(delta: &ToolRunTraceDelta) -> Option<String> {
    if !delta.clear && delta.pages.is_empty() {
        return None;
    }
    delta.encode().ok().map(base64_codec::base64_url_encode)
}

/// 🔎️ The first World3d, Canvas2d or Board2d scene surface of a rendered body, depth first.
fn tool_run_scene_surface(node: &mut BuiltNode) -> Option<&mut BuiltNode> {
    let is_scene = matches!(&node.component, Component::Surface(props) if [World3dScene::SCHEMA, Canvas2dScene::SCHEMA, Board2dScene::SCHEMA].contains(&props.doc_schema.as_str()));
    if is_scene {
        return Some(node);
    }
    node.children.iter_mut().find_map(tool_run_scene_surface)
}

/// 📎️ Re-attaches `lane` to a scene surface: the spine's lane refs gain the `toolRunTrace` entry and the
/// surface gains its paged carrier, exactly as `SceneDoc::split_lanes` plus `scene_surface` would emit it.
/// A surface whose producer already carries the lane is left untouched.
fn inject_tool_run_trace_lane_into(surface: &mut BuiltNode, lane: &str) -> UiAssemblyResult<()> {
    let Component::Surface(props) = &mut surface.component else { return Ok(()) };
    let (name, key) = match props.doc_schema.as_str() {
        World3dScene::SCHEMA => (World3dSceneLane::ToolRunTrace.name(), World3dSceneLane::ToolRunTrace.body_key()),
        Board2dScene::SCHEMA => (Board2dSceneLane::ToolRunTrace.name(), Board2dSceneLane::ToolRunTrace.body_key()),
        _ => (Canvas2dSceneLane::ToolRunTrace.name(), Canvas2dSceneLane::ToolRunTrace.body_key()),
    };
    if surface.children.iter().any(|child| child.key.as_str() == key) {
        return Ok(());
    }
    let reference = SceneLaneRef { lane: name.to_string(), bytes: lane.len() as u32, hash: scene_lane_hash(lane) };
    let encoded = match props.doc_schema.as_str() {
        World3dScene::SCHEMA => {
            let mut spine: World3dScene = semio_framework_ui_scene::decode(props).map_err(|error| ui_assembly_error_because("tool-run-trace.decode", error))?;
            spine.lanes.push(reference);
            semio_framework_ui_scene::encode(props.kind, &spine)
        }
        Board2dScene::SCHEMA => {
            let mut spine: Board2dScene = semio_framework_ui_scene::decode(props).map_err(|error| ui_assembly_error_because("tool-run-trace.decode", error))?;
            spine.lanes.push(reference);
            semio_framework_ui_scene::encode(props.kind, &spine)
        }
        _ => {
            let mut spine: Canvas2dScene = semio_framework_ui_scene::decode(props).map_err(|error| ui_assembly_error_because("tool-run-trace.decode", error))?;
            spine.lanes.push(reference);
            semio_framework_ui_scene::encode(props.kind, &spine)
        }
    };
    let mut encoded = encoded.map_err(|error| ui_assembly_error_because("tool-run-trace.encode", error))?;
    let carrier = paged_text_carrier(key, lane)?;
    if surface.children.len() == UI_BUILT_CHILDREN_MAX {
        return Err(ui_assembly_error("tool-run-trace.carrier"));
    }
    encoded.bindings = std::mem::take(&mut props.bindings);
    *props = encoded;
    surface.children.try_push(carrier).map_err(|_| ui_assembly_error("tool-run-trace.carrier"))
}

fn close_step_outcome(outcome: &mut semio_framework_job::StepOutcome) {
    while let semio_framework_job::JobPayloadCloseStep::Pending { released_items: 1, .. } = outcome.close_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES) {}
}
//#endregion 🔖️Job

//#region 🔖️Ledger
/// 🔁️ A bounded refold of the provisional ops from `base`. `boundary` is whether the job reached a point where
/// the refolded overlay is whole: a retract refold waits for the job's next checkpoint, completion or close,
/// so a retract followed by re-appends spread over several ticks never renders a half re-appended overlay —
/// the previous overlay stays rendered until then.
struct ToolRunRefold<P> {
    running: Option<P>,
    cursor: usize,
    boundary: bool,
}

/// 🚦️ Where one refold turn left the overlay.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ToolRunRefoldTurn {
    Pending,
    AwaitingBoundary,
    Swapped,
}

/// 🎚️ The values a run's declared settings reads named when last observed: config pointers, then per declared
/// window kind the `(window id, values)` of every partition it reads.
#[derive(Clone, Debug, Default, PartialEq)]
struct ToolRunSettingsValues {
    config: Vec<Option<DslValue>>,
    window_config: Vec<(String, String, Vec<Option<DslValue>>)>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ToolRunFinalizePhase {
    Pending,
    Revalidating,
    Publishing,
    Closing,
}

struct ToolRunFinalize<A: ArtifactApp> {
    phase: ToolRunFinalizePhase,
    publication: Option<store::ArtifactStoreBatchPublication<A::Snapshot, A::Mutation>>,
    retracted: u32,
    published: bool,
}

struct ToolRunEntry<A: ArtifactApp> {
    tool_id: String,
    actor: String,
    definition: ToolRunDefinition,
    slot: ToolRunSlot,
    identity: ToolRunIdentity,
    base: Arc<A::Snapshot>,
    base_generation: u64,
    settings_generation: (u64, u64),
    settings_values: ToolRunSettingsValues,
    window: Option<(String, String)>,
    window_bodies: Vec<String>,
    payload: Option<Arc<[u8]>>,
    trace_keys: ToolRunTraceKeys,
    provisional: Vec<A::Mutation>,
    entity_marks: Vec<(u32, u64)>,
    entities: Arc<BTreeSet<u64>>,
    overlay: Arc<A::Snapshot>,
    refold: Option<ToolRunRefold<A::Snapshot>>,
    trace: ToolRunTraceStore,
    recent_trace: std::collections::VecDeque<u64>,
    stage: u16,
    completed: u64,
    total: Option<u64>,
    counters: Vec<ToolRunCounter>,
    steps: ToolRunStepRing,
    step_sequence: u64,
    sequence: u64,
    conflicts: u32,
    rate_origin: Option<(u64, u64)>,
    units_per_second: f32,
    job: Option<ToolRunJobSlot<A::Config>>,
    checkpoint: Option<Vec<u8>>,
    pending_step: bool,
    finalize: Option<ToolRunFinalize<A>>,
    announced: Option<(ToolRunState, u64, String)>,
    port: ToolRunJobPort,
    /// ♻️ Snapshot aliases this run let go (a replaced base or overlay, a superseded fold result), owed to the store's
    /// alias retirement ([`ToolRunLedger::retire_step`]); never dropped plainly.
    displaced: Vec<Arc<A::Snapshot>>,
    /// 🧩️ The owned member a member run edits (`ToolRunDefinition::member`); `None` for a run on the document's store.
    member: Option<ToolRunMemberRun>,
}

impl<A: ArtifactApp> ToolRunEntry<A> {
    /// 🛣️ The lane this run occupies: the mutating lane, or its tool on its starting window when read-only.
    fn lane(&self) -> ToolRunLane {
        ToolRunLane { mutating: self.definition.mutating, tool_id: self.tool_id.clone(), window_id: if self.definition.mutating { None } else { self.window.as_ref().map(|(window_id, _)| window_id.clone()) } }
    }

    fn view(&self) -> ToolRunView {
        ToolRunView { tool_id: self.tool_id.clone(), identity: self.identity, state: self.slot.state, provisional_entities: Arc::clone(&self.entities), progress: self.progress(), payload: self.payload.clone() }
    }

    fn progress(&self) -> semio_framework_tool_run::ToolRunProgress {
        semio_framework_tool_run::ToolRunProgress {
            identity: self.identity,
            sequence: self.sequence,
            state: self.slot.state,
            stage: self.stage,
            completed: self.completed,
            total: self.total,
            counters: self.counters.clone(),
            units_per_second: self.units_per_second,
            conflicts: self.conflicts,
            steps: self.steps.clone(),
        }
    }

    /// 🏃️ Whether a driver turn has work for this run; a job waiting on its port is not work.
    fn has_pending_work(&self) -> bool {
        let stepping = self.job.is_none() || !self.port.is_waiting();
        self.port.has_effects()
            || self.refold_is_work()
            || !self.displaced.is_empty()
            || self.member.as_ref().is_some_and(ToolRunMemberRun::is_work)
            || match self.slot.state {
                ToolRunState::Running => stepping,
                ToolRunState::Starting | ToolRunState::Finalizing | ToolRunState::Aborting => true,
                ToolRunState::Paused => self.pending_step && stepping,
                ToolRunState::Complete => false,
                _ => self.job.is_some(),
            }
    }

    fn framework_step(&mut self, kind: ToolRunStepKind, reason: u16, args: &[ToolRunStepArg]) {
        self.step_sequence = self.step_sequence.saturating_add(1);
        self.steps.push(ToolRunStep { sequence: self.step_sequence, kind, stage: self.stage, reason, subject: None, repeat: 1, args: args.to_vec() });
    }

    fn begin_refold(&mut self, boundary: bool) {
        if let Some(running) = self.refold.replace(ToolRunRefold { running: None, cursor: 0, boundary }).and_then(|refold| refold.running) {
            self.displaced.push(Arc::new(running));
        }
    }

    /// ♻️ Replaces the overlay, owing the previous one to the store's alias retirement.
    fn replace_overlay(&mut self, overlay: Arc<A::Snapshot>) {
        let previous = std::mem::replace(&mut self.overlay, overlay);
        self.displaced.push(previous);
    }

    /// ♻️ Replaces the base, owing the previous one to the store's alias retirement.
    fn replace_base(&mut self, base: Arc<A::Snapshot>) {
        let previous = std::mem::replace(&mut self.base, base);
        self.displaced.push(previous);
    }

    /// 🏁️ The job reached a point where the refolded overlay is whole.
    fn settle_refold(&mut self) {
        if let Some(refold) = self.refold.as_mut() {
            refold.boundary = true;
        }
    }

    fn refold_is_work(&self) -> bool {
        self.refold.as_ref().is_some_and(|refold| refold.boundary || refold.cursor < self.provisional.len())
    }

    fn rebind(&mut self) {
        self.identity.generation = self.slot.generation;
        self.trace.rebind(self.identity);
    }

    fn rebuild_entities(&mut self) {
        let length = self.provisional.len() as u32;
        self.entity_marks.retain(|(end, _)| *end <= length);
        self.entities = Arc::new(self.entity_marks.iter().map(|(_, entity)| *entity).collect());
    }

    fn fold_one(snapshot: &A::Snapshot, op: &A::Mutation) -> Option<A::Snapshot> {
        let outcome = op.diff(snapshot);
        if !outcome.is_applicable(protocol::MergePolicy::default()) {
            return None;
        }
        outcome.diff().apply(snapshot).ok()
    }

    /// 🔁️ Folds provisional ops from `base` until the wall deadline; the overlay is replaced once every op is
    /// folded and the refold reached its boundary.
    fn refold_turn(&mut self, deadline_us: u64) -> ToolRunRefoldTurn {
        let Some(mut refold) = self.refold.take() else { return ToolRunRefoldTurn::Swapped };
        while refold.cursor < self.provisional.len() {
            let source = refold.running.as_ref().unwrap_or(&self.base);
            match Self::fold_one(source, &self.provisional[refold.cursor]) {
                Some(next) => {
                    if let Some(previous) = refold.running.replace(next) {
                        self.displaced.push(Arc::new(previous));
                    }
                }
                None => self.conflicts = self.conflicts.saturating_add(1),
            }
            refold.cursor += 1;
            if refold.cursor % TOOL_RUN_REFOLD_CHECK_OPS == 0 && semio_framework_job::default_now_us().is_none_or(|now| now >= deadline_us) {
                self.refold = Some(refold);
                return ToolRunRefoldTurn::Pending;
            }
        }
        if !refold.boundary {
            self.refold = Some(refold);
            return ToolRunRefoldTurn::AwaitingBoundary;
        }
        let overlay = refold.running.map_or_else(|| Arc::clone(&self.base), Arc::new);
        self.replace_overlay(overlay);
        ToolRunRefoldTurn::Swapped
    }

    /// 🧬️ Applies one tick of the current identity: retract, append (O(k) fold), entities, steps, progress, trace.
    fn apply_tick(&mut self, mut tick: ToolRunTick, discarded: &mut Vec<A::Mutation>) -> Result<ToolRunTickReceipt, Fault> {
        let mut receipt = ToolRunTickReceipt::default();
        if tick.identity.id != self.identity.id || tick.identity.generation != self.identity.generation {
            receipt.stale = true;
            return Ok(receipt);
        }
        if let Some(payload) = tick.payload.take() {
            self.payload = Some(payload.into());
        }
        self.sequence = self.sequence.max(tick.sequence);
        if let Some(member) = self.member.as_mut() {
            if let Some(retract) = tick.retract_to.map(|length| length as usize).filter(|length| *length < member.ops.len()) {
                receipt.retracted = (member.ops.len() - retract) as u32;
                member.ops.truncate(retract);
                member.rebase = true;
            }
            let room = (TOOL_RUN_MEMBER_OPS_MAX as usize).saturating_sub(member.ops.len());
            receipt.capped = tick.append_ops.len() > room;
            receipt.appended = tick.append_ops.len().min(room) as u32;
            member.ops.extend(tick.append_ops.drain(..).take(room));
            let length = member.ops.len() as u32;
            self.entity_marks.retain(|(end, _)| *end <= length);
            self.entities = Arc::new(self.entity_marks.iter().map(|(_, entity)| *entity).collect());
        } else if let Some(retract) = tick.retract_to.map(|length| length as usize).filter(|length| *length < self.provisional.len()) {
            receipt.retracted = (self.provisional.len() - retract) as u32;
            discarded.extend(self.provisional.drain(retract..));
            self.rebuild_entities();
            self.begin_refold(false);
        }
        let mut appended = Vec::with_capacity(tick.append_ops.len());
        for bytes in &tick.append_ops {
            if self.provisional.len() + appended.len() >= TOOL_RUN_PROVISIONAL_OPS_MAX as usize {
                receipt.capped = true;
                break;
            }
            appended.push(<A::Mutation as ::protocol::OpBinary>::decode_op(bytes).map_err(|error| error.into_fault())?);
        }
        if self.refold.is_none() && !appended.is_empty() {
            let mut running: Option<A::Snapshot> = None;
            for op in &appended {
                match Self::fold_one(running.as_ref().unwrap_or(&self.overlay), op) {
                    Some(next) => {
                        if let Some(previous) = running.replace(next) {
                            self.displaced.push(Arc::new(previous));
                        }
                    }
                    None => self.conflicts = self.conflicts.saturating_add(1),
                }
            }
            if let Some(running) = running {
                self.replace_overlay(Arc::new(running));
            }
        }
        receipt.appended += appended.len() as u32;
        self.provisional.extend(appended);
        let end = self.member.as_ref().map_or(self.provisional.len(), |member| member.ops.len()) as u32;
        if !tick.append_entities.is_empty() {
            let entities = Arc::make_mut(&mut self.entities);
            for entity in tick.append_entities {
                self.entity_marks.push((end, entity));
                entities.insert(entity);
            }
        }
        for mut step in tick.steps {
            self.step_sequence = self.step_sequence.saturating_add(1);
            step.sequence = self.step_sequence;
            self.steps.push(step);
        }
        if let Some(progress) = tick.progress {
            self.stage = progress.stage;
            self.total = progress.total;
            self.completed = progress.total.map_or(progress.completed, |total| progress.completed.min(total));
            self.counters = progress.counters;
        }
        for page in &tick.trace {
            let applied = self.trace.apply_page(page).map_err(|rejection| Fault::new(FaultOrigin::Framework, FaultCode::new(rejection.code()), "tool run trace page does not belong to the current run generation"))?;
            receipt.evicted = receipt.evicted.saturating_add(applied.evicted);
            receipt.capped |= applied.overflowed > 0;
            for op in &page.ops {
                match op {
                    ToolRunTraceOp::Upsert { key, .. } => {
                        self.trace_keys.observe(*key);
                        self.recent_trace.retain(|recent| recent != key);
                        if self.recent_trace.len() == TOOL_RUN_PANEL_TRACE_ROWS {
                            self.recent_trace.pop_front();
                        }
                        self.recent_trace.push_back(*key);
                    }
                    ToolRunTraceOp::Clear => self.recent_trace.clear(),
                    ToolRunTraceOp::Retire { key } => self.recent_trace.retain(|recent| recent != key),
                }
            }
        }
        if receipt.evicted > 0 {
            self.framework_step(ToolRunStepKind::Warning, TOOL_RUN_REASON_TRACE_TRUNCATED, &[ToolRunStepArg::Unsigned(u64::from(receipt.evicted))]);
        }
        if receipt.capped {
            let cap = if self.member.is_some() { TOOL_RUN_MEMBER_OPS_MAX } else { TOOL_RUN_PROVISIONAL_OPS_MAX };
            self.framework_step(ToolRunStepKind::Warning, TOOL_RUN_REASON_PROVISIONAL_CAP, &[ToolRunStepArg::Unsigned(u64::from(cap))]);
        }
        let now = semio_framework_job::default_now_us().unwrap_or(0);
        match self.rate_origin {
            None => self.rate_origin = Some((now, self.completed)),
            Some((origin_us, origin_completed)) if now > origin_us => self.units_per_second = self.completed.saturating_sub(origin_completed) as f32 * 1_000_000.0 / (now - origin_us) as f32,
            Some(_) => {}
        }
        Ok(receipt)
    }
}

/// 📬️ What one applied tick changed.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct ToolRunTickReceipt {
    pub stale: bool,
    pub appended: u32,
    pub retracted: u32,
    pub evicted: u32,
    pub capped: bool,
}

/// 🧭️ Driver watch state and turn budget (§3.3): settings publications the store generations cannot see.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ToolRunDriver {
    pub turn_wall_us: u64,
    window_config_publications: u64,
}

impl Default for ToolRunDriver {
    fn default() -> Self {
        Self { turn_wall_us: TOOL_RUN_TURN_WALL_US, window_config_publications: 0 }
    }
}

/// 🗄️ The tool runs of one document instance for its local actor (§2.2 invariant 5): at most one non-terminal
/// mutating run, and concurrent read-only runs, one per tool and window ([`ToolRunLane`]); plus the owners still
/// retiring.
///
/// 🎯️ The ledger operates on one *selected* run. Outside its own calls the selection is the primary run — the
/// non-terminal mutating run, else the most recent one — so the single-run accessors (`state`, `slot`, `view`, …)
/// answer for it; [`ToolRunLedger::select_run`] addresses another.
pub struct ToolRunLedger<A: ArtifactApp> {
    next_run: u64,
    entries: Vec<Box<ToolRunEntry<A>>>,
    selected: Option<usize>,
    driver: ToolRunDriver,
    retired_jobs: Vec<ToolRunJobSlot<A::Config>>,
    retired_publications: Vec<store::ArtifactStoreBatchPublication<A::Snapshot, A::Mutation>>,
    /// ♻️ Snapshot aliases owed to the store's alias retirement, and the one being retired now.
    retired_snapshots: Vec<Arc<A::Snapshot>>,
    snapshot_retirement: Option<Box<dyn store::ErasedSnapshotRetirement>>,
    discarded: Vec<A::Mutation>,
    /// 🧩️ Member runs that left their slot, whose typed owners and composed reads still retire against their member store.
    retired_members: Vec<ToolRunMemberRun>,
    closing: bool,
    trace_windows: BTreeMap<String, ToolRunTraceWindow>,
    ui_dirty: bool,
    document_dirty: bool,
}

/// 🪟️ One scene window the trace lane was delivered to: its body key and what its renderer last echoed.
struct ToolRunTraceWindow {
    body_key: String,
    echoed: Option<ToolRunTraceCursor>,
    answered: bool,
    stalls: u8,
}

impl<A: ArtifactApp> Default for ToolRunLedger<A> {
    fn default() -> Self {
        Self {
            next_run: 1,
            entries: Vec::new(),
            selected: None,
            driver: ToolRunDriver::default(),
            retired_jobs: Vec::new(),
            retired_publications: Vec::new(),
            retired_snapshots: Vec::new(),
            snapshot_retirement: None,
            discarded: Vec::new(),
            retired_members: Vec::new(),
            closing: false,
            trace_windows: BTreeMap::new(),
            ui_dirty: false,
            document_dirty: false,
        }
    }
}

impl<A: ArtifactApp> ToolRunLedger<A> {
    /// 👑️ The primary run: the non-terminal mutating run, else the most recent run.
    fn primary_index(&self) -> Option<usize> {
        self.entries.iter().position(|entry| entry.definition.mutating && !entry.slot.state.is_terminal()).or_else(|| self.entries.iter().enumerate().max_by_key(|(_, entry)| entry.slot.run).map(|(index, _)| index))
    }

    /// 👑️ Selects the primary run.
    pub fn select_primary(&mut self) {
        self.selected = self.primary_index();
    }

    /// 🎯️ Selects run `run`; `false` (and no selection) when this instance holds no such run.
    pub fn select_run(&mut self, run: u64) -> bool {
        self.selected = self.entries.iter().position(|entry| entry.slot.run == run);
        self.selected.is_some()
    }

    /// 🗂️ Every run this instance holds, oldest first.
    pub fn views(&self) -> Vec<ToolRunView> {
        self.entries.iter().map(|entry| entry.view()).collect()
    }

    /// 🪟️ The run a window renders: the most recent read-only run started from `window_id`, else the primary run.
    pub fn view_for(&self, window_id: Option<&str>) -> Option<ToolRunView> {
        self.window_index(window_id).or_else(|| self.primary_index()).map(|index| self.entries[index].view())
    }

    fn window_index(&self, window_id: Option<&str>) -> Option<usize> {
        let window_id = window_id?;
        self.entries.iter().enumerate().filter(|(_, entry)| !entry.definition.mutating && entry.window.as_ref().is_some_and(|(id, _)| id == window_id)).max_by_key(|(_, entry)| entry.slot.run).map(|(index, _)| index)
    }

    pub fn state(&self) -> Option<ToolRunState> {
        selected_entry!(self).map(|entry| entry.slot.state)
    }

    pub fn slot(&self) -> Option<ToolRunSlot> {
        selected_entry!(self).map(|entry| entry.slot)
    }

    pub fn identity(&self) -> Option<ToolRunIdentity> {
        selected_entry!(self).map(|entry| entry.identity)
    }

    pub fn tool_id(&self) -> Option<&str> {
        selected_entry!(self).map(|entry| entry.tool_id.as_str())
    }

    /// 📮️ The port every job of the selected run shares with its app instance.
    pub fn port(&self) -> Option<&ToolRunJobPort> {
        selected_entry!(self).map(|entry| &entry.port)
    }

    pub fn provisional(&self) -> &[A::Mutation] {
        selected_entry!(self).map_or(&[], |entry| entry.provisional.as_slice())
    }

    pub fn provisional_entities(&self) -> Option<&BTreeSet<u64>> {
        selected_entry!(self).map(|entry| entry.entities.as_ref())
    }

    pub fn steps(&self) -> Option<&ToolRunStepRing> {
        selected_entry!(self).map(|entry| &entry.steps)
    }

    pub fn trace(&self) -> Option<&ToolRunTraceStore> {
        selected_entry!(self).map(|entry| &entry.trace)
    }

    pub fn conflicts(&self) -> u32 {
        selected_entry!(self).map_or(0, |entry| entry.conflicts)
    }

    pub fn is_refolding(&self) -> bool {
        selected_entry!(self).is_some_and(|entry| entry.refold.is_some())
    }

    /// 📸️ The current run's last `StepOutcome::CheckpointReady` state, the one a rebuilt job continues from.
    pub fn checkpoint(&self) -> Option<&[u8]> {
        selected_entry!(self)?.checkpoint.as_deref()
    }

    /// 🔑️ The trace key allocator every job of the current run shares.
    pub fn trace_keys(&self) -> Option<&ToolRunTraceKeys> {
        selected_entry!(self).map(|entry| &entry.trace_keys)
    }

    /// 🏷️ `(provisional length at the end of the appending tick, entity)` per provisional entity, in append order.
    pub fn entity_marks(&self) -> &[(u32, u64)] {
        selected_entry!(self).map_or(&[], |entry| entry.entity_marks.as_slice())
    }

    /// 🪟️ `(window instance id, window kind id)` the current run was started from.
    pub fn window(&self) -> Option<(&str, &str)> {
        selected_entry!(self)?.window.as_ref().map(|(window_id, window_kind_id)| (window_id.as_str(), window_kind_id.as_str()))
    }

    /// 📊️ Progress snapshot derived from the ledger (§2.3); the step ring is the framework's own.
    pub fn progress(&self) -> Option<semio_framework_tool_run::ToolRunProgress> {
        selected_entry!(self).map(ToolRunEntry::progress)
    }

    /// 🪞️ The document a renderer reads: the mutating run's overlay while it holds provisional state, else `committed`.
    /// Read-only runs author no provisional edit, so their overlays never compose.
    pub fn overlay_or<'a>(&'a self, committed: &'a Arc<A::Snapshot>) -> &'a Arc<A::Snapshot> {
        match self.entries.iter().find(|entry| entry.definition.mutating && !entry.slot.state.is_terminal()) {
            Some(entry) if matches!(entry.slot.state, ToolRunState::Starting | ToolRunState::Running | ToolRunState::Paused | ToolRunState::Complete | ToolRunState::Finalizing) && !Arc::ptr_eq(&entry.overlay, &entry.base) => &entry.overlay,
            _ => committed,
        }
    }

    /// 🧩️ The composed children a renderer reads (§20.15): the mutating member run's composed read while it holds provisional
    /// state, else `live`. The parent document is untouched by a member run, so [`Self::overlay_or`] answers `committed`.
    pub fn children_or<'a>(&'a self, live: &'a ChildContentView) -> &'a ChildContentView {
        match self.entries.iter().find(|entry| entry.definition.mutating && !entry.slot.state.is_terminal()) {
            Some(entry) if matches!(entry.slot.state, ToolRunState::Starting | ToolRunState::Running | ToolRunState::Paused | ToolRunState::Complete | ToolRunState::Finalizing) => entry.member.as_ref().and_then(|member| member.children.as_ref()).unwrap_or(live),
            _ => live,
        }
    }

    /// 🧩️ The `(slot, child id)` of the member the selected run edits, `None` for a run on the document's own store.
    pub fn member(&self) -> Option<(&str, &str)> {
        selected_entry!(self)?.member.as_ref().map(|member| (member.slot.as_str(), member.child_id.as_str()))
    }

    /// 🧩️ The selected member run's provisional ops (that member's `OpBinary` ops); empty for a document run.
    pub fn member_ops(&self) -> &[Vec<u8>] {
        selected_entry!(self).and_then(|entry| entry.member.as_ref()).map_or(&[], |member| member.ops.as_slice())
    }

    pub fn view(&self) -> Option<ToolRunView> {
        selected_entry!(self).map(ToolRunEntry::view)
    }

    /// ⏪️ Whether a non-terminal mutating run holds provisional state on this instance: history editing cannot open then.
    pub fn holds_mutating_run(&self) -> bool {
        self.entries.iter().any(|entry| entry.definition.mutating && !entry.slot.state.is_terminal())
    }

    /// 🧊️ `freeze` rebase policy: local artifact emits fail with `toolRun.busy` while a freezing run is non-terminal.
    pub fn freezes_local_emits(&self) -> bool {
        self.entries.iter().any(|entry| entry.definition.rebase == ToolRunRebasePolicy::Freeze && !entry.slot.state.is_terminal())
    }

    /// 🏃️ Whether a driver turn has work: any run's stepping job, refold, close, finalize or port effects, or cold
    /// retirement. A job waiting on its port is not work.
    pub fn has_pending_work(&self) -> bool {
        !self.retired_jobs.is_empty()
            || !self.retired_publications.is_empty()
            || !self.retired_snapshots.is_empty()
            || self.snapshot_retirement.is_some()
            || !self.discarded.is_empty()
            || !self.retired_members.is_empty()
            || self.entries.iter().any(|entry| entry.has_pending_work())
    }

    /// 🧬️ Applies one decoded tick to the current run (the driver's per-tick O(k) overlay append);
    /// ticks of another run or generation are stale no-ops.
    pub fn apply_tick(&mut self, tick: ToolRunTick) -> Result<ToolRunTickReceipt, Fault> {
        let Some(entry) = selected_entry_mut!(self) else { return Ok(ToolRunTickReceipt { stale: true, ..ToolRunTickReceipt::default() }) };
        entry.apply_tick(tick, &mut self.discarded)
    }

    /// 🪟️ A window-config publication happened; the driver treats it as a settings change.
    pub fn note_window_config_published(&mut self) {
        self.driver.window_config_publications = self.driver.window_config_publications.wrapping_add(1);
    }

    /// 👥️ Ephemeral-shared presence summary (§3.4), `completed ≤ total` by construction.
    pub fn presence(&self) -> Option<protocol::PresenceToolRun> {
        let entry = &self.entries[self.primary_index()?];
        Some(protocol::PresenceToolRun {
            tool_id: entry.tool_id.clone(),
            state: protocol::PresenceToolRunState::from_wire_name(entry.slot.state.as_str())?,
            stage: entry.stage,
            completed: entry.total.map_or(entry.completed, |total| entry.completed.min(total)),
            total: entry.total,
        })
    }

    /// 📼️ Base64url (unpadded) `ToolRunTraceDelta` after `cursor`, for the scene lane `toolRunTrace` (§3.2).
    ///
    /// - A cursor of another run or generation, or none, gets `clear` plus the resend of the live log.
    /// - A caught-up cursor gets `None`, so an idle run costs nothing.
    /// - Without a run (dismissed or retired), a renderer still holding pages (`page > 0`) gets one empty
    ///   `clear` delta; `page == 0` already means an empty layer.
    pub fn trace_delta(&self, cursor: Option<ToolRunTraceCursor>, byte_budget: usize) -> Option<String> {
        let index = cursor.and_then(|cursor| self.entries.iter().position(|entry| entry.slot.run == cursor.run)).or_else(|| self.primary_index());
        let delta = match index.map(|index| &self.entries[index]) {
            Some(entry) => entry.trace.delta_after(cursor, byte_budget),
            None => {
                let cursor = cursor.filter(|cursor| cursor.page > 0)?;
                ToolRunTraceDelta { identity: ToolRunIdentity { id: ToolRunId { app_instance_id: 0, run: cursor.run }, generation: cursor.generation, base_revision: [0; 32] }, clear: true, next: 0, pages: Vec::new() }
            }
        };
        tool_run_trace_lane_text(&delta)
    }

    /// 🪟️ The lane text scene window `window_id` (body `body_key`) receives for its echoed `cursor`, and the
    /// bookkeeping that keeps a delivery backlog moving: pages left after the byte budget mark the ledger
    /// UI-dirty until the renderer's cursor stands still for `TOOL_RUN_TRACE_STALL_REFRESHES` refreshes.
    pub fn trace_lane(&mut self, window_id: &str, body_key: &str, cursor: Option<ToolRunTraceCursor>, byte_budget: usize) -> Option<String> {
        let Some(entry) = self.window_index(Some(window_id)).or_else(|| self.primary_index()).map(|index| &self.entries[index]) else {
            self.trace_windows.remove(window_id);
            return self.trace_delta(cursor, byte_budget);
        };
        let delta = entry.trace.delta_after(cursor, byte_budget);
        let backlog = delta.next < entry.trace.next_page();
        let window = self.trace_windows.entry(window_id.to_string()).or_insert_with(|| ToolRunTraceWindow { body_key: body_key.to_string(), echoed: None, answered: false, stalls: 0 });
        if window.body_key != body_key {
            window.body_key = body_key.to_string();
        }
        window.stalls = if window.answered && window.echoed == cursor { window.stalls.saturating_add(1) } else { 0 };
        window.echoed = cursor;
        window.answered = true;
        if backlog && window.stalls < TOOL_RUN_TRACE_STALL_REFRESHES {
            self.ui_dirty = true;
        }
        tool_run_trace_lane_text(&delta)
    }

    /// 🧹️ Forgets scene windows that closed or stopped hosting a scene surface.
    pub fn retain_trace_windows(&mut self, live: impl Fn(&str) -> bool) {
        self.trace_windows.retain(|window_id, _| live(window_id));
    }

    /// 🎯️ The minimal UI scope a run change dirties: the ToolRun panel body, the body of every scene window its trace
    /// lane rides in and the body of every window kind the run declares it renders in (`ToolRunDefinition::windows`) —
    /// never unrelated windows or panels.
    pub fn dirty_scope(&self) -> UiDirtyScope {
        let mut window_bodies: Vec<String> = self.trace_windows.values().map(|window| window.body_key.clone()).chain(self.entries.iter().flat_map(|entry| entry.window_bodies.iter().cloned())).collect();
        window_bodies.sort_unstable();
        window_bodies.dedup();
        UiDirtyScope::Partial { window_bodies, panel_bodies: vec![FRAMEWORK_TOOL_RUN_BODY_KEY.to_string()], utilities: false, tools: false, engagements: false, measures: false, labels: false }
    }

    /// 🚩️ Whether a run change still owes the host a dirty scope.
    pub fn is_ui_dirty(&self) -> bool {
        self.ui_dirty || self.document_dirty
    }

    fn apply_event(&mut self, event: ToolRunEvent) -> Result<ToolRunEffect, ToolRunRejection> {
        let transition = ToolRunMachine::apply(self.slot(), event)?;
        match (self.selected, transition.slot) {
            (Some(index), Some(slot)) => {
                let entry = &mut self.entries[index];
                let generation_changed = entry.slot.generation != slot.generation;
                entry.slot = slot;
                if generation_changed {
                    entry.rebind();
                }
            }
            (Some(index), None) => {
                let entry = self.entries.remove(index);
                self.retire_entry(*entry);
                self.select_primary();
            }
            (None, _) => {}
        }
        Ok(transition.effect)
    }

    fn retire_entry(&mut self, entry: ToolRunEntry<A>) {
        let ToolRunEntry { job, provisional, finalize, base, overlay, refold, mut displaced, member, .. } = entry;
        self.retired_members.extend(member);
        self.retired_snapshots.push(base);
        self.retired_snapshots.push(overlay);
        if let Some(running) = refold.and_then(|refold| refold.running) {
            self.retired_snapshots.push(Arc::new(running));
        }
        self.retired_snapshots.append(&mut displaced);
        self.retire_owners(job, provisional, finalize);
    }

    fn retire_owners(&mut self, job: Option<ToolRunJobSlot<A::Config>>, mut provisional: Vec<A::Mutation>, finalize: Option<ToolRunFinalize<A>>) {
        if let Some(mut job) = job {
            job.begin_close();
            self.retired_jobs.push(job);
        }
        self.discarded.append(&mut provisional);
        if let Some(publication) = finalize.and_then(|finalize| finalize.publication) {
            self.retired_publications.push(publication);
        }
    }

    fn close_current_job(&mut self) {
        let Some(entry) = selected_entry_mut!(self) else { return };
        entry.settle_refold();
        if let Some(mut job) = entry.job.take() {
            job.begin_close();
            self.retired_jobs.push(job);
        }
    }

    /// 🎯️ Hands the current job the entry's identity through `retarget`; a job that is not retargetable, or
    /// declines, is closed so the driver rebuilds it from its checkpoint.
    fn retarget_current_job(&mut self, retarget: impl FnOnce(&mut dyn ToolRunRetargetableJob<A::Config>, ToolRunIdentity) -> bool) {
        let Some(entry) = selected_entry_mut!(self) else { return };
        let identity = entry.identity;
        let Some(slot) = entry.job.as_mut() else { return };
        if slot.retargetable().is_some_and(|job| retarget(job, identity)) {
            slot.generation = semio_framework_job::Generation(u64::from(identity.generation));
        } else {
            self.close_current_job();
        }
    }

    /// 🧹️ Throws the run's provisional work away, payload included: an abort, a fault, a rebase-restart
    /// or a reconfigure-restart invalidates the run's whole intermediate result, so the windows that
    /// read `ToolRunView::payload` must stop showing it.
    fn discard_provisional(&mut self) {
        self.release_provisional(false);
    }

    /// 🧹️ Releases the provisional ops a COMPLETED finalize has already published, keeping the run's
    /// `payload`. The payload is not provisional work — it is the run's own result (§2.3: "the latest
    /// intermediate result of the run … the run's windows read it back through
    /// `ToolRunView::payload`"), and a `mutating: false` run publishes nothing else at all, so clearing
    /// it on finalize is what made a finished read-only run's windows revert to their pre-run render the
    /// instant it reached `Finalized`. It is cleared on a genuine discard and when the entry retires.
    fn release_provisional(&mut self, keep_payload: bool) {
        let Some(entry) = selected_entry_mut!(self) else { return };
        self.discarded.append(&mut entry.provisional);
        entry.entity_marks.clear();
        entry.entities = Arc::new(BTreeSet::new());
        if let Some(running) = entry.refold.take().and_then(|refold| refold.running) {
            entry.displaced.push(Arc::new(running));
        }
        let overlay = Arc::clone(&entry.base);
        entry.replace_overlay(overlay);
        entry.checkpoint = None;
        if let Some(member) = entry.member.as_mut() {
            member.release();
        }
        if !keep_payload {
            entry.payload = None;
        }
    }

    /// 🧹️ Advances the owners that outlived their slot by one bounded unit; `None` when nothing is retiring.
    fn retire_step(&mut self, store: &mut ArtifactStore<A::Snapshot, A::Mutation>, maximum_items: usize, maximum_bytes: usize) -> Result<Option<PluginCloseStep>, Fault> {
        if let Some(job) = self.retired_jobs.last_mut() {
            return match job.close_step(maximum_items, maximum_bytes)? {
                Some(step) => Ok(Some(step)),
                None => {
                    self.retired_jobs.pop();
                    Ok(Some(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }))
                }
            };
        }
        if let Some(publication) = self.retired_publications.pop() {
            let mut owner = Some(publication);
            return match store.handoff_batch_publication_close(&mut owner) {
                Ok(true) => Ok(Some(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })),
                Ok(false) => Err(plugin_sdk_fault("tool run publication handoff lost its exact retirement owner")),
                Err(error) => {
                    self.retired_publications.push(owner.expect("refused Store handoff preserves the tool run publication owner"));
                    Err(error.into_fault())
                }
            };
        }
        if let Some(retirement) = self.snapshot_retirement.as_mut() {
            return match retirement.close_step(maximum_items.max(1), maximum_bytes).map_err(|error| plugin_sdk_fault(error.into_message()))? {
                store::SnapshotRetirementStep::Complete if retirement.terminal_is_empty() => {
                    self.snapshot_retirement = None;
                    Ok(Some(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }))
                }
                store::SnapshotRetirementStep::Complete => Err(Fault::new(FaultOrigin::Framework, FaultCode::new("toolRun.snapshot-close"), "tool run snapshot retirement closed without its terminal-empty witness")),
                store::SnapshotRetirementStep::Pending { released_items, released_bytes } => Ok(Some(PluginCloseStep::Pending { released_items, released_bytes })),
                store::SnapshotRetirementStep::Blocked => Ok(Some(PluginCloseStep::Blocked { reason: "tool run snapshot retirement is blocked" })),
            };
        }
        for entry in &mut self.entries {
            self.retired_snapshots.append(&mut entry.displaced);
        }
        if let Some(alias) = self.retired_snapshots.pop() {
            self.snapshot_retirement = Some(store.retire_snapshot_alias(alias).map_err(|error| error.into_fault())?);
            return Ok(Some(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }));
        }
        if !self.discarded.is_empty() {
            let count = self.discarded.len().min(maximum_items.max(1)).min(TOOL_RUN_DISCARD_OPS_PER_TURN);
            for op in self.discarded.drain(self.discarded.len() - count..) {
                op.retire_cold();
            }
            return Ok(Some(PluginCloseStep::Pending { released_items: count, released_bytes: 0 }));
        }
        Ok(None)
    }

    /// 🚪️ Document close, instance retirement or reload: same as abort, ephemeral state vanishes (§2.2).
    pub fn begin_close(&mut self) {
        if self.closing {
            return;
        }
        self.closing = true;
        while !self.entries.is_empty() {
            self.selected = Some(self.entries.len() - 1);
            let _ = self.apply_event(ToolRunEvent::Closed);
        }
        self.selected = None;
    }

    /// 🧹️ One bounded close unit of every retiring owner.
    pub fn close_step(&mut self, store: &mut ArtifactStore<A::Snapshot, A::Mutation>, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
        self.begin_close();
        Ok(self.retire_step(store, maximum_items, maximum_bytes)?.unwrap_or(PluginCloseStep::Complete))
    }

    pub fn terminal_is_empty(&self) -> bool {
        self.entries.is_empty() && self.retired_jobs.is_empty() && self.retired_publications.is_empty() && self.retired_snapshots.is_empty() && self.snapshot_retirement.is_none() && self.discarded.is_empty() && self.retired_members.is_empty()
    }
}
//#endregion 🔖️Ledger

//#region 🔖️Member
/// 🧬️ The typed owners of a member run (`ToolRunDefinition::member`): the member snapshot the run rests on, the overlay its
/// provisional ops fold to, and every alias it let go — all owed to that member store's alias retirement, never dropped plainly.
trait ToolRunMemberOwners: Send {
    fn as_any_mut(&mut self) -> &mut dyn std::any::Any;
    fn has_displaced(&self) -> bool;
    fn is_empty(&self) -> bool;
}

struct ToolRunMemberState<P> {
    base: Option<Arc<P>>,
    overlay: Option<Arc<P>>,
    displaced: Vec<Arc<P>>,
}

impl<P: Send + Sync + 'static> ToolRunMemberOwners for ToolRunMemberState<P> {
    fn as_any_mut(&mut self) -> &mut dyn std::any::Any {
        self
    }

    fn has_displaced(&self) -> bool {
        !self.displaced.is_empty()
    }

    fn is_empty(&self) -> bool {
        self.base.is_none() && self.overlay.is_none() && self.displaced.is_empty()
    }
}

/// 🧩️ A run whose provisional ops are one owned member's ops (design §12, §20.15): where they land, the member generation
/// they rest on, how many the overlay already shows, the typed owners they fold through, and the composed read — the live
/// children with the overlay in the member's place — the render seams show while the run holds them.
struct ToolRunMemberRun {
    slot: String,
    child_id: String,
    dialect: ArtifactDialect,
    base_generation: u64,
    ops: Vec<Vec<u8>>,
    shown: usize,
    rebase: bool,
    owners: Option<Box<dyn ToolRunMemberOwners>>,
    children: Option<ChildContentView>,
    stale: Vec<ChildContentView>,
    emit: Option<ChildEmit>,
}

impl ToolRunMemberRun {
    /// 🏃️ Owed work: ops the overlay does not show yet, a refold from the member head, or reads and aliases to retire.
    fn is_work(&self) -> bool {
        self.rebase || self.shown != self.ops.len() || !self.stale.is_empty() || self.owners.as_deref().is_some_and(ToolRunMemberOwners::has_displaced)
    }

    /// 🧹️ Drops every provisional op: the composed read retires and the next refresh rests on the member head.
    fn release(&mut self) {
        self.ops.clear();
        self.shown = 0;
        self.rebase = true;
        self.emit = None;
        self.stale.extend(self.children.take());
    }
}

/// 📏️ Where one member fold left the overlay: the ops it shows, the ops that did not apply, and — once every op is shown —
/// the leased read of the overlay with the member's revision (`None`: no op, the render seams read the live member).
struct ToolRunMemberFolded {
    shown: usize,
    conflicts: u32,
    read: Option<(store::ErasedSnapshotRead, [u8; 32])>,
}

/// 🔁️ Folds a member run's ops onto its overlay within the turn wall budget: a rebase restarts from the member head.
struct ToolRunMemberFold<'a> {
    owners: &'a mut Option<Box<dyn ToolRunMemberOwners>>,
    ops: &'a [Vec<u8>],
    shown: usize,
    rebase: bool,
    deadline_us: u64,
}

impl store::MemberStoreVisitor for ToolRunMemberFold<'_> {
    type Output = Result<ToolRunMemberFolded, Fault>;

    fn visit<P, Mu>(self, store: &ArtifactStore<P, Mu>) -> Self::Output
    where
        P: Clone + semio_framework_value::ToValue + semio_framework_value::FromValue + ArtifactPack + semio_framework_schema_composition::ArtifactCompositionFields + Send + Sync + 'static,
        Mu: Clone + semio_framework_value::ToValue + semio_framework_value::FromValue + ::protocol::Mutation<P> + protocol::SemanticMutation<P> + ::protocol::OpBinary + ::protocol::OpText + Send + 'static,
    {
        let owners = self.owners.get_or_insert_with(|| Box::new(ToolRunMemberState::<P> { base: Some(store.snapshot_owner()), overlay: None, displaced: Vec::new() }));
        let state = owners.as_any_mut().downcast_mut::<ToolRunMemberState<P>>().ok_or_else(|| plugin_sdk_fault("a member tool run's owners belong to another store kind"))?;
        let mut shown = self.shown;
        if self.rebase {
            let previous = state.base.replace(store.snapshot_owner());
            state.displaced.extend(previous);
            state.displaced.extend(state.overlay.take());
            shown = 0;
        }
        let mut conflicts = 0u32;
        while shown < self.ops.len() {
            let op = <Mu as ::protocol::OpBinary>::decode_op(&self.ops[shown]).map_err(|error| error.into_fault())?;
            let source = state.overlay.as_ref().or(state.base.as_ref()).ok_or_else(|| plugin_sdk_fault("a member tool run lost its base"))?;
            let outcome = <Mu as ::protocol::Mutation<P>>::diff(&op, source);
            let next = outcome.is_applicable(protocol::MergePolicy::default()).then(|| <<Mu as ::protocol::Mutation<P>>::Diff as ::protocol::MutationDiff<P>>::apply(outcome.diff(), source).ok()).flatten();
            <Mu as ::protocol::Mutation<P>>::retire_cold(op);
            match next {
                Some(next) => state.displaced.extend(state.overlay.replace(Arc::new(next))),
                None => conflicts = conflicts.saturating_add(1),
            }
            shown += 1;
            if shown % TOOL_RUN_REFOLD_CHECK_OPS == 0 && shown < self.ops.len() && semio_framework_job::default_now_us().is_none_or(|now| now >= self.deadline_us) {
                return Ok(ToolRunMemberFolded { shown, conflicts, read: None });
            }
        }
        let read = match state.overlay.as_ref().filter(|_| !self.ops.is_empty()) {
            Some(overlay) => Some((store.snapshot_read_erased_of(Arc::clone(overlay)).map_err(|error| error.into_fault())?, store.content_revision())),
            None => None,
        };
        Ok(ToolRunMemberFolded { shown, conflicts, read })
    }
}

/// 🧾️ Decodes a member run's ops through the member's own vocabulary into the one composite child emission its finalize
/// publishes — the history row's mutations carry that member's leaf labels — resuming where the last turn stopped and
/// yielding at the turn wall deadline. `true` once every op is in the emission.
struct ToolRunMemberEmit<'a> {
    slot: &'a str,
    child_id: &'a str,
    ops: &'a [Vec<u8>],
    emit: &'a mut Option<ChildEmit>,
    deadline_us: u64,
}

impl store::MemberStoreVisitor for ToolRunMemberEmit<'_> {
    type Output = Result<bool, Fault>;

    fn visit<P, Mu>(self, _store: &ArtifactStore<P, Mu>) -> Self::Output
    where
        P: Clone + semio_framework_value::ToValue + semio_framework_value::FromValue + ArtifactPack + semio_framework_schema_composition::ArtifactCompositionFields + Send + Sync + 'static,
        Mu: Clone + semio_framework_value::ToValue + semio_framework_value::FromValue + ::protocol::Mutation<P> + protocol::SemanticMutation<P> + ::protocol::OpBinary + ::protocol::OpText + Send + 'static,
    {
        let emit = self.emit.get_or_insert_with(|| ChildEmit::open(self.slot, self.child_id, self.ops.len()));
        while emit.ops.len() < self.ops.len() {
            let op = <Mu as ::protocol::OpBinary>::decode_op(&self.ops[emit.ops.len()]).map_err(|error| error.into_fault())?;
            emit.push::<P, Mu>(&op);
            <Mu as ::protocol::Mutation<P>>::retire_cold(op);
            if emit.ops.len() % TOOL_RUN_REFOLD_CHECK_OPS == 0 && emit.ops.len() < self.ops.len() && semio_framework_job::default_now_us().is_none_or(|now| now >= self.deadline_us) {
                return Ok(false);
            }
        }
        Ok(true)
    }
}

/// 🔢️ The member store's generation, the base a member run watches instead of the document's.
struct ToolRunMemberGeneration;

impl store::MemberStoreVisitor for ToolRunMemberGeneration {
    type Output = u64;

    fn visit<P, Mu>(self, store: &ArtifactStore<P, Mu>) -> Self::Output
    where
        P: Clone + semio_framework_value::ToValue + semio_framework_value::FromValue + ArtifactPack + semio_framework_schema_composition::ArtifactCompositionFields + Send + Sync + 'static,
        Mu: Clone + semio_framework_value::ToValue + semio_framework_value::FromValue + ::protocol::Mutation<P> + protocol::SemanticMutation<P> + ::protocol::OpBinary + ::protocol::OpText + Send + 'static,
    {
        store.generation()
    }
}

/// ♻️ Hands one alias of a member run's owners to the member store's bounded alias retirement: displaced aliases first,
/// and with `everything` the base and overlay too (the run left its slot).
struct ToolRunMemberRetire<'a> {
    owners: &'a mut (dyn ToolRunMemberOwners + 'static),
    everything: bool,
}

impl store::MemberStoreVisitor for ToolRunMemberRetire<'_> {
    type Output = Result<Option<Box<dyn store::ErasedSnapshotRetirement>>, Fault>;

    fn visit<P, Mu>(self, store: &ArtifactStore<P, Mu>) -> Self::Output
    where
        P: Clone + semio_framework_value::ToValue + semio_framework_value::FromValue + ArtifactPack + semio_framework_schema_composition::ArtifactCompositionFields + Send + Sync + 'static,
        Mu: Clone + semio_framework_value::ToValue + semio_framework_value::FromValue + ::protocol::Mutation<P> + protocol::SemanticMutation<P> + ::protocol::OpBinary + ::protocol::OpText + Send + 'static,
    {
        let state = self.owners.as_any_mut().downcast_mut::<ToolRunMemberState<P>>().ok_or_else(|| plugin_sdk_fault("a member tool run's owners belong to another store kind"))?;
        let alias = match state.displaced.pop() {
            Some(alias) => Some(alias),
            None if self.everything => state.overlay.take().or_else(|| state.base.take()),
            None => None,
        };
        alias.map(|alias| store.retire_snapshot_alias(alias).map_err(|error| error.into_fault())).transpose()
    }
}
//#endregion 🔖️Member

//#region 🔖️Driver
/// 🎛️ Outcome of one tool run action dispatch; rejections are silent no-ops (§2.1).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ToolRunActionOutcome {
    Applied(ToolRunEffect),
    Rejected(ToolRunRejection),
}

/// 🔢️ One §2.5 action argument read as a `u64`, in every shape the wire can hand it over.
///
/// 🪪️ A JSON number that is an exact non-negative integer IS a `u64` here, and reading it as anything
/// else is not strictness, it is a silent refusal. `toolRunFinalize`'s `generation` crosses as
/// `Number(Float(1.0))` — the shell's own action arguments build it with `UiValue::Number(f64)`, and a
/// guest that mints it with `DslValue::uint` arrives the same way — so accepting only an exact `u64`
/// carrier or a numeric string made `generation` read `None`, and `(_, None)` is
/// `ToolRunRejection::Stale`. EVERY finalize of EVERY app was rejected: runs reached `Complete` and
/// stayed there, and because a start against a live run is `ToolRunRejection::Busy`, no tool run could
/// ever be started a second time. Measured on 6018 as a 3d preview that never re-evaluated after the
/// first evaluation of a session (`📓️preview-rearm-after-inspector-edit-2026-09-14.md`).
pub(crate) fn tool_run_arg_u64(args: Option<&DslValue>, key: &str) -> Option<u64> {
    let value = args?.get(key)?;
    value
        .as_u64()
        .or_else(|| value.as_str().and_then(|text| text.parse().ok()))
        .or_else(|| value.as_f64().filter(|number| number.is_finite() && *number >= 0.0 && number.fract() == 0.0 && *number < 18_446_744_073_709_551_616.0).map(|number| number as u64))
}

impl<A: ArtifactApp, M: SpaceMember + MemberFactory + 'static> VcsArtifactApp<A, M> {
    /// 🏃️ Ledger work plus an unobserved store or settings generation change the watch still owes.
    pub(crate) fn tool_run_has_pending_work(&self) -> bool {
        self.tool_runs.has_pending_work()
            || self.tool_runs.is_ui_dirty()
            || self.tool_runs.entries.iter().any(|entry| {
                matches!(entry.slot.state, ToolRunState::Running | ToolRunState::Paused | ToolRunState::Complete | ToolRunState::Finalizing)
                    && (entry.base_generation != self.store.generation()
                        || entry.settings_generation != self.tool_run_settings_generation()
                        || entry.member.as_ref().is_some_and(|member| self.children.get(&(member.slot.clone(), member.child_id.clone())).is_some_and(|child| child.member.visit_member(ToolRunMemberGeneration) != member.base_generation)))
            })
    }

    /// 🎚️ The committed settings generations the driver watches (config store, window-config publications).
    fn tool_run_settings_generation(&self) -> (u64, u64) {
        (self.config_store.generation(), self.tool_runs.driver.window_config_publications)
    }

    /// ⏯️ Host-driven routing of the §2.5 actions: applied to the ledger now, never queued behind the run.
    ///
    /// 🧯️ A rejection REPAINTS the panel. The panel's buttons carry the run identity captured when
    /// the panel last rendered, and a settings change bumps the live generation — so a stale press
    /// was rejected, published `UiDirtyScope::None`, and therefore left the same stale identity on
    /// the button: every later press was silently rejected too, forever. Measured 2026-09-17 on a
    /// ◻️2d fill that stayed `Paused · Searching an open handle (2/5)` for 30 s after Abort.
    pub(crate) async fn dispatch_tool_run_action(&mut self, action: &str, args: Option<&DslValue>, meta: &ActionMeta) -> Result<InvocationResult, Fault> {
        let outcome = self.apply_tool_run_action(action, args, meta).await?;
        let output = match outcome {
            ToolRunActionOutcome::Applied(effect) => DslValue::Object(vec![("toolRun".into(), DslValue::String(effect.as_str().into()))]),
            ToolRunActionOutcome::Rejected(rejection) => DslValue::Object(vec![("rejected".into(), DslValue::String(rejection.code().into()))]),
        };
        let ui_scope = match outcome {
            ToolRunActionOutcome::Applied(ToolRunEffect::SpawnJob) => UiDirtyScope::Full,
            ToolRunActionOutcome::Applied(_) => self.tool_runs.dirty_scope(),
            ToolRunActionOutcome::Rejected(_) => self.tool_runs.dirty_scope(),
        };
        let mut result = Self::empty_result(action, meta, Vec::new(), Vec::new(), ui_scope).await;
        result.output = output;
        Ok(result)
    }

    /// ⚖️ Applies one §2.5 action to the ledger and performs the transition's immediate effect. An action that
    /// names no identity at all (neither `runId` nor `generation`, as a keyboard chord dispatches it) targets
    /// the instance's live run at its generation of this dispatch; an identity it does name is checked as is.
    pub async fn apply_tool_run_action(&mut self, action: &str, args: Option<&DslValue>, meta: &ActionMeta) -> Result<ToolRunActionOutcome, Fault> {
        let outcome = self.apply_selected_tool_run_action(action, args, meta).await;
        self.tool_runs.select_primary();
        outcome
    }

    /// ⚖️ [`Self::apply_tool_run_action`] on the run the action addresses: its `runId`, else the primary run.
    ///
    /// 🛑️ An abort is idempotent in the generation: it ends the run whatever that run was last
    /// reconfigured to, exactly as `Dismiss` above already ignores generation entirely. Checking
    /// the button's captured generation made Abort unreachable after any settings change — the
    /// one control whose whole job is to get out of a run it cannot otherwise leave.
    async fn apply_selected_tool_run_action(&mut self, action: &str, args: Option<&DslValue>, meta: &ActionMeta) -> Result<ToolRunActionOutcome, Fault> {
        let Some(action) = ToolRunAction::from_id(action) else {
            return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("toolRun.unknown-action"), format!("'{action}' is not a tool run action")));
        };
        if action == ToolRunAction::Start {
            return self.start_tool_run(args, meta).await;
        }
        let names_identity = args.is_some_and(|args| args.get(TOOL_RUN_ARG_RUN_ID).is_some() || args.get(TOOL_RUN_ARG_GENERATION).is_some());
        match tool_run_arg_u64(args, TOOL_RUN_ARG_RUN_ID) {
            Some(run) => {
                self.tool_runs.select_run(run);
            }
            None => self.tool_runs.select_primary(),
        }
        let live = if names_identity { None } else { self.tool_runs.slot() };
        let run = live.map_or_else(|| tool_run_arg_u64(args, TOOL_RUN_ARG_RUN_ID).unwrap_or(0), |slot| slot.run);
        let generation = live.map(|slot| slot.generation).or_else(|| tool_run_arg_u64(args, TOOL_RUN_ARG_GENERATION).and_then(|value| u32::try_from(value).ok()));
        let event = match (action, generation) {
            (ToolRunAction::Dismiss, _) => ToolRunEvent::Dismiss { run },
            (_, None) => return Ok(ToolRunActionOutcome::Rejected(ToolRunRejection::Stale)),
            (ToolRunAction::Pause, Some(generation)) if self.tool_runs.state() == Some(ToolRunState::Paused) => ToolRunEvent::Resume { run, generation },
            (ToolRunAction::Pause, Some(generation)) => ToolRunEvent::Pause { run, generation },
            (ToolRunAction::Resume, Some(generation)) => ToolRunEvent::Resume { run, generation },
            (ToolRunAction::Step, Some(generation)) => ToolRunEvent::Step { run, generation },
            (ToolRunAction::Finalize, Some(generation)) => ToolRunEvent::Finalize { run, generation },
            (ToolRunAction::Abort, Some(generation)) => {
                let generation = self.tool_runs.slot().filter(|slot| slot.run == run).map_or(generation, |slot| slot.generation);
                let publishing = selected_entry!(self.tool_runs).and_then(|entry| entry.finalize.as_ref()).is_some_and(|finalize| {
                    finalize.published
                        || finalize.publication.as_ref().is_some_and(|publication| {
                            !matches!(publication.phase(), store::ArtifactStoreOneItemPublicationPhase::Preparing | store::ArtifactStoreOneItemPublicationPhase::PreparingCursor | store::ArtifactStoreOneItemPublicationPhase::PreflightingCommit)
                        })
                });
                ToolRunEvent::Abort { run, generation, publishing }
            }
            (ToolRunAction::Start, _) => unreachable!("start handled above"),
        };
        if let Some(entry) = selected_entry_mut!(self.tool_runs).filter(|entry| action == ToolRunAction::Finalize && entry.slot.run == run) {
            entry.actor = meta.actor.clone();
        }
        let effect = match self.tool_runs.apply_event(event) {
            Ok(effect) => effect,
            Err(rejection) => return Ok(ToolRunActionOutcome::Rejected(rejection)),
        };
        match (effect, selected_entry_mut!(self.tool_runs)) {
            (ToolRunEffect::DriveOneUnit, Some(entry)) => entry.pending_step = true,
            (ToolRunEffect::StopScheduling, Some(entry)) => entry.pending_step = false,
            (ToolRunEffect::BeginFinalize, Some(entry)) => entry.finalize = Some(ToolRunFinalize { phase: ToolRunFinalizePhase::Pending, publication: None, retracted: 0, published: false }),
            (ToolRunEffect::CloseJob, _) => self.tool_runs.close_current_job(),
            (ToolRunEffect::CancelBatch, _) => {
                self.tool_runs.close_current_job();
                if let Some(publication) = selected_entry_mut!(self.tool_runs).and_then(|entry| entry.finalize.as_mut()).and_then(|finalize| finalize.publication.as_mut()) {
                    self.store.cancel_apply_batch(publication);
                }
            }
            _ => {}
        }
        Ok(ToolRunActionOutcome::Applied(effect))
    }

    async fn start_tool_run(&mut self, args: Option<&DslValue>, meta: &ActionMeta) -> Result<ToolRunActionOutcome, Fault> {
        let view_state = meta.view_state.as_ref();
        let tool_id = args
            .and_then(|args| args.get(TOOL_RUN_ARG_TOOL_ID))
            .and_then(DslValue::as_str)
            .map(str::to_string)
            .or_else(|| view_state.and_then(|view| view.active_utility_id.clone().filter(|id| self.registry.tool_run(id).is_some()).or_else(|| view.active_tool_id.clone())))
            .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("toolRun.tool-id"), "toolRunStart needs a toolId argument or an active tool"))?;
        let definition =
            self.registry.tool_run(&tool_id).map(|(_, definition)| definition.clone()).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("toolRun.unknown-tool"), format!("tool '{tool_id}' declares no ToolRunDefinition")))?;
        let window_id = args.and_then(|args| args.get(TOOL_RUN_ARG_WINDOW_ID)).and_then(DslValue::as_str).map(str::to_string).or_else(|| view_state.and_then(|view| view.window_id.clone().or_else(|| view.focused_window_id.clone())));
        if definition.mutating && self.time_travel.freezes_local_emits() {
            return Ok(ToolRunActionOutcome::Rejected(ToolRunRejection::Busy));
        }
        let member = definition.member.as_deref().map(|slot| self.tool_run_member_target(slot)).transpose()?;
        let lane = ToolRunLane { mutating: definition.mutating, tool_id: tool_id.clone(), window_id: if definition.mutating { None } else { window_id.clone() } };
        let live: Vec<(ToolRunLane, ToolRunState)> = self.tool_runs.entries.iter().map(|entry| (entry.lane(), entry.slot.state)).collect();
        let replaced = match lane.admit(&live) {
            Ok(replaced) => replaced,
            Err(rejection) => return Ok(ToolRunActionOutcome::Rejected(rejection)),
        };
        let run = self.tool_runs.next_run;
        let transition = match ToolRunMachine::apply(None, ToolRunEvent::Start { run }) {
            Ok(transition) => transition,
            Err(rejection) => return Ok(ToolRunActionOutcome::Rejected(rejection)),
        };
        let slot = transition.slot.expect("start yields a slot");
        self.tool_runs.next_run = run.wrapping_add(1);
        for index in replaced.into_iter().rev() {
            let previous = self.tool_runs.entries.remove(index);
            self.tool_runs.retire_entry(*previous);
        }
        self.refresh_cache().await?;
        let (base, _, _) = self.command_cache_inputs();
        let identity = ToolRunIdentity::new(ToolRunId { app_instance_id: self.live_runtime_instance_id.unwrap_or(meta.instance_id), run }, self.store.content_revision());
        let settings_generation = self.tool_run_settings_generation();
        let window = window_id.and_then(|window_id| view_state?.window_instances.iter().find(|window| window.id == window_id).map(|window| (window.id.clone(), window.window_kind_id.clone())));
        let settings_values = self.tool_run_settings_values(&definition.settings, window.as_ref());
        let window_bodies = definition.windows.iter().filter_map(|window_kind_id| self.registry.window_body_key(window_kind_id).map(str::to_string)).collect();
        self.tool_runs.entries.push(Box::new(ToolRunEntry {
            tool_id,
            actor: meta.actor.clone(),
            settings_values,
            window,
            window_bodies,
            payload: None,
            trace_keys: ToolRunTraceKeys::default(),
            definition,
            slot,
            identity,
            overlay: Arc::clone(&base),
            base,
            base_generation: self.store.generation(),
            settings_generation,
            provisional: Vec::new(),
            entity_marks: Vec::new(),
            entities: Arc::new(BTreeSet::new()),
            refold: None,
            trace: ToolRunTraceStore::new(identity),
            recent_trace: std::collections::VecDeque::with_capacity(TOOL_RUN_PANEL_TRACE_ROWS),
            stage: 0,
            completed: 0,
            total: None,
            counters: Vec::new(),
            steps: ToolRunStepRing::new(),
            step_sequence: 0,
            sequence: 0,
            conflicts: 0,
            rate_origin: None,
            units_per_second: 0.0,
            job: None,
            checkpoint: None,
            pending_step: false,
            finalize: None,
            announced: None,
            port: ToolRunJobPort::default(),
            displaced: Vec::new(),
            member,
        }));
        Ok(ToolRunActionOutcome::Applied(transition.effect))
    }

    /// 🧵️ Builds the run's job for `purpose`: the app's retargetable job when it builds one, else its plain job.
    fn build_tool_run_job_slot(&self, entry: &ToolRunEntry<A>, purpose: ToolRunJobPurpose) -> Result<Option<ToolRunJobSlot<A::Config>>, Fault> {
        let request = || ToolRunJobRequest::<A> {
            tool_id: &entry.tool_id,
            definition: &entry.definition,
            purpose,
            identity: entry.identity,
            snapshot: match purpose {
                ToolRunJobPurpose::Run => Arc::clone(&entry.base),
                ToolRunJobPurpose::Revalidate => self.store.snapshot_owner(),
            },
            config: self.config_store.snapshot_owner(),
            window_id: entry.window.as_ref().map(|(window_id, _)| window_id.as_str()),
            window_config: entry.window.as_ref().and_then(|(window_id, window_kind_id)| self.window_config_store.snapshot(window_kind_id, window_id)),
            checkpoint: entry.checkpoint.as_deref(),
            provisional: &entry.provisional,
            instance_owner: self.instance_operation_owner.clone(),
            port: entry.port.clone(),
            trace_keys: entry.trace_keys.clone(),
            entity_marks: &entry.entity_marks,
            children: ChildContentView::clone(&self.child_content_root),
            member_ops: entry.member.as_ref().map_or(&[], |member| member.ops.as_slice()),
        };
        let generation = entry.identity.generation;
        if let Some(job) = A::build_retargetable_tool_run_job(request())? {
            return Ok(Some(ToolRunJobSlot::new(ToolRunJobHandle::Retargetable(job), purpose, generation)));
        }
        Ok(A::build_tool_run_job(request())?.map(|job| ToolRunJobSlot::new(ToolRunJobHandle::Plain(job), purpose, generation)))
    }

    /// 🎚️ What the run's declared settings reads name right now. A declared window kind that is the starting
    /// window's reads only that window's config, the one its jobs receive; any other declared kind reads every
    /// partition of that kind.
    fn tool_run_settings_values(&self, reads: &ToolRunSettingsReads, window: Option<&(String, String)>) -> ToolRunSettingsValues {
        let config = if reads.config.is_empty() {
            Vec::new()
        } else {
            let document = semio_framework_value::ToValue::to_value(self.config_store.snapshot_owner().as_ref());
            reads.config.iter().map(|pointer| tool_run_pointer_value(&document, pointer).cloned()).collect()
        };
        let window_config = reads
            .window_config
            .iter()
            .flat_map(|(window_kind_id, pointers)| {
                let started = window.filter(|(_, kind)| kind == window_kind_id).map(|(window_id, _)| window_id.as_str());
                self.window_config_store.pointer_values(window_kind_id, pointers).into_iter().filter(move |(window_id, _)| started.is_none_or(|started| started == window_id)).map(move |(window_id, values)| (window_kind_id.clone(), window_id, values))
            })
            .collect();
        ToolRunSettingsValues { config, window_config }
    }

    fn apply_tool_run_driver_event(&mut self, event: ToolRunEvent) -> Option<ToolRunEffect> {
        self.tool_runs.apply_event(event).ok()
    }

    /// 📮️ Hands the host every effect jobs queued on the port, in order, while the typed effect outbox has room.
    fn drain_tool_run_port(&mut self) {
        for index in 0..self.tool_runs.entries.len() {
            while let Some(effect) = self.tool_runs.entries[index].port.pop_effect() {
                if let Err(effect) = self.typed_effect_outbox.push(effect) {
                    self.tool_runs.entries[index].port.restore_effect(effect);
                    return;
                }
            }
        }
    }

    /// 🎯️ A tick-sized change: progress, steps, trace and provisional appends reach the panel and the scene
    /// windows only (`ToolRunLedger::dirty_scope`).
    fn mark_tool_run_ui_dirty(&mut self) {
        self.tool_runs.ui_dirty = true;
        self.flush_tool_run_ui_dirty();
    }

    /// 📄️ The document every window reads was swapped wholesale (overlay refolded, released or discarded), so
    /// every body is dirty once.
    fn mark_tool_run_document_dirty(&mut self) {
        self.tool_runs.document_dirty = true;
        self.flush_tool_run_ui_dirty();
    }

    /// 📮️ Hands the owed scope to the typed UI outbox once it has room; until then the flags stay set, so a
    /// queued unrelated scope never swallows a run change.
    pub(crate) fn flush_tool_run_ui_dirty(&mut self) {
        if !self.tool_runs.is_ui_dirty() || self.typed_ui_outbox.len() != 0 {
            return;
        }
        let scope = if self.tool_runs.document_dirty { UiDirtyScope::Full } else { self.tool_runs.dirty_scope() };
        if self.typed_ui_outbox.push(scope).is_ok() {
            self.tool_runs.ui_dirty = false;
            self.tool_runs.document_dirty = false;
        }
    }

    /// 🎬️ Scene lane injection (§3.2, §4.1 layer 2): the first World3d, Canvas2d or Board2d scene surface a window body
    /// renders carries the `toolRunTrace` lane answered for the cursor that window's renderer echoed.
    /// Panel bodies, override renders and bodies without a scene surface carry nothing.
    pub(crate) fn inject_tool_run_trace_lane(&mut self, tree: &mut ComponentTree, body_key: &str, view_state: &ViewModel) -> Result<(), Fault> {
        let Some(window_id) = view_state.window_id.as_deref() else { return Ok(()) };
        self.tool_runs.retain_trace_windows(|live| view_state.window_instances.iter().any(|window| window.id == live));
        let Some(surface) = tool_run_scene_surface(&mut tree.root) else {
            self.tool_runs.trace_windows.remove(window_id);
            return Ok(());
        };
        let cursor = view_state.tool_run_trace_cursor_by_window_id.get(window_id).copied();
        let Some(lane) = self.tool_runs.trace_lane(window_id, body_key, cursor, TOOL_RUN_TRACE_DELTA_BYTES) else { return Ok(()) };
        inject_tool_run_trace_lane_into(surface, &lane).map_err(|error| plugin_sdk_fault(error.to_string()))
    }

    /// 👀️ Store and settings watch (§3.3): emits `baseChanged` / `settingsChanged` with their policies.
    ///
    /// - A base change rebinds a retargetable job to the new identity in place; any other job is closed and
    ///   rebuilt under the new identity (`restart` also discards the provisional ops), so no tick of the old
    ///   identity is ever produced.
    /// - A config or window-config publication is only a settings change when a value behind one of the run's
    ///   declared `settings` pointers changed; `resume` then retargets a retargetable job in place and rebuilds
    ///   any other from its checkpoint.
    fn watch_tool_run_generations(&mut self) {
        let store_generation = self.store.generation();
        let settings_generation = self.tool_run_settings_generation();
        let member_generation = self.tool_run_member_generation();
        let Some(entry) = selected_entry!(self.tool_runs) else { return };
        let (run, state, rebase, reconfigure) = (entry.slot.run, entry.slot.state, entry.definition.rebase, entry.definition.reconfigure);
        let parent_moved = entry.base_generation != store_generation;
        let base_changed = match (entry.member.as_ref(), member_generation) {
            (Some(member), Some(generation)) => member.base_generation != generation,
            (Some(_), None) => false,
            (None, _) => parent_moved,
        };
        let settings_moved = entry.settings_generation != settings_generation;
        if !matches!(state, ToolRunState::Running | ToolRunState::Paused | ToolRunState::Complete) {
            return;
        }
        if parent_moved && entry.member.is_some() {
            let head = self.store.snapshot_owner();
            let entry = selected_entry_mut!(self.tool_runs).expect("the watch keeps the slot");
            entry.replace_base(head);
            let overlay = Arc::clone(&entry.base);
            entry.replace_overlay(overlay);
            entry.base_generation = store_generation;
        }
        if let (true, Some(generation)) = (base_changed, member_generation.filter(|_| selected_entry!(self.tool_runs).is_some_and(|entry| entry.member.is_some()))) {
            if self.apply_tool_run_driver_event(ToolRunEvent::BaseChanged { run }) == Some(ToolRunEffect::Refold) {
                let restart = rebase == ToolRunRebasePolicy::Restart;
                if restart {
                    self.tool_runs.close_current_job();
                    self.tool_runs.discard_provisional();
                }
                let entry = selected_entry_mut!(self.tool_runs).expect("refold keeps the slot");
                if let Some(member) = entry.member.as_mut() {
                    member.base_generation = generation;
                    member.rebase = true;
                }
                entry.framework_step(ToolRunStepKind::Warning, TOOL_RUN_REASON_REBASING, &[]);
                if !restart {
                    self.tool_runs.retarget_current_job(|job, identity| {
                        job.rebind(identity);
                        true
                    });
                }
                self.mark_tool_run_document_dirty();
            }
        } else if base_changed && self.apply_tool_run_driver_event(ToolRunEvent::BaseChanged { run }) == Some(ToolRunEffect::Refold) {
            let head = self.store.snapshot_owner();
            let restart = rebase == ToolRunRebasePolicy::Restart;
            if restart {
                self.tool_runs.close_current_job();
                self.tool_runs.discard_provisional();
            }
            let entry = selected_entry_mut!(self.tool_runs).expect("refold keeps the slot");
            entry.replace_base(head);
            entry.base_generation = store_generation;
            entry.identity.base_revision = self.store.content_revision();
            entry.trace.rebind(entry.identity);
            if restart {
                let overlay = Arc::clone(&entry.base);
                entry.replace_overlay(overlay);
            } else {
                entry.begin_refold(true);
            }
            entry.framework_step(ToolRunStepKind::Warning, TOOL_RUN_REASON_REBASING, &[]);
            if !restart {
                self.tool_runs.retarget_current_job(|job, identity| {
                    job.rebind(identity);
                    true
                });
            }
            self.mark_tool_run_document_dirty();
        }
        if !settings_moved {
            return;
        }
        let entry = selected_entry!(self.tool_runs).expect("the watch keeps the slot");
        let values = self.tool_run_settings_values(&entry.definition.settings, entry.window.as_ref());
        let entry = selected_entry_mut!(self.tool_runs).expect("the watch keeps the slot");
        entry.settings_generation = settings_generation;
        if values == entry.settings_values {
            return;
        }
        entry.settings_values = values;
        if self.apply_tool_run_driver_event(ToolRunEvent::SettingsChanged { run }) != Some(ToolRunEffect::Reconfigure) {
            return;
        }
        match reconfigure {
            ToolRunReconfigurePolicy::Restart => {
                self.tool_runs.close_current_job();
                self.tool_runs.discard_provisional();
                self.mark_tool_run_document_dirty();
            }
            ToolRunReconfigurePolicy::Resume => {
                let config = self.config_store.snapshot_owner();
                self.tool_runs.retarget_current_job(|job, identity| job.reconfigure(identity, config));
                self.mark_tool_run_ui_dirty();
            }
        }
    }

    /// ⏯️ One bounded driver turn (≤ `ToolRunDriver::turn_wall_us`): owed dirty scope, retirement, watch, refold,
    /// job steps, finalize.
    pub(crate) async fn drive_tool_run_turn(&mut self) -> Result<(), Fault> {
        self.flush_tool_run_ui_dirty();
        self.drain_tool_run_port();
        let started = semio_framework_job::default_now_us().unwrap_or(0);
        let deadline = started.saturating_add(self.tool_runs.driver.turn_wall_us);
        if let Some(step) = self.tool_run_retire_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES)? {
            if !matches!(step, PluginCloseStep::Blocked { .. }) {
                return Ok(());
            }
        }
        let runs: Vec<u64> = self.tool_runs.entries.iter().map(|entry| entry.slot.run).collect();
        let mut outcome = Ok(());
        for run in runs {
            if !self.tool_runs.select_run(run) {
                continue;
            }
            outcome = self.drive_selected_tool_run(deadline).await;
            if outcome.is_err() || semio_framework_job::default_now_us().is_none_or(|now| now >= deadline) {
                break;
            }
        }
        self.tool_runs.select_primary();
        outcome
    }

    /// ⏯️ The selected run's share of one driver turn.
    async fn drive_selected_tool_run(&mut self, deadline: u64) -> Result<(), Fault> {
        let Some(state) = self.tool_runs.state() else { return Ok(()) };
        match state {
            ToolRunState::Aborting => {
                if self.tool_runs.retired_jobs.is_empty() && self.tool_runs.retired_publications.is_empty() {
                    let (run, generation) = self.tool_runs.slot().map(|slot| (slot.run, slot.generation)).expect("aborting slot");
                    if let Some(finalize) = selected_entry_mut!(self.tool_runs).and_then(|entry| entry.finalize.take()) {
                        self.tool_runs.retire_owners(None, Vec::new(), Some(finalize));
                        return Ok(());
                    }
                    if self.apply_tool_run_driver_event(ToolRunEvent::AbortComplete { run, generation }) == Some(ToolRunEffect::RetireProvisional) {
                        self.tool_runs.discard_provisional();
                        self.mark_tool_run_document_dirty();
                    }
                }
                Ok(())
            }
            ToolRunState::Starting => self.admit_tool_run_job().await,
            ToolRunState::Running | ToolRunState::Paused | ToolRunState::Complete => {
                self.watch_tool_run_generations();
                if self.refold_tool_run(deadline) || self.refresh_tool_run_member(deadline)? {
                    return Ok(());
                }
                let entry = selected_entry!(self.tool_runs).expect("live slot");
                let wants_job = match entry.slot.state {
                    ToolRunState::Running => true,
                    ToolRunState::Paused => entry.pending_step,
                    _ => false,
                };
                if wants_job && entry.job.is_none() {
                    return self.admit_tool_run_job().await;
                }
                if wants_job {
                    self.step_tool_run_job(deadline)?;
                }
                Ok(())
            }
            ToolRunState::Finalizing => {
                if self.refresh_tool_run_member(deadline)? {
                    return Ok(());
                }
                self.finalize_tool_run_turn(deadline).await
            }
            ToolRunState::Finalized | ToolRunState::Aborted | ToolRunState::Faulted => Ok(()),
        }
    }

    /// 🔁️ `true` while a refold still owns this turn; a refold waiting only for its job's boundary lets the job step.
    fn refold_tool_run(&mut self, deadline: u64) -> bool {
        let Some(entry) = selected_entry_mut!(self.tool_runs).filter(|entry| entry.refold.is_some()) else { return false };
        if entry.job.is_none() {
            entry.settle_refold();
        }
        match entry.refold_turn(deadline) {
            ToolRunRefoldTurn::Pending => true,
            ToolRunRefoldTurn::AwaitingBoundary => false,
            ToolRunRefoldTurn::Swapped => {
                self.mark_tool_run_document_dirty();
                false
            }
        }
    }

    async fn admit_tool_run_job(&mut self) -> Result<(), Fault> {
        let Some(entry) = selected_entry!(self.tool_runs) else { return Ok(()) };
        let (run, generation, state) = (entry.slot.run, entry.slot.generation, entry.slot.state);
        entry.port.wake();
        match self.build_tool_run_job_slot(entry, ToolRunJobPurpose::Run) {
            Ok(Some(job)) => {
                selected_entry_mut!(self.tool_runs).expect("live slot").job = Some(job);
                if state == ToolRunState::Starting {
                    self.apply_tool_run_driver_event(ToolRunEvent::JobAdmitted { run, generation });
                }
            }
            Ok(None) | Err(_) => self.fault_tool_run(run, generation),
        }
        self.mark_tool_run_ui_dirty();
        Ok(())
    }

    fn fault_tool_run(&mut self, run: u64, generation: u32) {
        if self.apply_tool_run_driver_event(ToolRunEvent::JobFault { run, generation }) == Some(ToolRunEffect::DiscardProvisional) {
            self.tool_runs.close_current_job();
            self.tool_runs.discard_provisional();
            if let Some(entry) = selected_entry_mut!(self.tool_runs) {
                entry.framework_step(ToolRunStepKind::Danger, TOOL_RUN_REASON_CONFLICT, &[ToolRunStepArg::Unsigned(0)]);
            }
            self.mark_tool_run_document_dirty();
        }
    }

    /// 🦶️ Drives the current job until the turn deadline, a pause, a single step or a terminal outcome.
    fn step_tool_run_job(&mut self, deadline: u64) -> Result<(), Fault> {
        loop {
            let Some(entry) = selected_entry_mut!(self.tool_runs) else { return Ok(()) };
            let single = entry.slot.state == ToolRunState::Paused;
            let (run, generation, purpose) = (entry.slot.run, entry.slot.generation, entry.job.as_ref().map(|job| job.purpose));
            let Some(job) = entry.job.as_mut() else { return Ok(()) };
            let now = semio_framework_job::default_now_us().unwrap_or(0);
            let fuel = if single { 1 } else { semio_framework_job::INTERACTIVE_LANE_FUEL };
            let budget = semio_framework_job::StepBudget::from_duration(fuel, now, semio_framework_job::INTERACTIVE_LANE_WALL_US).unwrap_or(semio_framework_job::StepBudget::new(fuel, u64::MAX));
            let mut verdict = None;
            let interactive: &mut dyn semio_framework_job::InteractiveJob = match &mut job.job {
                ToolRunJobHandle::Plain(job) => job.as_mut(),
                ToolRunJobHandle::Retargetable(job) => job.as_mut(),
            };
            let mut outcome = semio_framework_job::drive_step(
                interactive,
                TOOL_RUN_JOB_SITE,
                job.operation,
                job.generation,
                semio_framework_job::InteractiveStage::InteractiveStep,
                budget,
                job.cancel.clone(),
                semio_framework_job::default_now_us,
                &mut job.preview_sequence,
                &mut verdict,
            );
            if single && !matches!(outcome, semio_framework_job::StepOutcome::Yield | semio_framework_job::StepOutcome::CheckpointReady(_)) {
                entry.pending_step = false;
            }
            let mut terminal = false;
            match &mut outcome {
                semio_framework_job::StepOutcome::Yield => {}
                semio_framework_job::StepOutcome::PreviewReady(payload) => {
                    let bytes = job_payload_bytes(payload, TOOL_RUN_TICK_BYTES_MAX);
                    close_job_payload(payload);
                    let tick = bytes
                        .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("toolRun.tick-bytes"), "tool run tick exceeds its byte cap"))
                        .and_then(|bytes| ToolRunTick::decode(&bytes).map_err(|error| Fault::new(FaultOrigin::Framework, FaultCode::new("toolRun.tick-decode"), format!("{error:?}"))));
                    let receipt = match tick {
                        Ok(tick) => entry.apply_tick(tick, &mut self.tool_runs.discarded),
                        Err(fault) => Err(fault),
                    };
                    match receipt {
                        Ok(receipt) => {
                            if let (Some(finalize), ToolRunJobPurpose::Revalidate) = (entry.finalize.as_mut(), purpose.unwrap_or(ToolRunJobPurpose::Run)) {
                                finalize.retracted = finalize.retracted.saturating_add(receipt.retracted);
                            }
                            if receipt.capped && purpose == Some(ToolRunJobPurpose::Run) {
                                self.complete_tool_run_job(run, generation);
                                terminal = true;
                            }
                            self.mark_tool_run_ui_dirty();
                        }
                        Err(_) => {
                            self.fault_tool_run(run, generation);
                            terminal = true;
                        }
                    }
                }
                semio_framework_job::StepOutcome::CheckpointReady(checkpoint) => {
                    entry.checkpoint = job_payload_bytes(&checkpoint.state, semio_framework_job::JOB_PAYLOAD_OPERATION_BYTES);
                    close_job_payload(&mut checkpoint.state);
                    entry.settle_refold();
                }
                semio_framework_job::StepOutcome::Complete(_) => {
                    close_step_outcome(&mut outcome);
                    entry.settle_refold();
                    match purpose {
                        Some(ToolRunJobPurpose::Revalidate) => self.complete_tool_run_revalidation(),
                        _ => self.complete_tool_run_job(run, generation),
                    }
                    terminal = true;
                }
                semio_framework_job::StepOutcome::Cancelled | semio_framework_job::StepOutcome::Fault(_) => {
                    close_step_outcome(&mut outcome);
                    self.fault_tool_run(run, generation);
                    terminal = true;
                }
            }
            self.drain_tool_run_port();
            if terminal || single || selected_entry!(self.tool_runs).is_none_or(|entry| entry.port.is_waiting()) || semio_framework_job::default_now_us().is_none_or(|now| now >= deadline) {
                return Ok(());
            }
            if !selected_entry!(self.tool_runs).is_some_and(|entry| entry.job.is_some() && matches!(entry.slot.state, ToolRunState::Running | ToolRunState::Finalizing)) {
                return Ok(());
            }
        }
    }

    /// 🏁️ A finished job's completion — and, for a READ-ONLY run, its finalization too.
    ///
    /// 🪪️ `Complete` means "the job is done and the run awaits the finalize that publishes its
    /// provisional edits". A run that declares `mutating: false` authors no provisional edit at all, so
    /// there is nothing for a finalize to publish and nothing for a user to review: leaving it parked in
    /// `Complete` only holds the tool's single run slot open, and a `toolRunStart` against a non-terminal
    /// run is `ToolRunRejection::Busy`. That is how generation3d's read-only `previewEval` ran exactly
    /// ONCE per session — every later start, whether a poll's or a gesture's own, was refused by the
    /// finished run still sitting in the slot, and the 3d preview stopped re-evaluating
    /// (`📓️preview-rearm-after-inspector-edit-2026-09-14.md`, `📋️tool-run-contract.md` §2.2). Asking a
    /// read-only run's owner to dispatch a finalize it has nothing to finalize is a round trip the host
    /// can always lose: it happens on the host's own refresh cadence, and a run action that publishes
    /// nothing moves no UI that would provoke the next pass.
    fn complete_tool_run_job(&mut self, run: u64, generation: u32) {
        let resident = selected_entry_mut!(self.tool_runs).is_some_and(|entry| entry.definition.mutating && entry.job.as_mut().is_some_and(|job| job.retargetable().is_some()));
        if resident {
            selected_entry_mut!(self.tool_runs).expect("a resident job has a slot").settle_refold();
        } else {
            self.tool_runs.close_current_job();
        }
        self.apply_tool_run_driver_event(ToolRunEvent::JobComplete { run, generation });
        if let Some(entry) = selected_entry_mut!(self.tool_runs) {
            entry.pending_step = false;
        }
        if selected_entry!(self.tool_runs).is_some_and(|entry| !entry.definition.mutating && entry.slot.state == ToolRunState::Complete) {
            let (run, generation) = self.tool_runs.slot().map(|slot| (slot.run, slot.generation)).expect("a complete run has a slot");
            if let Some(ToolRunEffect::BeginFinalize) = self.apply_tool_run_driver_event(ToolRunEvent::Finalize { run, generation }) {
                if let Some(entry) = selected_entry_mut!(self.tool_runs) {
                    entry.finalize = Some(ToolRunFinalize { phase: ToolRunFinalizePhase::Pending, publication: None, retracted: 0, published: false });
                }
            }
        }
        self.mark_tool_run_document_dirty();
    }

    fn complete_tool_run_revalidation(&mut self) {
        self.tool_runs.close_current_job();
        let Some(entry) = selected_entry_mut!(self.tool_runs) else { return };
        let (run, generation) = (entry.slot.run, entry.slot.generation);
        let retracted = entry.finalize.as_ref().map_or(0, |finalize| finalize.retracted);
        if retracted == 0 {
            if let Some(finalize) = entry.finalize.as_mut() {
                finalize.phase = ToolRunFinalizePhase::Publishing;
            }
            return;
        }
        entry.conflicts = entry.conflicts.saturating_add(retracted);
        entry.framework_step(ToolRunStepKind::Danger, TOOL_RUN_REASON_CONFLICT, &[ToolRunStepArg::Unsigned(u64::from(retracted))]);
        let finalize = entry.finalize.take();
        self.tool_runs.retire_owners(None, Vec::new(), finalize);
        self.apply_tool_run_driver_event(ToolRunEvent::RevalidationConflicts { run, generation });
        self.mark_tool_run_document_dirty();
    }

    /// 🏁️ Finalize (§2.7.4): freshness refold on the head, optional revalidate job, one outbound batched `Edit`.
    async fn finalize_tool_run_turn(&mut self, deadline: u64) -> Result<(), Fault> {
        let store_generation = self.store.generation();
        let member_generation = self.tool_run_member_generation();
        let entry = selected_entry_mut!(self.tool_runs).expect("finalizing slot");
        let phase = entry.finalize.as_ref().map_or(ToolRunFinalizePhase::Pending, |finalize| finalize.phase);
        let moved = match (entry.member.as_ref(), member_generation) {
            (Some(member), Some(generation)) => member.base_generation != generation,
            (Some(_), None) => false,
            (None, _) => entry.base_generation != store_generation,
        };
        let republish = matches!(phase, ToolRunFinalizePhase::Pending | ToolRunFinalizePhase::Revalidating) || (phase == ToolRunFinalizePhase::Publishing && entry.member.is_some());
        if moved && republish {
            entry.replace_base(self.store.snapshot_owner());
            entry.base_generation = store_generation;
            entry.begin_refold(true);
            if let (Some(member), Some(generation)) = (entry.member.as_mut(), member_generation) {
                member.base_generation = generation;
                member.rebase = true;
                member.emit = None;
            }
            entry.framework_step(ToolRunStepKind::Warning, TOOL_RUN_REASON_REBASING, &[]);
            if let Some(finalize) = entry.finalize.as_mut() {
                finalize.phase = ToolRunFinalizePhase::Pending;
                finalize.retracted = 0;
            }
            self.tool_runs.close_current_job();
            return Ok(());
        }
        if self.refold_tool_run(deadline) {
            return Ok(());
        }
        match phase {
            ToolRunFinalizePhase::Pending => {
                if selected_entry!(self.tool_runs).is_some_and(|entry| entry.job.as_ref().is_some_and(|job| job.purpose == ToolRunJobPurpose::Run)) {
                    self.tool_runs.close_current_job();
                    return Ok(());
                }
                let entry = selected_entry!(self.tool_runs).expect("finalizing slot");
                let (run, generation) = (entry.slot.run, entry.slot.generation);
                let next = if entry.definition.revalidate_job.is_some() && !(entry.provisional.is_empty() && entry.member.as_ref().is_none_or(|member| member.ops.is_empty())) {
                    match self.build_tool_run_job_slot(entry, ToolRunJobPurpose::Revalidate) {
                        Ok(Some(job)) => {
                            selected_entry_mut!(self.tool_runs).expect("finalizing slot").job = Some(job);
                            ToolRunFinalizePhase::Revalidating
                        }
                        Ok(None) | Err(_) => return self.reject_tool_run_publication(run, generation),
                    }
                } else {
                    ToolRunFinalizePhase::Publishing
                };
                if let Some(finalize) = selected_entry_mut!(self.tool_runs).and_then(|entry| entry.finalize.as_mut()) {
                    finalize.phase = next;
                }
                Ok(())
            }
            ToolRunFinalizePhase::Revalidating => self.step_tool_run_job(deadline),
            ToolRunFinalizePhase::Publishing => self.publish_tool_run(deadline).await,
            ToolRunFinalizePhase::Closing => self.close_tool_run_publication(),
        }
    }

    fn reject_tool_run_publication(&mut self, run: u64, generation: u32) -> Result<(), Fault> {
        let Some(entry) = selected_entry_mut!(self.tool_runs) else { return Ok(()) };
        entry.framework_step(ToolRunStepKind::Danger, TOOL_RUN_REASON_CONFLICT, &[ToolRunStepArg::Unsigned(entry.provisional.len() as u64)]);
        let finalize = entry.finalize.take();
        self.tool_runs.close_current_job();
        self.tool_runs.retire_owners(None, Vec::new(), finalize);
        self.apply_tool_run_driver_event(ToolRunEvent::StoreRejected { run, generation });
        self.mark_tool_run_ui_dirty();
        Ok(())
    }

    /// 🏷️ The history row label of a transaction a finalized run published (`<appId>#<toolId>` of a declared tool
    /// run): the tool's own label in every locale, so the row reads the same after a reload.
    pub(crate) fn tool_run_transaction_label(&self, app_id: &str, transaction: &protocol::TransactionRef) -> Option<LocalizedLabel> {
        let tool_id = transaction.tool.strip_prefix(app_id)?.strip_prefix('#')?;
        self.registry.tool_run(tool_id).map(|(label, _)| label.clone())
    }

    /// ♻️ Each folded op leaves the root it was prepared against returned to the Store; reclaim it before the
    /// next fold, or a large finalize keeps one whole document per op (see `reclaim_document_snapshot_read_returns`).
    async fn publish_tool_run(&mut self, deadline: u64) -> Result<(), Fault> {
        if selected_entry!(self.tool_runs).is_some_and(|entry| entry.member.is_some()) {
            return self.publish_tool_run_member(deadline).await;
        }
        let entry = selected_entry_mut!(self.tool_runs).expect("finalizing slot");
        let (run, generation) = (entry.slot.run, entry.slot.generation);
        if entry.provisional.is_empty() {
            entry.finalize.as_mut().expect("finalize owner").phase = ToolRunFinalizePhase::Closing;
            return Ok(());
        }
        if entry.finalize.as_ref().is_some_and(|finalize| finalize.publication.is_none()) {
            let transaction = tool_run_transaction(self.app.instance_id().await, &entry.tool_id, &entry.actor, run);
            self.store.set_local_actor_id(Some(entry.actor.clone())).map_err(|error| error.into_fault())?;
            match self.store.begin_outbound_apply_batch(
                semio_framework_job::allocate_operation_id(),
                entry.base_generation,
                self.store.content_revision(),
                entry.actor.clone(),
                entry.provisional.clone(),
                None,
                self.artifact_one_item_factory.as_ref(),
                Some(transaction),
            ) {
                Ok(publication) => entry.finalize.as_mut().expect("finalize owner").publication = Some(publication),
                Err(_) => return self.reject_tool_run_publication(run, generation),
            }
        }
        loop {
            if !self.reclaim_document_snapshot_read_returns(PUBLICATION_SNAPSHOT_READ_RECLAIM_STEPS)? {
                if semio_framework_job::default_now_us().is_none_or(|now| now >= deadline) {
                    return Ok(());
                }
                continue;
            }
            let entry = selected_entry_mut!(self.tool_runs).expect("finalizing slot");
            let publication = entry.finalize.as_mut().and_then(|finalize| finalize.publication.as_mut()).expect("admitted publication");
            match self.store.advance_apply_batch(publication, TOOL_RUN_PUBLICATION_GRANT) {
                Ok(store::ArtifactStoreOneItemAdvance::Published(_)) => {
                    let group_id = entry.identity.id.group_id();
                    let tool_id = entry.tool_id.clone();
                    let actor = entry.actor.clone();
                    self.store.stamp_tail_group_id(&group_id).await.map_err(|error| error.into_fault())?;
                    let publication = selected_entry_mut!(self.tool_runs).and_then(|entry| entry.finalize.as_mut()).and_then(|finalize| finalize.publication.as_mut()).expect("published publication");
                    self.store.flush_published_apply_batch(publication).await.map_err(|error| error.into_fault())?;
                    publication.acknowledge();
                    let edit_id = self.store.envelope().vcs.edits.last().map(|edit| edit.id.clone());
                    let label = self.registry.tool_run(&tool_id).map(|(label, _)| label.clone());
                    self.record_command(&tool_id, ActionKind::Mutation, label, edit_id, Vec::new(), None);
                    self.revalidate_interaction_state_after_document_change(&ActionMeta { actor, instance_id: self.live_runtime_instance_id.unwrap_or(1), view_state: None }).await?;
                    let entry = selected_entry_mut!(self.tool_runs).expect("finalizing slot");
                    let finalize = entry.finalize.as_mut().expect("finalize owner");
                    finalize.published = true;
                    finalize.phase = ToolRunFinalizePhase::Closing;
                    return Ok(());
                }
                Ok(store::ArtifactStoreOneItemAdvance::Blocked) => return Ok(()),
                Ok(_) => {}
                Err(_) => return self.reject_tool_run_publication(run, generation),
            }
            if semio_framework_job::default_now_us().is_none_or(|now| now >= deadline) {
                return Ok(());
            }
        }
    }

    /// 🎨️ The finalize SUCCEEDED, so the provisional ops are released — but the run's payload is
    /// its result, not provisional work, and its declared windows keep rendering it once the run
    /// is `Finalized`. See `ToolRunLedger::release_provisional`.
    fn close_tool_run_publication(&mut self) -> Result<(), Fault> {
        let entry = selected_entry_mut!(self.tool_runs).expect("finalizing slot");
        let (run, generation) = (entry.slot.run, entry.slot.generation);
        let finalize = entry.finalize.as_mut().expect("finalize owner");
        if let Some(publication) = finalize.publication.as_mut() {
            match publication.close_step(TOOL_RUN_PUBLICATION_GRANT).map_err(|error| plugin_sdk_fault(error.into_message()))? {
                store::SnapshotRetirementStep::Complete if publication.terminal_is_empty() => finalize.publication = None,
                store::SnapshotRetirementStep::Complete => return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("toolRun.publication-close"), "tool run publication closed without its terminal-empty witness")),
                _ => return Ok(()),
            }
            return Ok(());
        }
        entry.finalize = None;
        if self.apply_tool_run_driver_event(ToolRunEvent::PublicationComplete { run, generation }) == Some(ToolRunEffect::ReleaseProvisional) {
            let store_generation = self.store.generation();
            let member_generation = self.tool_run_member_generation();
            let head = self.store.snapshot_owner();
            self.tool_runs.release_provisional(true);
            let entry = selected_entry_mut!(self.tool_runs).expect("finalized slot");
            entry.replace_base(head);
            let overlay = Arc::clone(&entry.base);
            entry.replace_overlay(overlay);
            entry.base_generation = store_generation;
            if let (Some(member), Some(generation)) = (entry.member.as_mut(), member_generation) {
                member.base_generation = generation;
            }
        }
        self.mark_tool_run_document_dirty();
        Ok(())
    }

    /// 🧩️ The member a run declaring `ToolRunDefinition::member` edits: the one live owned child composed under `slot`, with
    /// the member store generation the run rests on. No such child, or several, refuse the start by name.
    fn tool_run_member_target(&self, slot: &str) -> Result<ToolRunMemberRun, Fault> {
        let mut candidates = self.children.entries().filter(|entry| entry.owner.slot == slot);
        let (Some(entry), None) = (candidates.next(), candidates.next()) else {
            return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("toolRun.member-unavailable"), format!("a member tool run needs exactly one live owned child in slot '{slot}'")));
        };
        Ok(ToolRunMemberRun {
            slot: slot.to_string(),
            child_id: entry.owner.child_id.clone(),
            dialect: entry.reference.dialect.clone(),
            base_generation: entry.member.visit_member(ToolRunMemberGeneration),
            ops: Vec::new(),
            shown: 0,
            rebase: false,
            owners: None,
            children: None,
            stale: Vec::new(),
            emit: None,
        })
    }

    /// 🔢️ The live generation of the member the selected run edits; `None` for a document run or a member that is gone.
    fn tool_run_member_generation(&self) -> Option<u64> {
        let member = selected_entry!(self.tool_runs)?.member.as_ref()?;
        self.children.get(&(member.slot.clone(), member.child_id.clone())).map(|child| child.member.visit_member(ToolRunMemberGeneration))
    }

    /// 🔁️ Brings the selected member run's composed read up to its provisional ops within the turn wall budget: retires the
    /// reads it replaced, folds the ops the overlay does not show yet (all of them after a rebase) and leases the overlay in
    /// the member's place once every op is shown. `true` while the fold still owns this turn; a fold that cannot apply its
    /// ops (they do not decode as the member's vocabulary) faults the run.
    fn refresh_tool_run_member(&mut self, deadline: u64) -> Result<bool, Fault> {
        let Some(mut member) = selected_entry_mut!(self.tool_runs).and_then(|entry| entry.member.take()) else { return Ok(false) };
        let outcome = self.refresh_member_overlay(&mut member, deadline);
        let entry = selected_entry_mut!(self.tool_runs).expect("a member run keeps its slot");
        entry.member = Some(member);
        let (run, generation) = (entry.slot.run, entry.slot.generation);
        match outcome {
            Ok(Some((pending, conflicts, rebased))) => {
                entry.conflicts = entry.conflicts.saturating_add(conflicts);
                if !pending {
                    if rebased {
                        self.mark_tool_run_document_dirty();
                    } else {
                        self.mark_tool_run_ui_dirty();
                    }
                }
                Ok(pending)
            }
            Ok(None) => Ok(false),
            Err(_) => {
                self.fault_tool_run(run, generation);
                Ok(false)
            }
        }
    }

    /// 🔁️ [`Self::refresh_tool_run_member`] on a member taken out of its entry: `(fold pending, conflicts, rebased)`, or
    /// `None` when the overlay already shows every op.
    fn refresh_member_overlay(&mut self, member: &mut ToolRunMemberRun, deadline: u64) -> Result<Option<(bool, u32, bool)>, Fault> {
        let stale = std::mem::take(&mut member.stale);
        self.retire_tool_run_views(stale, &mut member.stale)?;
        if !member.rebase && member.shown == member.ops.len() {
            return Ok(None);
        }
        let child = self.children.get(&(member.slot.clone(), member.child_id.clone())).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("toolRun.member-gone"), format!("the member {}/{} a tool run edits is gone", member.slot, member.child_id)))?;
        let rebased = member.rebase;
        let folded = child.member.visit_member(ToolRunMemberFold { owners: &mut member.owners, ops: &member.ops, shown: member.shown, rebase: member.rebase, deadline_us: deadline })?;
        member.rebase = false;
        member.shown = folded.shown;
        let pending = folded.shown < member.ops.len();
        if !pending {
            let next = match folded.read {
                Some((read, revision)) => Some(self.child_content_root.with_member_read(&member.slot, &member.child_id, &member.dialect, revision, read)?),
                None => None,
            };
            if let Some(previous) = std::mem::replace(&mut member.children, next) {
                self.retire_tool_run_views(vec![previous], &mut member.stale)?;
            }
        }
        Ok(Some((pending, folded.conflicts, rebased)))
    }

    /// 🧹️ Retires a member run's composed reads in order through the child-content retirements, one admitted generation
    /// each; a refused admission hands the view it could not retire and every later one back to `unretired`.
    fn retire_tool_run_views(&mut self, views: Vec<ChildContentView>, unretired: &mut Vec<ChildContentView>) -> Result<(), Fault> {
        let mut views = views.into_iter();
        while let Some(view) = views.next() {
            match self.admit_child_content_publication() {
                Ok(generation) => {
                    self.child_content_retirements.insert_admitted(generation, ChildContentRetirement::new(view, false));
                    self.child_content_generation = generation;
                }
                Err(fault) => {
                    unretired.push(view);
                    unretired.extend(views);
                    return Err(fault);
                }
            }
        }
        Ok(())
    }

    /// 🏁️ A member run's finalize (§12, §20.14): its provisional ops — at most `TOOL_RUN_MEMBER_OPS_MAX` — decoded through
    /// the member's own vocabulary within the turn wall budget, then published as ONE composite group whose member edit
    /// carries the run's `TransactionRef` and group id: one history row whose mutations are the member's leaves, editable on
    /// that member store. A member that is gone or ops that do not decode reject the publication like a conflicting parent
    /// batch.
    async fn publish_tool_run_member(&mut self, deadline: u64) -> Result<(), Fault> {
        let app_instance_id = self.app.instance_id().await;
        let entry = selected_entry_mut!(self.tool_runs).expect("finalizing slot");
        let (run, generation) = (entry.slot.run, entry.slot.generation);
        let member = entry.member.as_mut().expect("a member run");
        if member.ops.is_empty() {
            entry.finalize.as_mut().expect("finalize owner").phase = ToolRunFinalizePhase::Closing;
            return Ok(());
        }
        let decoded = self.children.get(&(member.slot.clone(), member.child_id.clone())).map(|child| child.member.visit_member(ToolRunMemberEmit { slot: &member.slot, child_id: &member.child_id, ops: &member.ops, emit: &mut member.emit, deadline_us: deadline }));
        match decoded {
            Some(Ok(true)) => {}
            Some(Ok(false)) => return Ok(()),
            _ => return self.reject_tool_run_publication(run, generation),
        }
        let entry = selected_entry_mut!(self.tool_runs).expect("finalizing slot");
        let emit = entry.member.as_mut().and_then(|member| member.emit.take()).expect("a decoded member emission");
        let transaction = tool_run_transaction(app_instance_id, &entry.tool_id, &entry.actor, run);
        let (tool_id, group_id) = (entry.tool_id.clone(), entry.identity.id.group_id());
        let meta = ActionMeta { actor: entry.actor.clone(), instance_id: self.live_runtime_instance_id.unwrap_or(1), view_state: None };
        if self.dispatch_emit_group(&tool_id, &[], std::slice::from_ref(&emit), None, Vec::new(), Vec::new(), UiDirtyScope::Full, &meta, Some(group_id), Some(transaction)).await.is_err() {
            return self.reject_tool_run_publication(run, generation);
        }
        self.revalidate_interaction_state_after_document_change(&meta).await?;
        let finalize = selected_entry_mut!(self.tool_runs).and_then(|entry| entry.finalize.as_mut()).expect("finalize owner");
        finalize.published = true;
        finalize.phase = ToolRunFinalizePhase::Closing;
        Ok(())
    }

    /// ♻️ One bounded unit of member-run retirement: one alias of a member run's typed owners handed to its member store's
    /// alias retirement (displaced aliases of live runs, every alias of a run that left its slot), else the composed reads of
    /// a fully retired member run. `None` when nothing member-owned is retiring or an alias retirement is still stepping.
    fn tool_run_member_retire_step(&mut self) -> Result<Option<PluginCloseStep>, Fault> {
        if self.tool_runs.snapshot_retirement.is_some() {
            return Ok(None);
        }
        let VcsArtifactApp { tool_runs, children, .. } = self;
        let live = tool_runs.entries.iter_mut().filter_map(|entry| entry.member.as_mut()).map(|member| (member, false));
        let retired = tool_runs.retired_members.iter_mut().map(|member| (member, true));
        for (member, everything) in live.chain(retired) {
            let Some(child) = children.get(&(member.slot.clone(), member.child_id.clone())) else {
                member.owners = None;
                continue;
            };
            let Some(owners) = member.owners.as_deref_mut().filter(|owners| everything || owners.has_displaced()) else { continue };
            if let Some(retirement) = child.member.visit_member(ToolRunMemberRetire { owners, everything })? {
                tool_runs.snapshot_retirement = Some(retirement);
                return Ok(Some(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }));
            }
        }
        let Some(index) = self.tool_runs.retired_members.iter().position(|member| member.owners.as_deref().is_none_or(ToolRunMemberOwners::is_empty)) else { return Ok(None) };
        let mut member = self.tool_runs.retired_members.swap_remove(index);
        let views = member.children.take().into_iter().chain(std::mem::take(&mut member.stale)).collect();
        if let Err(fault) = self.retire_tool_run_views(views, &mut member.stale) {
            self.tool_runs.retired_members.push(member);
            return Err(fault);
        }
        Ok(Some(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }))
    }

    /// ♻️ One bounded retirement unit of the tool run ledger, member-owned aliases and reads first.
    fn tool_run_retire_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<Option<PluginCloseStep>, Fault> {
        match self.tool_run_member_retire_step()? {
            Some(step) => Ok(Some(step)),
            None => self.tool_runs.retire_step(&mut self.store, maximum_items, maximum_bytes),
        }
    }

    /// 🚪️ One bounded close unit of the tool run ledger (document close, retirement, reload): every run ends as an abort and
    /// its owners — member-owned ones against their member store — retire.
    pub(crate) fn tool_run_close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
        self.tool_runs.begin_close();
        Ok(self.tool_run_retire_step(maximum_items, maximum_bytes)?.unwrap_or(PluginCloseStep::Complete))
    }
}

/// 🧾️ The transaction a finalized run publishes as: tool `<appId>#<toolId>`, id minted from the run's actor, the host
/// clock and the run counter, so every op of the run's one edit is one history row that time travel can open.
pub(crate) fn tool_run_transaction(app_id: &str, tool_id: &str, actor: &str, run: u64) -> protocol::TransactionRef {
    let clock = semio_framework_tool_machine::authoring_clock(run);
    protocol::TransactionRef::mint(&ActorId(actor.to_string()), &clock, format!("{app_id}#{tool_id}"))
}
//#endregion 🔖️Driver

//#region 🔖️Panel
fn tool_run_step_text(definition: &ToolRunDefinition, step: &ToolRunStep, locale: Locale) -> String {
    let template = match ToolRunLabel::for_reason(step.reason) {
        Some(label) => label.text(locale).to_string(),
        None => definition.reason(step.reason).map_or_else(|| step.reason.to_string(), |reason| reason.template.resolve(Terminology::Native, locale).to_string()),
    };
    let text = tool_run_format(&template, |name| name.parse::<usize>().ok().and_then(|index| step.args.get(index)).map(|arg| arg.to_plain_string()));
    if step.repeat > 1 {
        format!("{text} ×{}", step.repeat)
    } else {
        text
    }
}

fn tool_run_step_tone(kind: ToolRunStepKind) -> Tone {
    match kind {
        ToolRunStepKind::Info => Tone::Info,
        ToolRunStepKind::Success => Tone::Success,
        ToolRunStepKind::Warning => Tone::Warning,
        ToolRunStepKind::Danger => Tone::Danger,
    }
}

fn tool_run_verdict_tone(verdict: ToolRunVerdict) -> Tone {
    match verdict {
        ToolRunVerdict::Testing => Tone::Neutral,
        ToolRunVerdict::Success => Tone::Success,
        ToolRunVerdict::Warning => Tone::Warning,
        ToolRunVerdict::Danger => Tone::Danger,
    }
}

fn tool_run_state_label(state: ToolRunState) -> ToolRunLabel {
    state.label()
}

impl<A: ArtifactApp> ToolRunLedger<A> {
    /// 🪧️ The framework ToolRun panel (§2.6) as a `ComponentTree` root `framework.toolRun`: a ready group
    /// `framework.toolRun.ready` with an enabled Start for `ready_tool` (the active run-declaring tool) while this
    /// instance holds no run of it, then one group `framework.toolRun.<run>` per run, oldest first, labelled by
    /// `tool_label` of its tool.
    pub fn panel(&mut self, controller_id: &str, locale: Locale, ready_tool: Option<&str>, tool_label: impl Fn(&str) -> Option<String>) -> UiAssemblyResult<BuiltNode> {
        let error = ui_assembly_error;
        let mut groups = BuiltChildren::default();
        if let Some(tool_id) = ready_tool.filter(|tool_id| !self.entries.iter().any(|entry| entry.tool_id == *tool_id)) {
            let label = tool_label(tool_id).unwrap_or_else(|| tool_id.to_string());
            groups.try_push(tool_run_panel_ready_group(tool_id, controller_id, locale, &label)?).map_err(|_| error("tool-run-panel.groups"))?;
        }
        for entry in &mut self.entries {
            let label = tool_label(&entry.tool_id).unwrap_or_else(|| entry.tool_id.clone());
            groups.try_push(tool_run_panel_group(entry, controller_id, locale, &label)?).map_err(|_| error("tool-run-panel.groups"))?;
        }
        column()
            .try_label(if locale == Locale::De { "Werkzeugläufe" } else { "Tool runs" })
            .map_err(|_| error("tool-run-panel.label"))?
            .try_id(semio_framework_tool_run::TOOL_RUN_PANEL_ID)
            .map_err(|_| error("tool-run-panel.id"))?
            .try_children(groups)
            .map_err(|_| error("tool-run-panel.groups"))?
            .try_build()
            .map_err(|_| error("tool-run-panel.build"))
    }
}

/// ▶️ The ready group of a run-declaring tool with no run yet: its status and a real Start button carrying the tool id.
fn tool_run_panel_ready_group(tool_id: &str, controller_id: &str, locale: Locale, label: &str) -> UiAssemblyResult<BuiltNode> {
    let error = ui_assembly_error;
    let scope = format!("{}.ready", semio_framework_tool_run::TOOL_RUN_PANEL_ID);
    let status = text(Label(UiText::clipped(ToolRunLabel::ReadyToStart.text(locale))))
        .live(Liveness::Polite)
        .try_id(format!("{scope}.status"))
        .map_err(|_| error("tool-run-panel.ready-status-id"))?
        .try_build()
        .map_err(|_| error("tool-run-panel.ready-status"))?;
    let mut arguments = UiMapBuilder::try_new().ok_or_else(|| error("tool-run-panel.ready-args"))?;
    arguments.push(TOOL_RUN_ARG_TOOL_ID.to_string(), UiValue::Text(UiText::clipped(tool_id))).map_err(|_| error("tool-run-panel.ready-args"))?;
    let action = ToolRunAction::Start;
    let action_id = ActionId::try_v1(controller_id, action.id()).ok_or_else(|| error("tool-run-panel.action-id"))?;
    let start = button(Label(UiText::clipped(action.label().text(locale))))
        .try_id(format!("{scope}.{}", action.id()))
        .map_err(|_| error("tool-run-panel.button-id"))?
        .try_shortcut(action.chord())
        .map_err(|_| error("tool-run-panel.button-shortcut"))?
        .try_on_with(Trigger::Activate, action_id, UiValue::Map(arguments.finish()))
        .map_err(|_| error("tool-run-panel.button-binding"))?
        .try_build()
        .map_err(|_| error("tool-run-panel.button"))?;
    let mut buttons = BuiltChildren::default();
    buttons.try_push(start).map_err(|_| error("tool-run-panel.buttons"))?;
    let toolbar = row().try_id(format!("{scope}.actions")).map_err(|_| error("tool-run-panel.actions-id"))?.try_children(buttons).map_err(|_| error("tool-run-panel.actions"))?.try_build().map_err(|_| error("tool-run-panel.actions-build"))?;
    let mut children = BuiltChildren::default();
    for child in [status, toolbar] {
        children.try_push(child).map_err(|_| error("tool-run-panel.children"))?;
    }
    column()
        .try_label(label)
        .map_err(|_| error("tool-run-panel.label"))?
        .try_id(scope)
        .map_err(|_| error("tool-run-panel.id"))?
        .try_children(children)
        .map_err(|_| error("tool-run-panel.children"))?
        .try_build()
        .map_err(|_| error("tool-run-panel.build"))
}

/// 🪧️ One run's panel group (§2.6): polite status, progressbar, real buttons with `aria-keyshortcuts` addressing the
/// run by id, step log (live off) and a keyboard-navigable trace list; every id is scoped `framework.toolRun.<run>.`.
///
/// 👁️ The throttle belongs to the ANNOUNCEMENT, never to the text. Publishing the last ANNOUNCED
/// string froze the visible pill at whatever stage the run was in when it was first announced:
/// a `Finalized` run still read `Evaluating nodes (1/2)` on 6021 at 18:28 while its own progress
/// bar had moved on (ticket 26/09/09/PROCEDURAL-3D-END-TO-END). A sighted reader is watching the
/// same string a reader hears, so the string is always current and only `live` is rationed.
fn tool_run_panel_group<A: ArtifactApp>(entry: &mut ToolRunEntry<A>, controller_id: &str, locale: Locale, label: &str) -> UiAssemblyResult<BuiltNode> {
    let error = ui_assembly_error;
    let scope = semio_framework_tool_run::tool_run_panel_group_id(entry.slot.run);
    let state = entry.slot.state;
    let stage_count = entry.definition.stages.len();
    let stage_label = entry.definition.stage(entry.stage).map_or_else(String::new, |stage| stage.label.resolve(Terminology::Native, locale).to_string());
    let status = format!("{} · {stage_label} ({}/{stage_count})", tool_run_state_label(state).text(locale), usize::from(entry.stage) + 1);
    let now_ms = semio_framework_job::default_now_ms().unwrap_or(0);
    let announce = match entry.announced.as_ref() {
        Some((announced_state, at, announced)) => *announced_state != state || (*announced != status && now_ms.saturating_sub(*at) >= TOOL_RUN_STATUS_ANNOUNCE_INTERVAL_MS),
        None => true,
    };
    if announce {
        entry.announced = Some((state, now_ms, status.clone()));
    }
    let live = if !announce {
        Liveness::Off
    } else if state == ToolRunState::Faulted || entry.conflicts > 0 {
        Liveness::Assertive
    } else {
        Liveness::Polite
    };
    let status_node = text(Label(UiText::clipped(&status))).live(live).try_id(format!("{scope}.status")).map_err(|_| error("tool-run-panel.status-id"))?.try_build().map_err(|_| error("tool-run-panel.status"))?;
    let unit = entry.definition.unit.resolve(Terminology::Native, locale).to_string();
    let value_text = match entry.total {
        Some(total) => {
            let percent = if total == 0 { 100 } else { entry.completed.saturating_mul(100) / total };
            tool_run_format(ToolRunLabel::ProgressValueText.text(locale), |name| match name {
                "stage" => Some(stage_label.clone()),
                "i" => Some((usize::from(entry.stage) + 1).to_string()),
                "n" => Some(stage_count.to_string()),
                "completed" => Some(entry.completed.to_string()),
                "total" => Some(total.to_string()),
                "unit" => Some(unit.clone()),
                "pct" => Some(percent.to_string()),
                _ => None,
            })
        }
        None => format!("{stage_label} ({}/{stage_count}): {} {unit}", usize::from(entry.stage) + 1, entry.completed),
    };
    let mut bar = progress(entry.completed as f64, Label(UiText::clipped(&value_text)));
    if let Some(total) = entry.total {
        bar = bar.total(total as f64);
    }
    let bar = bar.try_id(format!("{scope}.progress")).map_err(|_| error("tool-run-panel.progress-id"))?.try_build().map_err(|_| error("tool-run-panel.progress"))?;
    let (run, generation) = (entry.slot.run, entry.slot.generation);
    let mut buttons = BuiltChildren::default();
    let toggle = if state == ToolRunState::Paused { ToolRunAction::Resume } else { ToolRunAction::Pause };
    let actions = if state.is_terminal() { vec![ToolRunAction::Start, ToolRunAction::Dismiss] } else { vec![toggle, ToolRunAction::Step, ToolRunAction::Abort, ToolRunAction::Finalize] };
    for action in actions {
        let mut arguments = UiMapBuilder::try_new().ok_or_else(|| error("tool-run-panel.args"))?;
        let pushed = match action {
            ToolRunAction::Start => arguments.push(TOOL_RUN_ARG_TOOL_ID.to_string(), UiValue::Text(UiText::clipped(&entry.tool_id))).is_ok(),
            _ => arguments.push(TOOL_RUN_ARG_RUN_ID.to_string(), UiValue::Text(UiText::clipped(&run.to_string()))).is_ok() && arguments.push(TOOL_RUN_ARG_GENERATION.to_string(), UiValue::Number(f64::from(generation))).is_ok(),
        };
        if !pushed {
            return Err(error("tool-run-panel.args"));
        }
        let action_id = ActionId::try_v1(controller_id, action.id()).ok_or_else(|| error("tool-run-panel.action-id"))?;
        let legal = action.is_legal_in(Some(state));
        let mut builder = button(Label(UiText::clipped(action.label().text(locale)))).disabled(!legal);
        builder = builder.try_id(format!("{scope}.{}", action.id())).map_err(|_| error("tool-run-panel.button-id"))?;
        builder = builder.try_shortcut(action.chord()).map_err(|_| error("tool-run-panel.button-shortcut"))?;
        if action == ToolRunAction::Finalize && !legal {
            builder = builder.try_describe(ToolRunLabel::FinalizeDisabled.text(locale)).map_err(|_| error("tool-run-panel.finalize-description"))?;
        }
        let node = builder.try_on_with(Trigger::Activate, action_id, UiValue::Map(arguments.finish())).map_err(|_| error("tool-run-panel.button-binding"))?.try_build().map_err(|_| error("tool-run-panel.button"))?;
        buttons.try_push(node).map_err(|_| error("tool-run-panel.buttons"))?;
    }
    let toolbar = row().try_id(format!("{scope}.actions")).map_err(|_| error("tool-run-panel.actions-id"))?.try_children(buttons).map_err(|_| error("tool-run-panel.actions"))?.try_build().map_err(|_| error("tool-run-panel.actions-build"))?;
    let mut step_rows = BuiltChildren::default();
    let newest_steps: Vec<&ToolRunStep> = entry.steps.iter().collect();
    for step in newest_steps.into_iter().rev().take(TOOL_RUN_PANEL_STEP_ROWS) {
        let row = text(Label(UiText::clipped(&tool_run_step_text(&entry.definition, step, locale))))
            .tone(tool_run_step_tone(step.kind))
            .try_id(format!("{scope}.step.{}", step.sequence))
            .map_err(|_| error("tool-run-panel.step-id"))?
            .try_build()
            .map_err(|_| error("tool-run-panel.step"))?;
        step_rows.try_push(row).map_err(|_| error("tool-run-panel.steps"))?;
    }
    let steps = column()
        .live(Liveness::Off)
        .try_label(if locale == Locale::De { "Schritte" } else { "Steps" })
        .map_err(|_| error("tool-run-panel.steps-label"))?
        .try_id(format!("{scope}.steps"))
        .map_err(|_| error("tool-run-panel.steps-id"))?
        .try_children(step_rows)
        .map_err(|_| error("tool-run-panel.steps-children"))?
        .try_build()
        .map_err(|_| error("tool-run-panel.steps-build"))?;
    let mut trace_rows = BuiltChildren::default();
    for key in entry.recent_trace.iter().rev() {
        let Some(record) = entry.trace.record(*key) else { continue };
        let reason = ToolRunStep { sequence: 0, kind: ToolRunStepKind::Info, stage: entry.stage, reason: record.reason, subject: Some(*key), repeat: 1, args: Vec::new() };
        let item = ui::tree_item(Label(UiText::clipped(&tool_run_step_text(&entry.definition, &reason, locale))))
            .tone(tool_run_verdict_tone(record.verdict))
            .try_id(format!("{scope}.trace.{key}"))
            .map_err(|_| error("tool-run-panel.trace-id"))?
            .try_build()
            .map_err(|_| error("tool-run-panel.trace-item"))?;
        trace_rows.try_push(item).map_err(|_| error("tool-run-panel.trace-rows"))?;
    }
    let trace = tree()
        .try_label(if locale == Locale::De { "Versuche" } else { "Attempts" })
        .map_err(|_| error("tool-run-panel.trace-label"))?
        .try_id(format!("{scope}.trace"))
        .map_err(|_| error("tool-run-panel.trace-id"))?
        .try_children(trace_rows)
        .map_err(|_| error("tool-run-panel.trace"))?
        .try_build()
        .map_err(|_| error("tool-run-panel.trace-build"))?;
    let mut children = BuiltChildren::default();
    for child in [status_node, bar, toolbar, steps, trace] {
        children.try_push(child).map_err(|_| error("tool-run-panel.children"))?;
    }
    column()
        .try_label(label)
        .map_err(|_| error("tool-run-panel.label"))?
        .try_id(scope)
        .map_err(|_| error("tool-run-panel.id"))?
        .try_children(children)
        .map_err(|_| error("tool-run-panel.children"))?
        .try_build()
        .map_err(|_| error("tool-run-panel.build"))
}
//#endregion 🔖️Panel

pairs.after:
//! ⏯️ OS runtime of an interactive, transactional tool run with a visible process: the per-instance
//! [`ToolRunLedger`] (provisional document ops folded into an overlay the renderer reads as the document), the
//! [`ToolRunDriver`] turn stepping run and revalidate jobs, the one-edit finalize publication and the
//! framework ToolRun panel body.
//!
//! Contract: `.🧬semio/🦑️repo/🎫️tickets/🎆️26/🌙️09/☀️13/INTERACTIVE-TOOLS-VISIBLE-PROCESS/📋️tool-run-contract.md`
//! §2.7, §2.8, §3.3, §4.1 (layers 1 and 3). Domain-neutral types: `semio_framework_tool_run`.

use super::*;
use semio_framework_tool_run::{
    tool_run_format, tool_run_pointer_value, ToolRunAction, ToolRunCounter, ToolRunDefinition, ToolRunEffect, ToolRunEvent, ToolRunId, ToolRunIdentity, ToolRunLabel, ToolRunLane, ToolRunMachine, ToolRunRebasePolicy, ToolRunReconfigurePolicy,
    ToolRunRejection, ToolRunSettingsReads, ToolRunSlot, ToolRunState, ToolRunStep, ToolRunStepArg, ToolRunStepKind, ToolRunStepRing, ToolRunTick, ToolRunTraceCursor, ToolRunTraceDelta, ToolRunTraceOp, ToolRunTraceStore, ToolRunVerdict,
    TOOL_RUN_ACTION_IDS, TOOL_RUN_ARG_GENERATION, TOOL_RUN_ARG_RUN_ID, TOOL_RUN_ARG_TOOL_ID, TOOL_RUN_ARG_WINDOW_ID, TOOL_RUN_MEMBER_OPS_MAX, TOOL_RUN_PROVISIONAL_OPS_MAX, TOOL_RUN_REASON_CONFLICT, TOOL_RUN_REASON_PROVISIONAL_CAP, TOOL_RUN_REASON_REBASING,
    TOOL_RUN_REASON_TRACE_TRUNCATED, TOOL_RUN_STATUS_ANNOUNCE_INTERVAL_MS, TOOL_RUN_TICK_BYTES_MAX,
};
use semio_framework_ui_scene::{scene_lane_hash, Board2dScene, Board2dSceneLane, Canvas2dScene, Canvas2dSceneLane, SceneDoc, SceneLaneRef, World3dScene, World3dSceneLane};
use std::collections::BTreeMap;
use std::sync::Arc;

//#region 🔖️Limits
/// 🪧️ Framework-owned panel body served before any app body, next to `FRAMEWORK_HISTORY_BODY_KEY`.
pub const FRAMEWORK_TOOL_RUN_BODY_KEY: &str = "framework.body.toolRun";
/// ⏱️ Wall budget of one driver turn; every job step inside it keeps its own interactive-lane slice.
pub const TOOL_RUN_TURN_WALL_US: u64 = 4_000;
/// 🧮️ Folded ops between two wall-clock checks of a bounded refold.
pub const TOOL_RUN_REFOLD_CHECK_OPS: usize = 64;
/// 🧹️ Discarded provisional ops cold-retired per driver or close turn.
pub const TOOL_RUN_DISCARD_OPS_PER_TURN: usize = 4_096;
/// 📜️ Newest step-log rows the panel shows.
pub const TOOL_RUN_PANEL_STEP_ROWS: usize = 16;
/// 🧾️ Newest trace records the panel's keyboard trace list shows.
pub const TOOL_RUN_PANEL_TRACE_ROWS: usize = 32;
/// 📦️ Encoded trace delta bytes one renderer refresh receives.
pub const TOOL_RUN_TRACE_DELTA_BYTES: usize = 262_144;
/// 🔁️ Refreshes one window may re-request a trace backlog while its renderer's echoed cursor stands still;
/// a renderer that never echoes therefore costs a bounded number of refreshes, never a refresh loop.
pub const TOOL_RUN_TRACE_STALL_REFRESHES: u8 = 4;
const TOOL_RUN_JOB_SITE: &str = "tool-run.step";
const TOOL_RUN_PUBLICATION_GRANT: store::ArtifactStoreOneItemGrant = store::ArtifactStoreOneItemGrant { maximum_items: 1, maximum_bytes: TYPED_OPERATION_RESULT_PAGE_BYTES };
//#endregion 🔖️Limits

//#region 🔖️Selection
/// 🎯️ The run the ledger currently operates on (`ToolRunLedger::selected`), borrowing only `entries`.
macro_rules! selected_entry {
    ($ledger:expr) => {
        $ledger.selected.and_then(|index| $ledger.entries.get(index)).map(|entry| &**entry)
    };
}

/// 🎯️ The run the ledger currently operates on, mutably, borrowing only `entries`.
macro_rules! selected_entry_mut {
    ($ledger:expr) => {
        match $ledger.selected {
            Some(index) => $ledger.entries.get_mut(index).map(|entry| &mut **entry),
            None => None,
        }
    };
}
//#endregion 🔖️Selection

//#region 🔖️Request
/// 🎯️ Which job of a run the app builds.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ToolRunJobPurpose {
    Run,
    Revalidate,
}

/// 🧵️ A boxed run or revalidate job; it reports `ToolRunTick` pages via `StepOutcome::PreviewReady`. `Send`
/// explicitly: the browser target's `InteractiveJob` drops its thread-transfer bound, but the ledger lives
/// in a `PluginApp`, which stays `Send` on every target.
pub type ToolRunJob = Box<dyn semio_framework_job::InteractiveJob + Send>;

/// 🧳️ Everything an app needs to build one run or revalidate job (§3.7).
///
/// - `snapshot` is the run's base for `Run` and the committed head for `Revalidate`.
/// - `window_id` is the window instance the run was started from (`toolRunStart`'s `windowId`, else the
///   dispatching view's window), and `window_config` that window's config snapshot as of this build.
/// - `checkpoint` is the last `StepOutcome::CheckpointReady` state of this run (reconfigure `resume`).
/// - `provisional` is the provisional op list the job continues from or revalidates.
/// - `instance_owner` is the instance's retained operation owner, shared with its commands.
/// - `port` carries the host effects the job asks for and the wake of a job waiting on them.
/// - `trace_keys` allocates trace keys no record of this run uses, e.g. one per placement a revalidate job
///   re-tests; every job of the run shares it, so keys never collide across rebuilds and purposes.
/// - `entity_marks` holds `(provisional length at the end of the tick that appended it, entity)` per entity, in
///   append order: which provisional op prefix each placement's entity belongs to.
/// - `children` is the composed read the job runs on: the live owned children, whose member a member run
///   (`ToolRunDefinition::member`) edits.
/// - `member_ops` is a member run's provisional op list (that member's `OpBinary` ops), the one the job continues
///   from or revalidates; empty for a run on the document's own store.
pub struct ToolRunJobRequest<'a, A: ArtifactApp> {
    pub tool_id: &'a str,
    pub definition: &'a ToolRunDefinition,
    pub purpose: ToolRunJobPurpose,
    pub identity: ToolRunIdentity,
    pub snapshot: Arc<A::Snapshot>,
    pub config: Arc<A::Config>,
    pub window_id: Option<&'a str>,
    pub window_config: Option<WindowConfigSnapshot>,
    pub checkpoint: Option<&'a [u8]>,
    pub provisional: &'a [A::Mutation],
    pub instance_owner: ArtifactInstanceOperationOwnerHandle,
    pub port: ToolRunJobPort,
    pub trace_keys: ToolRunTraceKeys,
    pub entity_marks: &'a [(u32, u64)],
    pub children: ChildContentView,
    pub member_ops: &'a [Vec<u8>],
}

/// 🔑️ The trace key allocator every job of one run shares: keys handed out lie above every key the run's
/// ticks have upserted and every key allocated before.
#[derive(Clone, Debug, Default)]
pub struct ToolRunTraceKeys {
    next: Arc<std::sync::atomic::AtomicU64>,
}

impl ToolRunTraceKeys {
    /// 🔢️ The first key neither upserted by this run nor allocated.
    pub fn next(&self) -> u64 {
        self.next.load(std::sync::atomic::Ordering::SeqCst)
    }

    /// 🎟️ Reserves `count` consecutive unused keys.
    pub fn allocate(&self, count: u64) -> std::ops::Range<u64> {
        let start = self.next.try_update(std::sync::atomic::Ordering::SeqCst, std::sync::atomic::Ordering::SeqCst, |next| Some(next.saturating_add(count))).unwrap_or_else(|next| next);
        start..start.saturating_add(count)
    }

    fn observe(&self, key: u64) {
        self.next.fetch_max(key.saturating_add(1), std::sync::atomic::Ordering::SeqCst);
    }
}

/// 🎯️ The in-place retarget hooks of the tool run job protocol (§3.3). A job built through
/// `ArtifactApp::build_retargetable_tool_run_job` stays resident across a base change and a settings change —
/// and while its run is `complete` — instead of being closed and rebuilt from its checkpoint.
pub trait ToolRunRetargetableJob<C>: semio_framework_job::InteractiveJob + Send {
    /// 🪢️ Every tick after this call carries `identity` (base changed: new generation and base revision).
    fn rebind(&mut self, identity: ToolRunIdentity);
    /// 🎚️ Retargets the job to `config` under `identity`; `false` when it cannot continue in place, and the
    /// driver then closes it and rebuilds it from its checkpoint.
    fn reconfigure(&mut self, identity: ToolRunIdentity, config: Arc<C>) -> bool;
}

/// 📮️ What a run job shares with its app instance across turns: the host effects it hands the driver (an
/// extension round trip whose answer returns as an app command cannot happen inside `step`) and the external
/// wake of a job waiting on such work. A waiting job is never stepped and keeps its instance idle, so waiting
/// costs no turn; whoever folds the awaited answer calls [`ToolRunJobPort::wake`].
#[derive(Clone, Default)]
pub struct ToolRunJobPort {
    inner: Arc<ToolRunJobPortState>,
}

#[derive(Default)]
struct ToolRunJobPortState {
    effects: std::sync::Mutex<std::collections::VecDeque<Effect>>,
    waiting: std::sync::atomic::AtomicBool,
}

impl ToolRunJobPort {
    /// 📨️ Queues one effect the driver hands the host on its next turn, in order.
    pub fn dispatch(&self, effect: Effect) {
        if let Ok(mut effects) = self.inner.effects.lock() {
            effects.push_back(effect);
        }
    }

    /// ⏸️ The job's next step makes no progress until [`ToolRunJobPort::wake`]; set it while holding whatever
    /// lock the waker folds its answer under, so no wake can slip between the decision and the flag.
    pub fn wait(&self) {
        self.inner.waiting.store(true, std::sync::atomic::Ordering::SeqCst);
    }

    /// ⏰️ Makes a waiting job runnable again.
    pub fn wake(&self) {
        self.inner.waiting.store(false, std::sync::atomic::Ordering::SeqCst);
    }

    pub fn is_waiting(&self) -> bool {
        self.inner.waiting.load(std::sync::atomic::Ordering::SeqCst)
    }

    pub fn has_effects(&self) -> bool {
        self.inner.effects.lock().is_ok_and(|effects| !effects.is_empty())
    }

    fn pop_effect(&self) -> Option<Effect> {
        self.inner.effects.lock().ok()?.pop_front()
    }

    fn restore_effect(&self, effect: Effect) {
        if let Ok(mut effects) = self.inner.effects.lock() {
            effects.push_front(effect);
        }
    }
}

/// 🪟️ What a renderer learns about the run on this document instance (§4.1 layer 1): its identity and state, the
/// provisional entities, the §2.3 progress (stage, counters, step ring) and the latest plugin payload a tick carried.
#[derive(Clone, Debug, PartialEq)]
pub struct ToolRunView {
    pub tool_id: String,
    pub identity: ToolRunIdentity,
    pub state: ToolRunState,
    pub provisional_entities: Arc<BTreeSet<u64>>,
    pub progress: semio_framework_tool_run::ToolRunProgress,
    pub payload: Option<Arc<[u8]>>,
}

impl ToolRunView {
    /// 🏗️ A view of a run with no provisional entities, no progress yet and no payload.
    pub fn new(tool_id: impl Into<String>, identity: ToolRunIdentity, state: ToolRunState) -> Self {
        let progress = semio_framework_tool_run::ToolRunProgress { identity, sequence: 0, state, stage: 0, completed: 0, total: None, counters: Vec::new(), units_per_second: 0.0, conflicts: 0, steps: ToolRunStepRing::new() };
        Self { tool_id: tool_id.into(), identity, state, provisional_entities: Arc::new(BTreeSet::new()), progress, payload: None }
    }
}

/// 🔖️ True for the seven framework-reserved tool run action ids (§2.5).
pub fn is_tool_run_action_id(action: &str) -> bool {
    TOOL_RUN_ACTION_IDS.contains(&action)
}
//#endregion 🔖️Request

//#region 🔖️Job
enum ToolRunJobHandle<C> {
    Plain(ToolRunJob),
    Retargetable(Box<dyn ToolRunRetargetableJob<C>>),
}

struct ToolRunJobSlot<C> {
    job: ToolRunJobHandle<C>,
    purpose: ToolRunJobPurpose,
    operation: semio_framework_job::OperationId,
    generation: semio_framework_job::Generation,
    cancel: semio_framework_job::CancelToken,
    preview_sequence: u64,
    closing: bool,
}

impl<C> ToolRunJobSlot<C> {
    fn new(job: ToolRunJobHandle<C>, purpose: ToolRunJobPurpose, generation: u32) -> Self {
        Self { job, purpose, operation: semio_framework_job::allocate_operation_id(), generation: semio_framework_job::Generation(u64::from(generation)), cancel: semio_framework_job::CancelToken::root_now(), preview_sequence: 0, closing: false }
    }

    fn interactive(&mut self) -> &mut dyn semio_framework_job::InteractiveJob {
        match &mut self.job {
            ToolRunJobHandle::Plain(job) => job.as_mut(),
            ToolRunJobHandle::Retargetable(job) => job.as_mut(),
        }
    }

    fn terminal_is_empty(&self) -> bool {
        match &self.job {
            ToolRunJobHandle::Plain(job) => job.terminal_is_empty(),
            ToolRunJobHandle::Retargetable(job) => job.terminal_is_empty(),
        }
    }

    fn retargetable(&mut self) -> Option<&mut dyn ToolRunRetargetableJob<C>> {
        match &mut self.job {
            ToolRunJobHandle::Retargetable(job) if !self.closing => Some(job.as_mut()),
            _ => None,
        }
    }

    fn begin_close(&mut self) {
        if !self.closing {
            self.cancel.cancel_now();
            self.interactive().begin_close();
            self.closing = true;
        }
    }

    fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<Option<PluginCloseStep>, Fault> {
        self.begin_close();
        match self.interactive().close_step(maximum_items.max(1), maximum_bytes) {
            semio_framework_job::InteractiveJobCloseStep::Pending { released_items, released_bytes } => Ok(Some(PluginCloseStep::Pending { released_items, released_bytes })),
            semio_framework_job::InteractiveJobCloseStep::Blocked => Ok(Some(PluginCloseStep::Blocked { reason: "tool run job close is blocked" })),
            semio_framework_job::InteractiveJobCloseStep::Complete if self.terminal_is_empty() => Ok(None),
            semio_framework_job::InteractiveJobCloseStep::Complete => Err(Fault::new(FaultOrigin::Framework, FaultCode::new("toolRun.job-close"), "tool run job reported Complete without its terminal-empty witness")),
        }
    }
}

fn close_job_payload(payload: &mut semio_framework_job::RetainedJobPayload) {
    while let semio_framework_job::JobPayloadCloseStep::Pending { released_items: 1, .. } = payload.close_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES) {}
}

fn job_payload_bytes(payload: &semio_framework_job::RetainedJobPayload, limit: usize) -> Option<Vec<u8>> {
    if payload.len() > limit {
        return None;
    }
    let mut bytes = Vec::with_capacity(payload.len());
    for index in 0..payload.page_count() {
        bytes.extend_from_slice(payload.page(index)?);
    }
    Some(bytes)
}

/// 📼️ Lane text of one delta: `None` for an empty, non-clearing delta, else its base64url (unpadded) pack body.
fn tool_run_trace_lane_text(delta: &ToolRunTraceDelta) -> Option<String> {
    if !delta.clear && delta.pages.is_empty() {
        return None;
    }
    delta.encode().ok().map(base64_codec::base64_url_encode)
}

/// 🔎️ The first World3d, Canvas2d or Board2d scene surface of a rendered body, depth first.
fn tool_run_scene_surface(node: &mut BuiltNode) -> Option<&mut BuiltNode> {
    let is_scene = matches!(&node.component, Component::Surface(props) if [World3dScene::SCHEMA, Canvas2dScene::SCHEMA, Board2dScene::SCHEMA].contains(&props.doc_schema.as_str()));
    if is_scene {
        return Some(node);
    }
    node.children.iter_mut().find_map(tool_run_scene_surface)
}

/// 📎️ Re-attaches `lane` to a scene surface: the spine's lane refs gain the `toolRunTrace` entry and the
/// surface gains its paged carrier, exactly as `SceneDoc::split_lanes` plus `scene_surface` would emit it.
/// A surface whose producer already carries the lane is left untouched.
fn inject_tool_run_trace_lane_into(surface: &mut BuiltNode, lane: &str) -> UiAssemblyResult<()> {
    let Component::Surface(props) = &mut surface.component else { return Ok(()) };
    let (name, key) = match props.doc_schema.as_str() {
        World3dScene::SCHEMA => (World3dSceneLane::ToolRunTrace.name(), World3dSceneLane::ToolRunTrace.body_key()),
        Board2dScene::SCHEMA => (Board2dSceneLane::ToolRunTrace.name(), Board2dSceneLane::ToolRunTrace.body_key()),
        _ => (Canvas2dSceneLane::ToolRunTrace.name(), Canvas2dSceneLane::ToolRunTrace.body_key()),
    };
    if surface.children.iter().any(|child| child.key.as_str() == key) {
        return Ok(());
    }
    let reference = SceneLaneRef { lane: name.to_string(), bytes: lane.len() as u32, hash: scene_lane_hash(lane) };
    let encoded = match props.doc_schema.as_str() {
        World3dScene::SCHEMA => {
            let mut spine: World3dScene = semio_framework_ui_scene::decode(props).map_err(|error| ui_assembly_error_because("tool-run-trace.decode", error))?;
            spine.lanes.push(reference);
            semio_framework_ui_scene::encode(props.kind, &spine)
        }
        Board2dScene::SCHEMA => {
            let mut spine: Board2dScene = semio_framework_ui_scene::decode(props).map_err(|error| ui_assembly_error_because("tool-run-trace.decode", error))?;
            spine.lanes.push(reference);
            semio_framework_ui_scene::encode(props.kind, &spine)
        }
        _ => {
            let mut spine: Canvas2dScene = semio_framework_ui_scene::decode(props).map_err(|error| ui_assembly_error_because("tool-run-trace.decode", error))?;
            spine.lanes.push(reference);
            semio_framework_ui_scene::encode(props.kind, &spine)
        }
    };
    let mut encoded = encoded.map_err(|error| ui_assembly_error_because("tool-run-trace.encode", error))?;
    let carrier = paged_text_carrier(key, lane)?;
    if surface.children.len() == UI_BUILT_CHILDREN_MAX {
        return Err(ui_assembly_error("tool-run-trace.carrier"));
    }
    encoded.bindings = std::mem::take(&mut props.bindings);
    *props = encoded;
    surface.children.try_push(carrier).map_err(|_| ui_assembly_error("tool-run-trace.carrier"))
}

fn close_step_outcome(outcome: &mut semio_framework_job::StepOutcome) {
    while let semio_framework_job::JobPayloadCloseStep::Pending { released_items: 1, .. } = outcome.close_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES) {}
}
//#endregion 🔖️Job

//#region 🔖️Ledger
/// 🔁️ A bounded refold of the provisional ops from `base`. `boundary` is whether the job reached a point where
/// the refolded overlay is whole: a retract refold waits for the job's next checkpoint, completion or close,
/// so a retract followed by re-appends spread over several ticks never renders a half re-appended overlay —
/// the previous overlay stays rendered until then.
struct ToolRunRefold<P> {
    running: Option<P>,
    cursor: usize,
    boundary: bool,
}

/// 🚦️ Where one refold turn left the overlay.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ToolRunRefoldTurn {
    Pending,
    AwaitingBoundary,
    Swapped,
}

/// 🎚️ The values a run's declared settings reads named when last observed: config pointers, then per declared
/// window kind the `(window id, values)` of every partition it reads.
#[derive(Clone, Debug, Default, PartialEq)]
struct ToolRunSettingsValues {
    config: Vec<Option<DslValue>>,
    window_config: Vec<(String, String, Vec<Option<DslValue>>)>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ToolRunFinalizePhase {
    Pending,
    Revalidating,
    Publishing,
    Closing,
}

struct ToolRunFinalize<A: ArtifactApp> {
    phase: ToolRunFinalizePhase,
    publication: Option<store::ArtifactStoreBatchPublication<A::Snapshot, A::Mutation>>,
    retracted: u32,
    published: bool,
}

struct ToolRunEntry<A: ArtifactApp> {
    tool_id: String,
    actor: String,
    definition: ToolRunDefinition,
    slot: ToolRunSlot,
    identity: ToolRunIdentity,
    base: Arc<A::Snapshot>,
    base_generation: u64,
    settings_generation: (u64, u64),
    settings_values: ToolRunSettingsValues,
    window: Option<(String, String)>,
    window_bodies: Vec<String>,
    payload: Option<Arc<[u8]>>,
    trace_keys: ToolRunTraceKeys,
    provisional: Vec<A::Mutation>,
    entity_marks: Vec<(u32, u64)>,
    entities: Arc<BTreeSet<u64>>,
    overlay: Arc<A::Snapshot>,
    refold: Option<ToolRunRefold<A::Snapshot>>,
    trace: ToolRunTraceStore,
    recent_trace: std::collections::VecDeque<u64>,
    stage: u16,
    completed: u64,
    total: Option<u64>,
    counters: Vec<ToolRunCounter>,
    steps: ToolRunStepRing,
    step_sequence: u64,
    sequence: u64,
    conflicts: u32,
    rate_origin: Option<(u64, u64)>,
    units_per_second: f32,
    job: Option<ToolRunJobSlot<A::Config>>,
    checkpoint: Option<Vec<u8>>,
    pending_step: bool,
    finalize: Option<ToolRunFinalize<A>>,
    announced: Option<(ToolRunState, u64, String)>,
    port: ToolRunJobPort,
    /// ♻️ Snapshot aliases this run let go (a replaced base or overlay, a superseded fold result), owed to the store's
    /// alias retirement ([`ToolRunLedger::retire_step`]); never dropped plainly.
    displaced: Vec<Arc<A::Snapshot>>,
    /// 🧩️ The owned member a member run edits (`ToolRunDefinition::member`); `None` for a run on the document's store.
    member: Option<ToolRunMemberRun>,
}

impl<A: ArtifactApp> ToolRunEntry<A> {
    /// 🛣️ The lane this run occupies: the mutating lane, or its tool on its starting window when read-only.
    fn lane(&self) -> ToolRunLane {
        ToolRunLane { mutating: self.definition.mutating, tool_id: self.tool_id.clone(), window_id: if self.definition.mutating { None } else { self.window.as_ref().map(|(window_id, _)| window_id.clone()) } }
    }

    fn view(&self) -> ToolRunView {
        ToolRunView { tool_id: self.tool_id.clone(), identity: self.identity, state: self.slot.state, provisional_entities: Arc::clone(&self.entities), progress: self.progress(), payload: self.payload.clone() }
    }

    fn progress(&self) -> semio_framework_tool_run::ToolRunProgress {
        semio_framework_tool_run::ToolRunProgress {
            identity: self.identity,
            sequence: self.sequence,
            state: self.slot.state,
            stage: self.stage,
            completed: self.completed,
            total: self.total,
            counters: self.counters.clone(),
            units_per_second: self.units_per_second,
            conflicts: self.conflicts,
            steps: self.steps.clone(),
        }
    }

    /// 🏃️ Whether a driver turn has work for this run; a job waiting on its port is not work.
    fn has_pending_work(&self) -> bool {
        let stepping = self.job.is_none() || !self.port.is_waiting();
        self.port.has_effects()
            || self.refold_is_work()
            || !self.displaced.is_empty()
            || self.member.as_ref().is_some_and(ToolRunMemberRun::is_work)
            || match self.slot.state {
                ToolRunState::Running => stepping,
                ToolRunState::Starting | ToolRunState::Finalizing | ToolRunState::Aborting => true,
                ToolRunState::Paused => self.pending_step && stepping,
                ToolRunState::Complete => false,
                _ => self.job.is_some(),
            }
    }

    fn framework_step(&mut self, kind: ToolRunStepKind, reason: u16, args: &[ToolRunStepArg]) {
        self.step_sequence = self.step_sequence.saturating_add(1);
        self.steps.push(ToolRunStep { sequence: self.step_sequence, kind, stage: self.stage, reason, subject: None, repeat: 1, args: args.to_vec() });
    }

    fn begin_refold(&mut self, boundary: bool) {
        if let Some(running) = self.refold.replace(ToolRunRefold { running: None, cursor: 0, boundary }).and_then(|refold| refold.running) {
            self.displaced.push(Arc::new(running));
        }
    }

    /// ♻️ Replaces the overlay, owing the previous one to the store's alias retirement.
    fn replace_overlay(&mut self, overlay: Arc<A::Snapshot>) {
        let previous = std::mem::replace(&mut self.overlay, overlay);
        self.displaced.push(previous);
    }

    /// ♻️ Replaces the base, owing the previous one to the store's alias retirement.
    fn replace_base(&mut self, base: Arc<A::Snapshot>) {
        let previous = std::mem::replace(&mut self.base, base);
        self.displaced.push(previous);
    }

    /// 🏁️ The job reached a point where the refolded overlay is whole.
    fn settle_refold(&mut self) {
        if let Some(refold) = self.refold.as_mut() {
            refold.boundary = true;
        }
    }

    fn refold_is_work(&self) -> bool {
        self.refold.as_ref().is_some_and(|refold| refold.boundary || refold.cursor < self.provisional.len())
    }

    fn rebind(&mut self) {
        self.identity.generation = self.slot.generation;
        self.trace.rebind(self.identity);
    }

    fn rebuild_entities(&mut self) {
        let length = self.provisional.len() as u32;
        self.entity_marks.retain(|(end, _)| *end <= length);
        self.entities = Arc::new(self.entity_marks.iter().map(|(_, entity)| *entity).collect());
    }

    fn fold_one(snapshot: &A::Snapshot, op: &A::Mutation) -> Option<A::Snapshot> {
        let outcome = op.diff(snapshot);
        if !outcome.is_applicable(protocol::MergePolicy::default()) {
            return None;
        }
        outcome.diff().apply(snapshot).ok()
    }

    /// 🔁️ Folds provisional ops from `base` until the wall deadline; the overlay is replaced once every op is
    /// folded and the refold reached its boundary.
    fn refold_turn(&mut self, deadline_us: u64) -> ToolRunRefoldTurn {
        let Some(mut refold) = self.refold.take() else { return ToolRunRefoldTurn::Swapped };
        while refold.cursor < self.provisional.len() {
            let source = refold.running.as_ref().unwrap_or(&self.base);
            match Self::fold_one(source, &self.provisional[refold.cursor]) {
                Some(next) => {
                    if let Some(previous) = refold.running.replace(next) {
                        self.displaced.push(Arc::new(previous));
                    }
                }
                None => self.conflicts = self.conflicts.saturating_add(1),
            }
            refold.cursor += 1;
            if refold.cursor % TOOL_RUN_REFOLD_CHECK_OPS == 0 && semio_framework_job::default_now_us().is_none_or(|now| now >= deadline_us) {
                self.refold = Some(refold);
                return ToolRunRefoldTurn::Pending;
            }
        }
        if !refold.boundary {
            self.refold = Some(refold);
            return ToolRunRefoldTurn::AwaitingBoundary;
        }
        let overlay = refold.running.map_or_else(|| Arc::clone(&self.base), Arc::new);
        self.replace_overlay(overlay);
        ToolRunRefoldTurn::Swapped
    }

    /// 🧬️ Applies one tick of the current identity: retract, append (O(k) fold), entities, steps, progress, trace.
    fn apply_tick(&mut self, mut tick: ToolRunTick, discarded: &mut Vec<A::Mutation>) -> Result<ToolRunTickReceipt, Fault> {
        let mut receipt = ToolRunTickReceipt::default();
        if tick.identity.id != self.identity.id || tick.identity.generation != self.identity.generation {
            receipt.stale = true;
            return Ok(receipt);
        }
        if let Some(payload) = tick.payload.take() {
            self.payload = Some(payload.into());
        }
        self.sequence = self.sequence.max(tick.sequence);
        if let Some(member) = self.member.as_mut() {
            if let Some(retract) = tick.retract_to.map(|length| length as usize).filter(|length| *length < member.ops.len()) {
                receipt.retracted = (member.ops.len() - retract) as u32;
                member.ops.truncate(retract);
                member.rebase = true;
            }
            let room = (TOOL_RUN_MEMBER_OPS_MAX as usize).saturating_sub(member.ops.len());
            receipt.capped = tick.append_ops.len() > room;
            receipt.appended = tick.append_ops.len().min(room) as u32;
            member.ops.extend(tick.append_ops.drain(..).take(room));
            let length = member.ops.len() as u32;
            self.entity_marks.retain(|(end, _)| *end <= length);
            self.entities = Arc::new(self.entity_marks.iter().map(|(_, entity)| *entity).collect());
        } else if let Some(retract) = tick.retract_to.map(|length| length as usize).filter(|length| *length < self.provisional.len()) {
            receipt.retracted = (self.provisional.len() - retract) as u32;
            discarded.extend(self.provisional.drain(retract..));
            self.rebuild_entities();
            self.begin_refold(false);
        }
        let mut appended = Vec::with_capacity(tick.append_ops.len());
        for bytes in &tick.append_ops {
            if self.provisional.len() + appended.len() >= TOOL_RUN_PROVISIONAL_OPS_MAX as usize {
                receipt.capped = true;
                break;
            }
            appended.push(<A::Mutation as ::protocol::OpBinary>::decode_op(bytes).map_err(|error| error.into_fault())?);
        }
        if self.refold.is_none() && !appended.is_empty() {
            let mut running: Option<A::Snapshot> = None;
            for op in &appended {
                match Self::fold_one(running.as_ref().unwrap_or(&self.overlay), op) {
                    Some(next) => {
                        if let Some(previous) = running.replace(next) {
                            self.displaced.push(Arc::new(previous));
                        }
                    }
                    None => self.conflicts = self.conflicts.saturating_add(1),
                }
            }
            if let Some(running) = running {
                self.replace_overlay(Arc::new(running));
            }
        }
        receipt.appended += appended.len() as u32;
        self.provisional.extend(appended);
        let end = self.member.as_ref().map_or(self.provisional.len(), |member| member.ops.len()) as u32;
        if !tick.append_entities.is_empty() {
            let entities = Arc::make_mut(&mut self.entities);
            for entity in tick.append_entities {
                self.entity_marks.push((end, entity));
                entities.insert(entity);
            }
        }
        for mut step in tick.steps {
            self.step_sequence = self.step_sequence.saturating_add(1);
            step.sequence = self.step_sequence;
            self.steps.push(step);
        }
        if let Some(progress) = tick.progress {
            self.stage = progress.stage;
            self.total = progress.total;
            self.completed = progress.total.map_or(progress.completed, |total| progress.completed.min(total));
            self.counters = progress.counters;
        }
        for page in &tick.trace {
            let applied = self.trace.apply_page(page).map_err(|rejection| Fault::new(FaultOrigin::Framework, FaultCode::new(rejection.code()), "tool run trace page does not belong to the current run generation"))?;
            receipt.evicted = receipt.evicted.saturating_add(applied.evicted);
            receipt.capped |= applied.overflowed > 0;
            for op in &page.ops {
                match op {
                    ToolRunTraceOp::Upsert { key, .. } => {
                        self.trace_keys.observe(*key);
                        self.recent_trace.retain(|recent| recent != key);
                        if self.recent_trace.len() == TOOL_RUN_PANEL_TRACE_ROWS {
                            self.recent_trace.pop_front();
                        }
                        self.recent_trace.push_back(*key);
                    }
                    ToolRunTraceOp::Clear => self.recent_trace.clear(),
                    ToolRunTraceOp::Retire { key } => self.recent_trace.retain(|recent| recent != key),
                }
            }
        }
        if receipt.evicted > 0 {
            self.framework_step(ToolRunStepKind::Warning, TOOL_RUN_REASON_TRACE_TRUNCATED, &[ToolRunStepArg::Unsigned(u64::from(receipt.evicted))]);
        }
        if receipt.capped {
            let cap = if self.member.is_some() { TOOL_RUN_MEMBER_OPS_MAX } else { TOOL_RUN_PROVISIONAL_OPS_MAX };
            self.framework_step(ToolRunStepKind::Warning, TOOL_RUN_REASON_PROVISIONAL_CAP, &[ToolRunStepArg::Unsigned(u64::from(cap))]);
        }
        let now = semio_framework_job::default_now_us().unwrap_or(0);
        match self.rate_origin {
            None => self.rate_origin = Some((now, self.completed)),
            Some((origin_us, origin_completed)) if now > origin_us => self.units_per_second = self.completed.saturating_sub(origin_completed) as f32 * 1_000_000.0 / (now - origin_us) as f32,
            Some(_) => {}
        }
        Ok(receipt)
    }
}

/// 📬️ What one applied tick changed.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct ToolRunTickReceipt {
    pub stale: bool,
    pub appended: u32,
    pub retracted: u32,
    pub evicted: u32,
    pub capped: bool,
}

/// 🧭️ Driver watch state and turn budget (§3.3): settings publications the store generations cannot see.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ToolRunDriver {
    pub turn_wall_us: u64,
    window_config_publications: u64,
}

impl Default for ToolRunDriver {
    fn default() -> Self {
        Self { turn_wall_us: TOOL_RUN_TURN_WALL_US, window_config_publications: 0 }
    }
}

/// 🗄️ The tool runs of one document instance for its local actor (§2.2 invariant 5): at most one non-terminal
/// mutating run, and concurrent read-only runs, one per tool and window ([`ToolRunLane`]); plus the owners still
/// retiring.
///
/// 🎯️ The ledger operates on one *selected* run. Outside its own calls the selection is the primary run — the
/// non-terminal mutating run, else the most recent one — so the single-run accessors (`state`, `slot`, `view`, …)
/// answer for it; [`ToolRunLedger::select_run`] addresses another.
pub struct ToolRunLedger<A: ArtifactApp> {
    next_run: u64,
    entries: Vec<Box<ToolRunEntry<A>>>,
    selected: Option<usize>,
    driver: ToolRunDriver,
    retired_jobs: Vec<ToolRunJobSlot<A::Config>>,
    retired_publications: Vec<store::ArtifactStoreBatchPublication<A::Snapshot, A::Mutation>>,
    /// ♻️ Snapshot aliases owed to the store's alias retirement, and the one being retired now.
    retired_snapshots: Vec<Arc<A::Snapshot>>,
    snapshot_retirement: Option<Box<dyn store::ErasedSnapshotRetirement>>,
    discarded: Vec<A::Mutation>,
    /// 🧩️ Member runs that left their slot, whose typed owners and composed reads still retire against their member store.
    retired_members: Vec<ToolRunMemberRun>,
    closing: bool,
    trace_windows: BTreeMap<String, ToolRunTraceWindow>,
    ui_dirty: bool,
    document_dirty: bool,
}

/// 🪟️ One scene window the trace lane was delivered to: its body key and what its renderer last echoed.
struct ToolRunTraceWindow {
    body_key: String,
    echoed: Option<ToolRunTraceCursor>,
    answered: bool,
    stalls: u8,
}

impl<A: ArtifactApp> Default for ToolRunLedger<A> {
    fn default() -> Self {
        Self {
            next_run: 1,
            entries: Vec::new(),
            selected: None,
            driver: ToolRunDriver::default(),
            retired_jobs: Vec::new(),
            retired_publications: Vec::new(),
            retired_snapshots: Vec::new(),
            snapshot_retirement: None,
            discarded: Vec::new(),
            retired_members: Vec::new(),
            closing: false,
            trace_windows: BTreeMap::new(),
            ui_dirty: false,
            document_dirty: false,
        }
    }
}

impl<A: ArtifactApp> ToolRunLedger<A> {
    /// 👑️ The primary run: the non-terminal mutating run, else the most recent run.
    fn primary_index(&self) -> Option<usize> {
        self.entries.iter().position(|entry| entry.definition.mutating && !entry.slot.state.is_terminal()).or_else(|| self.entries.iter().enumerate().max_by_key(|(_, entry)| entry.slot.run).map(|(index, _)| index))
    }

    /// 👑️ Selects the primary run.
    pub fn select_primary(&mut self) {
        self.selected = self.primary_index();
    }

    /// 🎯️ Selects run `run`; `false` (and no selection) when this instance holds no such run.
    pub fn select_run(&mut self, run: u64) -> bool {
        self.selected = self.entries.iter().position(|entry| entry.slot.run == run);
        self.selected.is_some()
    }

    /// 🗂️ Every run this instance holds, oldest first.
    pub fn views(&self) -> Vec<ToolRunView> {
        self.entries.iter().map(|entry| entry.view()).collect()
    }

    /// 🪟️ The run a window renders: the most recent read-only run started from `window_id`, else the primary run.
    pub fn view_for(&self, window_id: Option<&str>) -> Option<ToolRunView> {
        self.window_index(window_id).or_else(|| self.primary_index()).map(|index| self.entries[index].view())
    }

    fn window_index(&self, window_id: Option<&str>) -> Option<usize> {
        let window_id = window_id?;
        self.entries.iter().enumerate().filter(|(_, entry)| !entry.definition.mutating && entry.window.as_ref().is_some_and(|(id, _)| id == window_id)).max_by_key(|(_, entry)| entry.slot.run).map(|(index, _)| index)
    }

    pub fn state(&self) -> Option<ToolRunState> {
        selected_entry!(self).map(|entry| entry.slot.state)
    }

    pub fn slot(&self) -> Option<ToolRunSlot> {
        selected_entry!(self).map(|entry| entry.slot)
    }

    pub fn identity(&self) -> Option<ToolRunIdentity> {
        selected_entry!(self).map(|entry| entry.identity)
    }

    pub fn tool_id(&self) -> Option<&str> {
        selected_entry!(self).map(|entry| entry.tool_id.as_str())
    }

    /// 📮️ The port every job of the selected run shares with its app instance.
    pub fn port(&self) -> Option<&ToolRunJobPort> {
        selected_entry!(self).map(|entry| &entry.port)
    }

    pub fn provisional(&self) -> &[A::Mutation] {
        selected_entry!(self).map_or(&[], |entry| entry.provisional.as_slice())
    }

    pub fn provisional_entities(&self) -> Option<&BTreeSet<u64>> {
        selected_entry!(self).map(|entry| entry.entities.as_ref())
    }

    pub fn steps(&self) -> Option<&ToolRunStepRing> {
        selected_entry!(self).map(|entry| &entry.steps)
    }

    pub fn trace(&self) -> Option<&ToolRunTraceStore> {
        selected_entry!(self).map(|entry| &entry.trace)
    }

    pub fn conflicts(&self) -> u32 {
        selected_entry!(self).map_or(0, |entry| entry.conflicts)
    }

    pub fn is_refolding(&self) -> bool {
        selected_entry!(self).is_some_and(|entry| entry.refold.is_some())
    }

    /// 📸️ The current run's last `StepOutcome::CheckpointReady` state, the one a rebuilt job continues from.
    pub fn checkpoint(&self) -> Option<&[u8]> {
        selected_entry!(self)?.checkpoint.as_deref()
    }

    /// 🔑️ The trace key allocator every job of the current run shares.
    pub fn trace_keys(&self) -> Option<&ToolRunTraceKeys> {
        selected_entry!(self).map(|entry| &entry.trace_keys)
    }

    /// 🏷️ `(provisional length at the end of the appending tick, entity)` per provisional entity, in append order.
    pub fn entity_marks(&self) -> &[(u32, u64)] {
        selected_entry!(self).map_or(&[], |entry| entry.entity_marks.as_slice())
    }

    /// 🪟️ `(window instance id, window kind id)` the current run was started from.
    pub fn window(&self) -> Option<(&str, &str)> {
        selected_entry!(self)?.window.as_ref().map(|(window_id, window_kind_id)| (window_id.as_str(), window_kind_id.as_str()))
    }

    /// 📊️ Progress snapshot derived from the ledger (§2.3); the step ring is the framework's own.
    pub fn progress(&self) -> Option<semio_framework_tool_run::ToolRunProgress> {
        selected_entry!(self).map(ToolRunEntry::progress)
    }

    /// 🪞️ The document a renderer reads: the mutating run's overlay while it holds provisional state, else `committed`.
    /// Read-only runs author no provisional edit, so their overlays never compose.
    pub fn overlay_or<'a>(&'a self, committed: &'a Arc<A::Snapshot>) -> &'a Arc<A::Snapshot> {
        match self.entries.iter().find(|entry| entry.definition.mutating && !entry.slot.state.is_terminal()) {
            Some(entry) if matches!(entry.slot.state, ToolRunState::Starting | ToolRunState::Running | ToolRunState::Paused | ToolRunState::Complete | ToolRunState::Finalizing) && !Arc::ptr_eq(&entry.overlay, &entry.base) => &entry.overlay,
            _ => committed,
        }
    }

    /// 🧩️ The composed children a renderer reads (§20.15): the mutating member run's composed read while it holds provisional
    /// state, else `live`. The parent document is untouched by a member run, so [`Self::overlay_or`] answers `committed`.
    pub fn children_or<'a>(&'a self, live: &'a ChildContentView) -> &'a ChildContentView {
        match self.entries.iter().find(|entry| entry.definition.mutating && !entry.slot.state.is_terminal()) {
            Some(entry) if matches!(entry.slot.state, ToolRunState::Starting | ToolRunState::Running | ToolRunState::Paused | ToolRunState::Complete | ToolRunState::Finalizing) => entry.member.as_ref().and_then(|member| member.children.as_ref()).unwrap_or(live),
            _ => live,
        }
    }

    /// 🧩️ The `(slot, child id)` of the member the selected run edits, `None` for a run on the document's own store.
    pub fn member(&self) -> Option<(&str, &str)> {
        selected_entry!(self)?.member.as_ref().map(|member| (member.slot.as_str(), member.child_id.as_str()))
    }

    /// 🧩️ The selected member run's provisional ops (that member's `OpBinary` ops); empty for a document run.
    pub fn member_ops(&self) -> &[Vec<u8>] {
        selected_entry!(self).and_then(|entry| entry.member.as_ref()).map_or(&[], |member| member.ops.as_slice())
    }

    pub fn view(&self) -> Option<ToolRunView> {
        selected_entry!(self).map(ToolRunEntry::view)
    }

    /// ⏪️ Whether a non-terminal mutating run holds provisional state on this instance: history editing cannot open then.
    pub fn holds_mutating_run(&self) -> bool {
        self.entries.iter().any(|entry| entry.definition.mutating && !entry.slot.state.is_terminal())
    }

    /// 🧊️ `freeze` rebase policy: local artifact emits fail with `toolRun.busy` while a freezing run is non-terminal.
    pub fn freezes_local_emits(&self) -> bool {
        self.entries.iter().any(|entry| entry.definition.rebase == ToolRunRebasePolicy::Freeze && !entry.slot.state.is_terminal())
    }

    /// 🏃️ Whether a driver turn has work: any run's stepping job, refold, close, finalize or port effects, or cold
    /// retirement. A job waiting on its port is not work.
    pub fn has_pending_work(&self) -> bool {
        !self.retired_jobs.is_empty()
            || !self.retired_publications.is_empty()
            || !self.retired_snapshots.is_empty()
            || self.snapshot_retirement.is_some()
            || !self.discarded.is_empty()
            || !self.retired_members.is_empty()
            || self.entries.iter().any(|entry| entry.has_pending_work())
    }

    /// 🧬️ Applies one decoded tick to the current run (the driver's per-tick O(k) overlay append);
    /// ticks of another run or generation are stale no-ops.
    pub fn apply_tick(&mut self, tick: ToolRunTick) -> Result<ToolRunTickReceipt, Fault> {
        let Some(entry) = selected_entry_mut!(self) else { return Ok(ToolRunTickReceipt { stale: true, ..ToolRunTickReceipt::default() }) };
        entry.apply_tick(tick, &mut self.discarded)
    }

    /// 🪟️ A window-config publication happened; the driver treats it as a settings change.
    pub fn note_window_config_published(&mut self) {
        self.driver.window_config_publications = self.driver.window_config_publications.wrapping_add(1);
    }

    /// 👥️ Ephemeral-shared presence summary (§3.4), `completed ≤ total` by construction.
    pub fn presence(&self) -> Option<protocol::PresenceToolRun> {
        let entry = &self.entries[self.primary_index()?];
        Some(protocol::PresenceToolRun {
            tool_id: entry.tool_id.clone(),
            state: protocol::PresenceToolRunState::from_wire_name(entry.slot.state.as_str())?,
            stage: entry.stage,
            completed: entry.total.map_or(entry.completed, |total| entry.completed.min(total)),
            total: entry.total,
        })
    }

    /// 📼️ Base64url (unpadded) `ToolRunTraceDelta` after `cursor`, for the scene lane `toolRunTrace` (§3.2).
    ///
    /// - A cursor of another run or generation, or none, gets `clear` plus the resend of the live log.
    /// - A caught-up cursor gets `None`, so an idle run costs nothing.
    /// - Without a run (dismissed or retired), a renderer still holding pages (`page > 0`) gets one empty
    ///   `clear` delta; `page == 0` already means an empty layer.
    pub fn trace_delta(&self, cursor: Option<ToolRunTraceCursor>, byte_budget: usize) -> Option<String> {
        let index = cursor.and_then(|cursor| self.entries.iter().position(|entry| entry.slot.run == cursor.run)).or_else(|| self.primary_index());
        let delta = match index.map(|index| &self.entries[index]) {
            Some(entry) => entry.trace.delta_after(cursor, byte_budget),
            None => {
                let cursor = cursor.filter(|cursor| cursor.page > 0)?;
                ToolRunTraceDelta { identity: ToolRunIdentity { id: ToolRunId { app_instance_id: 0, run: cursor.run }, generation: cursor.generation, base_revision: [0; 32] }, clear: true, next: 0, pages: Vec::new() }
            }
        };
        tool_run_trace_lane_text(&delta)
    }

    /// 🪟️ The lane text scene window `window_id` (body `body_key`) receives for its echoed `cursor`, and the
    /// bookkeeping that keeps a delivery backlog moving: pages left after the byte budget mark the ledger
    /// UI-dirty until the renderer's cursor stands still for `TOOL_RUN_TRACE_STALL_REFRESHES` refreshes.
    pub fn trace_lane(&mut self, window_id: &str, body_key: &str, cursor: Option<ToolRunTraceCursor>, byte_budget: usize) -> Option<String> {
        let Some(entry) = self.window_index(Some(window_id)).or_else(|| self.primary_index()).map(|index| &self.entries[index]) else {
            self.trace_windows.remove(window_id);
            return self.trace_delta(cursor, byte_budget);
        };
        let delta = entry.trace.delta_after(cursor, byte_budget);
        let backlog = delta.next < entry.trace.next_page();
        let window = self.trace_windows.entry(window_id.to_string()).or_insert_with(|| ToolRunTraceWindow { body_key: body_key.to_string(), echoed: None, answered: false, stalls: 0 });
        if window.body_key != body_key {
            window.body_key = body_key.to_string();
        }
        window.stalls = if window.answered && window.echoed == cursor { window.stalls.saturating_add(1) } else { 0 };
        window.echoed = cursor;
        window.answered = true;
        if backlog && window.stalls < TOOL_RUN_TRACE_STALL_REFRESHES {
            self.ui_dirty = true;
        }
        tool_run_trace_lane_text(&delta)
    }

    /// 🧹️ Forgets scene windows that closed or stopped hosting a scene surface.
    pub fn retain_trace_windows(&mut self, live: impl Fn(&str) -> bool) {
        self.trace_windows.retain(|window_id, _| live(window_id));
    }

    /// 🎯️ The minimal UI scope a run change dirties: the ToolRun panel body, the body of every scene window its trace
    /// lane rides in and the body of every window kind the run declares it renders in (`ToolRunDefinition::windows`) —
    /// never unrelated windows or panels.
    pub fn dirty_scope(&self) -> UiDirtyScope {
        let mut window_bodies: Vec<String> = self.trace_windows.values().map(|window| window.body_key.clone()).chain(self.entries.iter().flat_map(|entry| entry.window_bodies.iter().cloned())).collect();
        window_bodies.sort_unstable();
        window_bodies.dedup();
        UiDirtyScope::Partial { window_bodies, panel_bodies: vec![FRAMEWORK_TOOL_RUN_BODY_KEY.to_string()], utilities: false, tools: false, engagements: false, measures: false, labels: false }
    }

    /// 🚩️ Whether a run change still owes the host a dirty scope.
    pub fn is_ui_dirty(&self) -> bool {
        self.ui_dirty || self.document_dirty
    }

    fn apply_event(&mut self, event: ToolRunEvent) -> Result<ToolRunEffect, ToolRunRejection> {
        let transition = ToolRunMachine::apply(self.slot(), event)?;
        match (self.selected, transition.slot) {
            (Some(index), Some(slot)) => {
                let entry = &mut self.entries[index];
                let generation_changed = entry.slot.generation != slot.generation;
                entry.slot = slot;
                if generation_changed {
                    entry.rebind();
                }
            }
            (Some(index), None) => {
                let entry = self.entries.remove(index);
                self.retire_entry(*entry);
                self.select_primary();
            }
            (None, _) => {}
        }
        Ok(transition.effect)
    }

    fn retire_entry(&mut self, entry: ToolRunEntry<A>) {
        let ToolRunEntry { job, provisional, finalize, base, overlay, refold, mut displaced, member, .. } = entry;
        self.retired_members.extend(member);
        self.retired_snapshots.push(base);
        self.retired_snapshots.push(overlay);
        if let Some(running) = refold.and_then(|refold| refold.running) {
            self.retired_snapshots.push(Arc::new(running));
        }
        self.retired_snapshots.append(&mut displaced);
        self.retire_owners(job, provisional, finalize);
    }

    fn retire_owners(&mut self, job: Option<ToolRunJobSlot<A::Config>>, mut provisional: Vec<A::Mutation>, finalize: Option<ToolRunFinalize<A>>) {
        if let Some(mut job) = job {
            job.begin_close();
            self.retired_jobs.push(job);
        }
        self.discarded.append(&mut provisional);
        if let Some(publication) = finalize.and_then(|finalize| finalize.publication) {
            self.retired_publications.push(publication);
        }
    }

    fn close_current_job(&mut self) {
        let Some(entry) = selected_entry_mut!(self) else { return };
        entry.settle_refold();
        if let Some(mut job) = entry.job.take() {
            job.begin_close();
            self.retired_jobs.push(job);
        }
    }

    /// 🎯️ Hands the current job the entry's identity through `retarget`; a job that is not retargetable, or
    /// declines, is closed so the driver rebuilds it from its checkpoint.
    fn retarget_current_job(&mut self, retarget: impl FnOnce(&mut dyn ToolRunRetargetableJob<A::Config>, ToolRunIdentity) -> bool) {
        let Some(entry) = selected_entry_mut!(self) else { return };
        let identity = entry.identity;
        let Some(slot) = entry.job.as_mut() else { return };
        if slot.retargetable().is_some_and(|job| retarget(job, identity)) {
            slot.generation = semio_framework_job::Generation(u64::from(identity.generation));
        } else {
            self.close_current_job();
        }
    }

    /// 🧹️ Throws the run's provisional work away, payload included: an abort, a fault, a rebase-restart
    /// or a reconfigure-restart invalidates the run's whole intermediate result, so the windows that
    /// read `ToolRunView::payload` must stop showing it.
    fn discard_provisional(&mut self) {
        self.release_provisional(false);
    }

    /// 🧹️ Releases the provisional ops a COMPLETED finalize has already published, keeping the run's
    /// `payload`. The payload is not provisional work — it is the run's own result (§2.3: "the latest
    /// intermediate result of the run … the run's windows read it back through
    /// `ToolRunView::payload`"), and a `mutating: false` run publishes nothing else at all, so clearing
    /// it on finalize is what made a finished read-only run's windows revert to their pre-run render the
    /// instant it reached `Finalized`. It is cleared on a genuine discard and when the entry retires.
    fn release_provisional(&mut self, keep_payload: bool) {
        let Some(entry) = selected_entry_mut!(self) else { return };
        self.discarded.append(&mut entry.provisional);
        entry.entity_marks.clear();
        entry.entities = Arc::new(BTreeSet::new());
        if let Some(running) = entry.refold.take().and_then(|refold| refold.running) {
            entry.displaced.push(Arc::new(running));
        }
        let overlay = Arc::clone(&entry.base);
        entry.replace_overlay(overlay);
        entry.checkpoint = None;
        if let Some(member) = entry.member.as_mut() {
            member.release();
        }
        if !keep_payload {
            entry.payload = None;
        }
    }

    /// 🧹️ Advances the owners that outlived their slot by one bounded unit; `None` when nothing is retiring.
    fn retire_step(&mut self, store: &mut ArtifactStore<A::Snapshot, A::Mutation>, maximum_items: usize, maximum_bytes: usize) -> Result<Option<PluginCloseStep>, Fault> {
        if let Some(job) = self.retired_jobs.last_mut() {
            return match job.close_step(maximum_items, maximum_bytes)? {
                Some(step) => Ok(Some(step)),
                None => {
                    self.retired_jobs.pop();
                    Ok(Some(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }))
                }
            };
        }
        if let Some(publication) = self.retired_publications.pop() {
            let mut owner = Some(publication);
            return match store.handoff_batch_publication_close(&mut owner) {
                Ok(true) => Ok(Some(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })),
                Ok(false) => Err(plugin_sdk_fault("tool run publication handoff lost its exact retirement owner")),
                Err(error) => {
                    self.retired_publications.push(owner.expect("refused Store handoff preserves the tool run publication owner"));
                    Err(error.into_fault())
                }
            };
        }
        if let Some(retirement) = self.snapshot_retirement.as_mut() {
            return match retirement.close_step(maximum_items.max(1), maximum_bytes).map_err(|error| plugin_sdk_fault(error.into_message()))? {
                store::SnapshotRetirementStep::Complete if retirement.terminal_is_empty() => {
                    self.snapshot_retirement = None;
                    Ok(Some(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }))
                }
                store::SnapshotRetirementStep::Complete => Err(Fault::new(FaultOrigin::Framework, FaultCode::new("toolRun.snapshot-close"), "tool run snapshot retirement closed without its terminal-empty witness")),
                store::SnapshotRetirementStep::Pending { released_items, released_bytes } => Ok(Some(PluginCloseStep::Pending { released_items, released_bytes })),
                store::SnapshotRetirementStep::Blocked => Ok(Some(PluginCloseStep::Blocked { reason: "tool run snapshot retirement is blocked" })),
            };
        }
        for entry in &mut self.entries {
            self.retired_snapshots.append(&mut entry.displaced);
        }
        if let Some(alias) = self.retired_snapshots.pop() {
            self.snapshot_retirement = Some(store.retire_snapshot_alias(alias).map_err(|error| error.into_fault())?);
            return Ok(Some(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }));
        }
        if !self.discarded.is_empty() {
            let count = self.discarded.len().min(maximum_items.max(1)).min(TOOL_RUN_DISCARD_OPS_PER_TURN);
            for op in self.discarded.drain(self.discarded.len() - count..) {
                op.retire_cold();
            }
            return Ok(Some(PluginCloseStep::Pending { released_items: count, released_bytes: 0 }));
        }
        Ok(None)
    }

    /// 🚪️ Document close, instance retirement or reload: same as abort, ephemeral state vanishes (§2.2).
    pub fn begin_close(&mut self) {
        if self.closing {
            return;
        }
        self.closing = true;
        while !self.entries.is_empty() {
            self.selected = Some(self.entries.len() - 1);
            let _ = self.apply_event(ToolRunEvent::Closed);
        }
        self.selected = None;
    }

    /// 🧹️ One bounded close unit of every retiring owner.
    pub fn close_step(&mut self, store: &mut ArtifactStore<A::Snapshot, A::Mutation>, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
        self.begin_close();
        Ok(self.retire_step(store, maximum_items, maximum_bytes)?.unwrap_or(PluginCloseStep::Complete))
    }

    pub fn terminal_is_empty(&self) -> bool {
        self.entries.is_empty() && self.retired_jobs.is_empty() && self.retired_publications.is_empty() && self.retired_snapshots.is_empty() && self.snapshot_retirement.is_none() && self.discarded.is_empty() && self.retired_members.is_empty()
    }
}
//#endregion 🔖️Ledger

//#region 🔖️Member
/// 🧬️ The typed owners of a member run (`ToolRunDefinition::member`): the member snapshot the run rests on, the overlay its
/// provisional ops fold to, and every alias it let go — all owed to that member store's alias retirement, never dropped plainly.
trait ToolRunMemberOwners: Send {
    fn as_any_mut(&mut self) -> &mut dyn std::any::Any;
    fn has_displaced(&self) -> bool;
    fn is_empty(&self) -> bool;
}

struct ToolRunMemberState<P> {
    base: Option<store::ArtifactDerivedSnapshot<P>>,
    overlay: Option<store::ArtifactDerivedSnapshot<P>>,
    displaced: Vec<Arc<P>>,
}

impl<P: Send + Sync + 'static> ToolRunMemberOwners for ToolRunMemberState<P> {
    fn as_any_mut(&mut self) -> &mut dyn std::any::Any {
        self
    }

    fn has_displaced(&self) -> bool {
        !self.displaced.is_empty()
    }

    fn is_empty(&self) -> bool {
        self.base.is_none() && self.overlay.is_none() && self.displaced.is_empty()
    }
}

/// 🧩️ A run whose provisional ops are one owned member's ops (design §12, §20.15): where they land, the member generation
/// they rest on, how many the overlay already shows, the typed owners they fold through, and the composed read — the live
/// children with the overlay in the member's place — the render seams show while the run holds them.
struct ToolRunMemberRun {
    slot: String,
    child_id: String,
    dialect: ArtifactDialect,
    base_generation: u64,
    ops: Vec<Vec<u8>>,
    shown: usize,
    rebase: bool,
    owners: Option<Box<dyn ToolRunMemberOwners>>,
    children: Option<ChildContentView>,
    stale: Vec<ChildContentView>,
    emit: Option<ChildEmit>,
}

impl ToolRunMemberRun {
    /// 🏃️ Owed work: ops the overlay does not show yet, a refold from the member head, or reads and aliases to retire.
    fn is_work(&self) -> bool {
        self.rebase || self.shown != self.ops.len() || !self.stale.is_empty() || self.owners.as_deref().is_some_and(ToolRunMemberOwners::has_displaced)
    }

    /// 🧹️ Drops every provisional op: the composed read retires and the next refresh rests on the member head.
    fn release(&mut self) {
        self.ops.clear();
        self.shown = 0;
        self.rebase = true;
        self.emit = None;
        self.stale.extend(self.children.take());
    }
}

/// 📏️ Where one member fold left the overlay: the ops it shows, the ops that did not apply, and — once every op is shown —
/// the leased read of the overlay with the member's revision (`None`: no op, the render seams read the live member).
struct ToolRunMemberFolded {
    shown: usize,
    conflicts: u32,
    read: Option<(store::ErasedSnapshotRead, [u8; 32])>,
}

/// 🔁️ Folds a member run's ops onto its overlay within the turn wall budget: a rebase restarts from the member head.
struct ToolRunMemberFold<'a> {
    owners: &'a mut Option<Box<dyn ToolRunMemberOwners>>,
    ops: &'a [Vec<u8>],
    shown: usize,
    rebase: bool,
    deadline_us: u64,
}

impl store::MemberStoreVisitor for ToolRunMemberFold<'_> {
    type Output = Result<ToolRunMemberFolded, Fault>;

    fn visit<P, Mu>(self, store: &ArtifactStore<P, Mu>) -> Self::Output
    where
        P: Clone + semio_framework_value::ToValue + semio_framework_value::FromValue + ArtifactPack + semio_framework_schema_composition::ArtifactCompositionFields + Send + Sync + 'static,
        Mu: Clone + semio_framework_value::ToValue + semio_framework_value::FromValue + ::protocol::Mutation<P> + protocol::SemanticMutation<P> + ::protocol::OpBinary + ::protocol::OpText + Send + 'static,
    {
        let owners = self.owners.get_or_insert_with(|| Box::new(ToolRunMemberState::<P> { base: Some(store.derived_snapshot_head()), overlay: None, displaced: Vec::new() }));
        let state = owners.as_any_mut().downcast_mut::<ToolRunMemberState<P>>().ok_or_else(|| plugin_sdk_fault("a member tool run's owners belong to another store kind"))?;
        let mut shown = self.shown;
        if self.rebase {
            let previous = state.base.replace(store.derived_snapshot_head());
            state.displaced.extend(previous.map(store::ArtifactDerivedSnapshot::into_snapshot_owner));
            state.displaced.extend(state.overlay.take().map(store::ArtifactDerivedSnapshot::into_snapshot_owner));
            shown = 0;
        }
        let mut conflicts = 0u32;
        while shown < self.ops.len() {
            let op = <Mu as ::protocol::OpBinary>::decode_op(&self.ops[shown]).map_err(|error| error.into_fault())?;
            let source = state.overlay.as_ref().or(state.base.as_ref()).ok_or_else(|| plugin_sdk_fault("a member tool run lost its base"))?;
            let next = store.derive_provisional_snapshot(source, &op);
            <Mu as ::protocol::Mutation<P>>::retire_cold(op);
            match next.map_err(|error| error.into_fault())? {
                Some(next) => state.displaced.extend(state.overlay.replace(next).map(store::ArtifactDerivedSnapshot::into_snapshot_owner)),
                None => conflicts = conflicts.saturating_add(1),
            }
            shown += 1;
            if shown % TOOL_RUN_REFOLD_CHECK_OPS == 0 && shown < self.ops.len() && semio_framework_job::default_now_us().is_none_or(|now| now >= self.deadline_us) {
                return Ok(ToolRunMemberFolded { shown, conflicts, read: None });
            }
        }
        let read = match state.overlay.as_ref().filter(|_| !self.ops.is_empty()) {
            Some(overlay) => Some((store.snapshot_read_derived(overlay).map_err(|error| error.into_fault())?, store.content_revision())),
            None => None,
        };
        Ok(ToolRunMemberFolded { shown, conflicts, read })
    }
}

/// 🧾️ Decodes a member run's ops through the member's own vocabulary into the one composite child emission its finalize
/// publishes — the history row's mutations carry that member's leaf labels — resuming where the last turn stopped and
/// yielding at the turn wall deadline. `true` once every op is in the emission.
struct ToolRunMemberEmit<'a> {
    slot: &'a str,
    child_id: &'a str,
    ops: &'a [Vec<u8>],
    emit: &'a mut Option<ChildEmit>,
    deadline_us: u64,
}

impl store::MemberStoreVisitor for ToolRunMemberEmit<'_> {
    type Output = Result<bool, Fault>;

    fn visit<P, Mu>(self, _store: &ArtifactStore<P, Mu>) -> Self::Output
    where
        P: Clone + semio_framework_value::ToValue + semio_framework_value::FromValue + ArtifactPack + semio_framework_schema_composition::ArtifactCompositionFields + Send + Sync + 'static,
        Mu: Clone + semio_framework_value::ToValue + semio_framework_value::FromValue + ::protocol::Mutation<P> + protocol::SemanticMutation<P> + ::protocol::OpBinary + ::protocol::OpText + Send + 'static,
    {
        let emit = self.emit.get_or_insert_with(|| ChildEmit::open(self.slot, self.child_id, self.ops.len()));
        while emit.ops.len() < self.ops.len() {
            let op = <Mu as ::protocol::OpBinary>::decode_op(&self.ops[emit.ops.len()]).map_err(|error| error.into_fault())?;
            emit.push::<P, Mu>(&op);
            <Mu as ::protocol::Mutation<P>>::retire_cold(op);
            if emit.ops.len() % TOOL_RUN_REFOLD_CHECK_OPS == 0 && emit.ops.len() < self.ops.len() && semio_framework_job::default_now_us().is_none_or(|now| now >= self.deadline_us) {
                return Ok(false);
            }
        }
        Ok(true)
    }
}

/// 🔢️ The member store's generation, the base a member run watches instead of the document's.
struct ToolRunMemberGeneration;

impl store::MemberStoreVisitor for ToolRunMemberGeneration {
    type Output = u64;

    fn visit<P, Mu>(self, store: &ArtifactStore<P, Mu>) -> Self::Output
    where
        P: Clone + semio_framework_value::ToValue + semio_framework_value::FromValue + ArtifactPack + semio_framework_schema_composition::ArtifactCompositionFields + Send + Sync + 'static,
        Mu: Clone + semio_framework_value::ToValue + semio_framework_value::FromValue + ::protocol::Mutation<P> + protocol::SemanticMutation<P> + ::protocol::OpBinary + ::protocol::OpText + Send + 'static,
    {
        store.generation()
    }
}

/// ♻️ Hands one alias of a member run's owners to the member store's bounded alias retirement: displaced aliases first,
/// and with `everything` the base and overlay too (the run left its slot).
struct ToolRunMemberRetire<'a> {
    owners: &'a mut (dyn ToolRunMemberOwners + 'static),
    everything: bool,
}

impl store::MemberStoreVisitor for ToolRunMemberRetire<'_> {
    type Output = Result<Option<Box<dyn store::ErasedSnapshotRetirement>>, Fault>;

    fn visit<P, Mu>(self, store: &ArtifactStore<P, Mu>) -> Self::Output
    where
        P: Clone + semio_framework_value::ToValue + semio_framework_value::FromValue + ArtifactPack + semio_framework_schema_composition::ArtifactCompositionFields + Send + Sync + 'static,
        Mu: Clone + semio_framework_value::ToValue + semio_framework_value::FromValue + ::protocol::Mutation<P> + protocol::SemanticMutation<P> + ::protocol::OpBinary + ::protocol::OpText + Send + 'static,
    {
        let state = self.owners.as_any_mut().downcast_mut::<ToolRunMemberState<P>>().ok_or_else(|| plugin_sdk_fault("a member tool run's owners belong to another store kind"))?;
        let alias = match state.displaced.pop() {
            Some(alias) => Some(alias),
            None if self.everything => state.overlay.take().or_else(|| state.base.take()).map(store::ArtifactDerivedSnapshot::into_snapshot_owner),
            None => None,
        };
        alias.map(|alias| store.retire_snapshot_alias(alias).map_err(|error| error.into_fault())).transpose()
    }
}
//#endregion 🔖️Member

//#region 🔖️Driver
/// 🎛️ Outcome of one tool run action dispatch; rejections are silent no-ops (§2.1).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ToolRunActionOutcome {
    Applied(ToolRunEffect),
    Rejected(ToolRunRejection),
}

/// 🔢️ One §2.5 action argument read as a `u64`, in every shape the wire can hand it over.
///
/// 🪪️ A JSON number that is an exact non-negative integer IS a `u64` here, and reading it as anything
/// else is not strictness, it is a silent refusal. `toolRunFinalize`'s `generation` crosses as
/// `Number(Float(1.0))` — the shell's own action arguments build it with `UiValue::Number(f64)`, and a
/// guest that mints it with `DslValue::uint` arrives the same way — so accepting only an exact `u64`
/// carrier or a numeric string made `generation` read `None`, and `(_, None)` is
/// `ToolRunRejection::Stale`. EVERY finalize of EVERY app was rejected: runs reached `Complete` and
/// stayed there, and because a start against a live run is `ToolRunRejection::Busy`, no tool run could
/// ever be started a second time. Measured on 6018 as a 3d preview that never re-evaluated after the
/// first evaluation of a session (`📓️preview-rearm-after-inspector-edit-2026-09-14.md`).
pub(crate) fn tool_run_arg_u64(args: Option<&DslValue>, key: &str) -> Option<u64> {
    let value = args?.get(key)?;
    value
        .as_u64()
        .or_else(|| value.as_str().and_then(|text| text.parse().ok()))
        .or_else(|| value.as_f64().filter(|number| number.is_finite() && *number >= 0.0 && number.fract() == 0.0 && *number < 18_446_744_073_709_551_616.0).map(|number| number as u64))
}

impl<A: ArtifactApp, M: SpaceMember + MemberFactory + 'static> VcsArtifactApp<A, M> {
    /// 🏃️ Ledger work plus an unobserved store or settings generation change the watch still owes.
    pub(crate) fn tool_run_has_pending_work(&self) -> bool {
        self.tool_runs.has_pending_work()
            || self.tool_runs.is_ui_dirty()
            || self.tool_runs.entries.iter().any(|entry| {
                matches!(entry.slot.state, ToolRunState::Running | ToolRunState::Paused | ToolRunState::Complete | ToolRunState::Finalizing)
                    && (entry.base_generation != self.store.generation()
                        || entry.settings_generation != self.tool_run_settings_generation()
                        || entry.member.as_ref().is_some_and(|member| self.children.get(&(member.slot.clone(), member.child_id.clone())).is_some_and(|child| child.member.visit_member(ToolRunMemberGeneration) != member.base_generation)))
            })
    }

    /// 🎚️ The committed settings generations the driver watches (config store, window-config publications).
    fn tool_run_settings_generation(&self) -> (u64, u64) {
        (self.config_store.generation(), self.tool_runs.driver.window_config_publications)
    }

    /// ⏯️ Host-driven routing of the §2.5 actions: applied to the ledger now, never queued behind the run.
    ///
    /// 🧯️ A rejection REPAINTS the panel. The panel's buttons carry the run identity captured when
    /// the panel last rendered, and a settings change bumps the live generation — so a stale press
    /// was rejected, published `UiDirtyScope::None`, and therefore left the same stale identity on
    /// the button: every later press was silently rejected too, forever. Measured 2026-09-17 on a
    /// ◻️2d fill that stayed `Paused · Searching an open handle (2/5)` for 30 s after Abort.
    pub(crate) async fn dispatch_tool_run_action(&mut self, action: &str, args: Option<&DslValue>, meta: &ActionMeta) -> Result<InvocationResult, Fault> {
        let outcome = self.apply_tool_run_action(action, args, meta).await?;
        let output = match outcome {
            ToolRunActionOutcome::Applied(effect) => DslValue::Object(vec![("toolRun".into(), DslValue::String(effect.as_str().into()))]),
            ToolRunActionOutcome::Rejected(rejection) => DslValue::Object(vec![("rejected".into(), DslValue::String(rejection.code().into()))]),
        };
        let ui_scope = match outcome {
            ToolRunActionOutcome::Applied(ToolRunEffect::SpawnJob) => UiDirtyScope::Full,
            ToolRunActionOutcome::Applied(_) => self.tool_runs.dirty_scope(),
            ToolRunActionOutcome::Rejected(_) => self.tool_runs.dirty_scope(),
        };
        let mut result = Self::empty_result(action, meta, Vec::new(), Vec::new(), ui_scope).await;
        result.output = output;
        Ok(result)
    }

    /// ⚖️ Applies one §2.5 action to the ledger and performs the transition's immediate effect. An action that
    /// names no identity at all (neither `runId` nor `generation`, as a keyboard chord dispatches it) targets
    /// the instance's live run at its generation of this dispatch; an identity it does name is checked as is.
    pub async fn apply_tool_run_action(&mut self, action: &str, args: Option<&DslValue>, meta: &ActionMeta) -> Result<ToolRunActionOutcome, Fault> {
        let outcome = self.apply_selected_tool_run_action(action, args, meta).await;
        self.tool_runs.select_primary();
        outcome
    }

    /// ⚖️ [`Self::apply_tool_run_action`] on the run the action addresses: its `runId`, else the primary run.
    ///
    /// 🛑️ An abort is idempotent in the generation: it ends the run whatever that run was last
    /// reconfigured to, exactly as `Dismiss` above already ignores generation entirely. Checking
    /// the button's captured generation made Abort unreachable after any settings change — the
    /// one control whose whole job is to get out of a run it cannot otherwise leave.
    async fn apply_selected_tool_run_action(&mut self, action: &str, args: Option<&DslValue>, meta: &ActionMeta) -> Result<ToolRunActionOutcome, Fault> {
        let Some(action) = ToolRunAction::from_id(action) else {
            return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("toolRun.unknown-action"), format!("'{action}' is not a tool run action")));
        };
        if action == ToolRunAction::Start {
            return self.start_tool_run(args, meta).await;
        }
        let names_identity = args.is_some_and(|args| args.get(TOOL_RUN_ARG_RUN_ID).is_some() || args.get(TOOL_RUN_ARG_GENERATION).is_some());
        match tool_run_arg_u64(args, TOOL_RUN_ARG_RUN_ID) {
            Some(run) => {
                self.tool_runs.select_run(run);
            }
            None => self.tool_runs.select_primary(),
        }
        let live = if names_identity { None } else { self.tool_runs.slot() };
        let run = live.map_or_else(|| tool_run_arg_u64(args, TOOL_RUN_ARG_RUN_ID).unwrap_or(0), |slot| slot.run);
        let generation = live.map(|slot| slot.generation).or_else(|| tool_run_arg_u64(args, TOOL_RUN_ARG_GENERATION).and_then(|value| u32::try_from(value).ok()));
        let event = match (action, generation) {
            (ToolRunAction::Dismiss, _) => ToolRunEvent::Dismiss { run },
            (_, None) => return Ok(ToolRunActionOutcome::Rejected(ToolRunRejection::Stale)),
            (ToolRunAction::Pause, Some(generation)) if self.tool_runs.state() == Some(ToolRunState::Paused) => ToolRunEvent::Resume { run, generation },
            (ToolRunAction::Pause, Some(generation)) => ToolRunEvent::Pause { run, generation },
            (ToolRunAction::Resume, Some(generation)) => ToolRunEvent::Resume { run, generation },
            (ToolRunAction::Step, Some(generation)) => ToolRunEvent::Step { run, generation },
            (ToolRunAction::Finalize, Some(generation)) => ToolRunEvent::Finalize { run, generation },
            (ToolRunAction::Abort, Some(generation)) => {
                let generation = self.tool_runs.slot().filter(|slot| slot.run == run).map_or(generation, |slot| slot.generation);
                let publishing = selected_entry!(self.tool_runs).and_then(|entry| entry.finalize.as_ref()).is_some_and(|finalize| {
                    finalize.published
                        || finalize.publication.as_ref().is_some_and(|publication| {
                            !matches!(publication.phase(), store::ArtifactStoreOneItemPublicationPhase::Preparing | store::ArtifactStoreOneItemPublicationPhase::PreparingCursor | store::ArtifactStoreOneItemPublicationPhase::PreflightingCommit)
                        })
                });
                ToolRunEvent::Abort { run, generation, publishing }
            }
            (ToolRunAction::Start, _) => unreachable!("start handled above"),
        };
        if let Some(entry) = selected_entry_mut!(self.tool_runs).filter(|entry| action == ToolRunAction::Finalize && entry.slot.run == run) {
            entry.actor = meta.actor.clone();
        }
        let effect = match self.tool_runs.apply_event(event) {
            Ok(effect) => effect,
            Err(rejection) => return Ok(ToolRunActionOutcome::Rejected(rejection)),
        };
        match (effect, selected_entry_mut!(self.tool_runs)) {
            (ToolRunEffect::DriveOneUnit, Some(entry)) => entry.pending_step = true,
            (ToolRunEffect::StopScheduling, Some(entry)) => entry.pending_step = false,
            (ToolRunEffect::BeginFinalize, Some(entry)) => entry.finalize = Some(ToolRunFinalize { phase: ToolRunFinalizePhase::Pending, publication: None, retracted: 0, published: false }),
            (ToolRunEffect::CloseJob, _) => self.tool_runs.close_current_job(),
            (ToolRunEffect::CancelBatch, _) => {
                self.tool_runs.close_current_job();
                if let Some(publication) = selected_entry_mut!(self.tool_runs).and_then(|entry| entry.finalize.as_mut()).and_then(|finalize| finalize.publication.as_mut()) {
                    self.store.cancel_apply_batch(publication);
                }
            }
            _ => {}
        }
        Ok(ToolRunActionOutcome::Applied(effect))
    }

    async fn start_tool_run(&mut self, args: Option<&DslValue>, meta: &ActionMeta) -> Result<ToolRunActionOutcome, Fault> {
        let view_state = meta.view_state.as_ref();
        let tool_id = args
            .and_then(|args| args.get(TOOL_RUN_ARG_TOOL_ID))
            .and_then(DslValue::as_str)
            .map(str::to_string)
            .or_else(|| view_state.and_then(|view| view.active_utility_id.clone().filter(|id| self.registry.tool_run(id).is_some()).or_else(|| view.active_tool_id.clone())))
            .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("toolRun.tool-id"), "toolRunStart needs a toolId argument or an active tool"))?;
        let definition =
            self.registry.tool_run(&tool_id).map(|(_, definition)| definition.clone()).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("toolRun.unknown-tool"), format!("tool '{tool_id}' declares no ToolRunDefinition")))?;
        let window_id = args.and_then(|args| args.get(TOOL_RUN_ARG_WINDOW_ID)).and_then(DslValue::as_str).map(str::to_string).or_else(|| view_state.and_then(|view| view.window_id.clone().or_else(|| view.focused_window_id.clone())));
        if definition.mutating && self.time_travel.freezes_local_emits() {
            return Ok(ToolRunActionOutcome::Rejected(ToolRunRejection::Busy));
        }
        let member = definition.member.as_deref().map(|slot| self.tool_run_member_target(slot)).transpose()?;
        let lane = ToolRunLane { mutating: definition.mutating, tool_id: tool_id.clone(), window_id: if definition.mutating { None } else { window_id.clone() } };
        let live: Vec<(ToolRunLane, ToolRunState)> = self.tool_runs.entries.iter().map(|entry| (entry.lane(), entry.slot.state)).collect();
        let replaced = match lane.admit(&live) {
            Ok(replaced) => replaced,
            Err(rejection) => return Ok(ToolRunActionOutcome::Rejected(rejection)),
        };
        let run = self.tool_runs.next_run;
        let transition = match ToolRunMachine::apply(None, ToolRunEvent::Start { run }) {
            Ok(transition) => transition,
            Err(rejection) => return Ok(ToolRunActionOutcome::Rejected(rejection)),
        };
        let slot = transition.slot.expect("start yields a slot");
        self.tool_runs.next_run = run.wrapping_add(1);
        for index in replaced.into_iter().rev() {
            let previous = self.tool_runs.entries.remove(index);
            self.tool_runs.retire_entry(*previous);
        }
        self.refresh_cache().await?;
        let (base, _, _) = self.command_cache_inputs();
        let identity = ToolRunIdentity::new(ToolRunId { app_instance_id: self.live_runtime_instance_id.unwrap_or(meta.instance_id), run }, self.store.content_revision());
        let settings_generation = self.tool_run_settings_generation();
        let window = window_id.and_then(|window_id| view_state?.window_instances.iter().find(|window| window.id == window_id).map(|window| (window.id.clone(), window.window_kind_id.clone())));
        let settings_values = self.tool_run_settings_values(&definition.settings, window.as_ref());
        let window_bodies = definition.windows.iter().filter_map(|window_kind_id| self.registry.window_body_key(window_kind_id).map(str::to_string)).collect();
        self.tool_runs.entries.push(Box::new(ToolRunEntry {
            tool_id,
            actor: meta.actor.clone(),
            settings_values,
            window,
            window_bodies,
            payload: None,
            trace_keys: ToolRunTraceKeys::default(),
            definition,
            slot,
            identity,
            overlay: Arc::clone(&base),
            base,
            base_generation: self.store.generation(),
            settings_generation,
            provisional: Vec::new(),
            entity_marks: Vec::new(),
            entities: Arc::new(BTreeSet::new()),
            refold: None,
            trace: ToolRunTraceStore::new(identity),
            recent_trace: std::collections::VecDeque::with_capacity(TOOL_RUN_PANEL_TRACE_ROWS),
            stage: 0,
            completed: 0,
            total: None,
            counters: Vec::new(),
            steps: ToolRunStepRing::new(),
            step_sequence: 0,
            sequence: 0,
            conflicts: 0,
            rate_origin: None,
            units_per_second: 0.0,
            job: None,
            checkpoint: None,
            pending_step: false,
            finalize: None,
            announced: None,
            port: ToolRunJobPort::default(),
            displaced: Vec::new(),
            member,
        }));
        Ok(ToolRunActionOutcome::Applied(transition.effect))
    }

    /// 🧵️ Builds the run's job for `purpose`: the app's retargetable job when it builds one, else its plain job.
    fn build_tool_run_job_slot(&self, entry: &ToolRunEntry<A>, purpose: ToolRunJobPurpose) -> Result<Option<ToolRunJobSlot<A::Config>>, Fault> {
        let request = || ToolRunJobRequest::<A> {
            tool_id: &entry.tool_id,
            definition: &entry.definition,
            purpose,
            identity: entry.identity,
            snapshot: match purpose {
                ToolRunJobPurpose::Run => Arc::clone(&entry.base),
                ToolRunJobPurpose::Revalidate => self.store.snapshot_owner(),
            },
            config: self.config_store.snapshot_owner(),
            window_id: entry.window.as_ref().map(|(window_id, _)| window_id.as_str()),
            window_config: entry.window.as_ref().and_then(|(window_id, window_kind_id)| self.window_config_store.snapshot(window_kind_id, window_id)),
            checkpoint: entry.checkpoint.as_deref(),
            provisional: &entry.provisional,
            instance_owner: self.instance_operation_owner.clone(),
            port: entry.port.clone(),
            trace_keys: entry.trace_keys.clone(),
            entity_marks: &entry.entity_marks,
            children: ChildContentView::clone(&self.child_content_root),
            member_ops: entry.member.as_ref().map_or(&[], |member| member.ops.as_slice()),
        };
        let generation = entry.identity.generation;
        if let Some(job) = A::build_retargetable_tool_run_job(request())? {
            return Ok(Some(ToolRunJobSlot::new(ToolRunJobHandle::Retargetable(job), purpose, generation)));
        }
        Ok(A::build_tool_run_job(request())?.map(|job| ToolRunJobSlot::new(ToolRunJobHandle::Plain(job), purpose, generation)))
    }

    /// 🎚️ What the run's declared settings reads name right now. A declared window kind that is the starting
    /// window's reads only that window's config, the one its jobs receive; any other declared kind reads every
    /// partition of that kind.
    fn tool_run_settings_values(&self, reads: &ToolRunSettingsReads, window: Option<&(String, String)>) -> ToolRunSettingsValues {
        let config = if reads.config.is_empty() {
            Vec::new()
        } else {
            let document = semio_framework_value::ToValue::to_value(self.config_store.snapshot_owner().as_ref());
            reads.config.iter().map(|pointer| tool_run_pointer_value(&document, pointer).cloned()).collect()
        };
        let window_config = reads
            .window_config
            .iter()
            .flat_map(|(window_kind_id, pointers)| {
                let started = window.filter(|(_, kind)| kind == window_kind_id).map(|(window_id, _)| window_id.as_str());
                self.window_config_store.pointer_values(window_kind_id, pointers).into_iter().filter(move |(window_id, _)| started.is_none_or(|started| started == window_id)).map(move |(window_id, values)| (window_kind_id.clone(), window_id, values))
            })
            .collect();
        ToolRunSettingsValues { config, window_config }
    }

    fn apply_tool_run_driver_event(&mut self, event: ToolRunEvent) -> Option<ToolRunEffect> {
        self.tool_runs.apply_event(event).ok()
    }

    /// 📮️ Hands the host every effect jobs queued on the port, in order, while the typed effect outbox has room.
    fn drain_tool_run_port(&mut self) {
        for index in 0..self.tool_runs.entries.len() {
            while let Some(effect) = self.tool_runs.entries[index].port.pop_effect() {
                if let Err(effect) = self.typed_effect_outbox.push(effect) {
                    self.tool_runs.entries[index].port.restore_effect(effect);
                    return;
                }
            }
        }
    }

    /// 🎯️ A tick-sized change: progress, steps, trace and provisional appends reach the panel and the scene
    /// windows only (`ToolRunLedger::dirty_scope`).
    fn mark_tool_run_ui_dirty(&mut self) {
        self.tool_runs.ui_dirty = true;
        self.flush_tool_run_ui_dirty();
    }

    /// 📄️ The document every window reads was swapped wholesale (overlay refolded, released or discarded), so
    /// every body is dirty once.
    fn mark_tool_run_document_dirty(&mut self) {
        self.tool_runs.document_dirty = true;
        self.flush_tool_run_ui_dirty();
    }

    /// 📮️ Hands the owed scope to the typed UI outbox once it has room; until then the flags stay set, so a
    /// queued unrelated scope never swallows a run change.
    pub(crate) fn flush_tool_run_ui_dirty(&mut self) {
        if !self.tool_runs.is_ui_dirty() || self.typed_ui_outbox.len() != 0 {
            return;
        }
        let scope = if self.tool_runs.document_dirty { UiDirtyScope::Full } else { self.tool_runs.dirty_scope() };
        if self.typed_ui_outbox.push(scope).is_ok() {
            self.tool_runs.ui_dirty = false;
            self.tool_runs.document_dirty = false;
        }
    }

    /// 🎬️ Scene lane injection (§3.2, §4.1 layer 2): the first World3d, Canvas2d or Board2d scene surface a window body
    /// renders carries the `toolRunTrace` lane answered for the cursor that window's renderer echoed.
    /// Panel bodies, override renders and bodies without a scene surface carry nothing.
    pub(crate) fn inject_tool_run_trace_lane(&mut self, tree: &mut ComponentTree, body_key: &str, view_state: &ViewModel) -> Result<(), Fault> {
        let Some(window_id) = view_state.window_id.as_deref() else { return Ok(()) };
        self.tool_runs.retain_trace_windows(|live| view_state.window_instances.iter().any(|window| window.id == live));
        let Some(surface) = tool_run_scene_surface(&mut tree.root) else {
            self.tool_runs.trace_windows.remove(window_id);
            return Ok(());
        };
        let cursor = view_state.tool_run_trace_cursor_by_window_id.get(window_id).copied();
        let Some(lane) = self.tool_runs.trace_lane(window_id, body_key, cursor, TOOL_RUN_TRACE_DELTA_BYTES) else { return Ok(()) };
        inject_tool_run_trace_lane_into(surface, &lane).map_err(|error| plugin_sdk_fault(error.to_string()))
    }

    /// 👀️ Store and settings watch (§3.3): emits `baseChanged` / `settingsChanged` with their policies.
    ///
    /// - A base change rebinds a retargetable job to the new identity in place; any other job is closed and
    ///   rebuilt under the new identity (`restart` also discards the provisional ops), so no tick of the old
    ///   identity is ever produced.
    /// - A config or window-config publication is only a settings change when a value behind one of the run's
    ///   declared `settings` pointers changed; `resume` then retargets a retargetable job in place and rebuilds
    ///   any other from its checkpoint.
    fn watch_tool_run_generations(&mut self) {
        let store_generation = self.store.generation();
        let settings_generation = self.tool_run_settings_generation();
        let member_generation = self.tool_run_member_generation();
        let Some(entry) = selected_entry!(self.tool_runs) else { return };
        let (run, state, rebase, reconfigure) = (entry.slot.run, entry.slot.state, entry.definition.rebase, entry.definition.reconfigure);
        let parent_moved = entry.base_generation != store_generation;
        let base_changed = match (entry.member.as_ref(), member_generation) {
            (Some(member), Some(generation)) => member.base_generation != generation,
            (Some(_), None) => false,
            (None, _) => parent_moved,
        };
        let settings_moved = entry.settings_generation != settings_generation;
        if !matches!(state, ToolRunState::Running | ToolRunState::Paused | ToolRunState::Complete) {
            return;
        }
        if parent_moved && entry.member.is_some() {
            let head = self.store.snapshot_owner();
            let entry = selected_entry_mut!(self.tool_runs).expect("the watch keeps the slot");
            entry.replace_base(head);
            let overlay = Arc::clone(&entry.base);
            entry.replace_overlay(overlay);
            entry.base_generation = store_generation;
        }
        if let (true, Some(generation)) = (base_changed, member_generation.filter(|_| selected_entry!(self.tool_runs).is_some_and(|entry| entry.member.is_some()))) {
            if self.apply_tool_run_driver_event(ToolRunEvent::BaseChanged { run }) == Some(ToolRunEffect::Refold) {
                let restart = rebase == ToolRunRebasePolicy::Restart;
                if restart {
                    self.tool_runs.close_current_job();
                    self.tool_runs.discard_provisional();
                }
                let entry = selected_entry_mut!(self.tool_runs).expect("refold keeps the slot");
                if let Some(member) = entry.member.as_mut() {
                    member.base_generation = generation;
                    member.rebase = true;
                }
                entry.framework_step(ToolRunStepKind::Warning, TOOL_RUN_REASON_REBASING, &[]);
                if !restart {
                    self.tool_runs.retarget_current_job(|job, identity| {
                        job.rebind(identity);
                        true
                    });
                }
                self.mark_tool_run_document_dirty();
            }
        } else if base_changed && self.apply_tool_run_driver_event(ToolRunEvent::BaseChanged { run }) == Some(ToolRunEffect::Refold) {
            let head = self.store.snapshot_owner();
            let restart = rebase == ToolRunRebasePolicy::Restart;
            if restart {
                self.tool_runs.close_current_job();
                self.tool_runs.discard_provisional();
            }
            let entry = selected_entry_mut!(self.tool_runs).expect("refold keeps the slot");
            entry.replace_base(head);
            entry.base_generation = store_generation;
            entry.identity.base_revision = self.store.content_revision();
            entry.trace.rebind(entry.identity);
            if restart {
                let overlay = Arc::clone(&entry.base);
                entry.replace_overlay(overlay);
            } else {
                entry.begin_refold(true);
            }
            entry.framework_step(ToolRunStepKind::Warning, TOOL_RUN_REASON_REBASING, &[]);
            if !restart {
                self.tool_runs.retarget_current_job(|job, identity| {
                    job.rebind(identity);
                    true
                });
            }
            self.mark_tool_run_document_dirty();
        }
        if !settings_moved {
            return;
        }
        let entry = selected_entry!(self.tool_runs).expect("the watch keeps the slot");
        let values = self.tool_run_settings_values(&entry.definition.settings, entry.window.as_ref());
        let entry = selected_entry_mut!(self.tool_runs).expect("the watch keeps the slot");
        entry.settings_generation = settings_generation;
        if values == entry.settings_values {
            return;
        }
        entry.settings_values = values;
        if self.apply_tool_run_driver_event(ToolRunEvent::SettingsChanged { run }) != Some(ToolRunEffect::Reconfigure) {
            return;
        }
        match reconfigure {
            ToolRunReconfigurePolicy::Restart => {
                self.tool_runs.close_current_job();
                self.tool_runs.discard_provisional();
                self.mark_tool_run_document_dirty();
            }
            ToolRunReconfigurePolicy::Resume => {
                let config = self.config_store.snapshot_owner();
                self.tool_runs.retarget_current_job(|job, identity| job.reconfigure(identity, config));
                self.mark_tool_run_ui_dirty();
            }
        }
    }

    /// ⏯️ One bounded driver turn (≤ `ToolRunDriver::turn_wall_us`): owed dirty scope, retirement, watch, refold,
    /// job steps, finalize.
    pub(crate) async fn drive_tool_run_turn(&mut self) -> Result<(), Fault> {
        self.flush_tool_run_ui_dirty();
        self.drain_tool_run_port();
        let started = semio_framework_job::default_now_us().unwrap_or(0);
        let deadline = started.saturating_add(self.tool_runs.driver.turn_wall_us);
        if let Some(step) = self.tool_run_retire_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES)? {
            if !matches!(step, PluginCloseStep::Blocked { .. }) {
                return Ok(());
            }
        }
        let runs: Vec<u64> = self.tool_runs.entries.iter().map(|entry| entry.slot.run).collect();
        let mut outcome = Ok(());
        for run in runs {
            if !self.tool_runs.select_run(run) {
                continue;
            }
            outcome = self.drive_selected_tool_run(deadline).await;
            if outcome.is_err() || semio_framework_job::default_now_us().is_none_or(|now| now >= deadline) {
                break;
            }
        }
        self.tool_runs.select_primary();
        outcome
    }

    /// ⏯️ The selected run's share of one driver turn.
    async fn drive_selected_tool_run(&mut self, deadline: u64) -> Result<(), Fault> {
        let Some(state) = self.tool_runs.state() else { return Ok(()) };
        match state {
            ToolRunState::Aborting => {
                if self.tool_runs.retired_jobs.is_empty() && self.tool_runs.retired_publications.is_empty() {
                    let (run, generation) = self.tool_runs.slot().map(|slot| (slot.run, slot.generation)).expect("aborting slot");
                    if let Some(finalize) = selected_entry_mut!(self.tool_runs).and_then(|entry| entry.finalize.take()) {
                        self.tool_runs.retire_owners(None, Vec::new(), Some(finalize));
                        return Ok(());
                    }
                    if self.apply_tool_run_driver_event(ToolRunEvent::AbortComplete { run, generation }) == Some(ToolRunEffect::RetireProvisional) {
                        self.tool_runs.discard_provisional();
                        self.mark_tool_run_document_dirty();
                    }
                }
                Ok(())
            }
            ToolRunState::Starting => self.admit_tool_run_job().await,
            ToolRunState::Running | ToolRunState::Paused | ToolRunState::Complete => {
                self.watch_tool_run_generations();
                if self.refold_tool_run(deadline) || self.refresh_tool_run_member(deadline)? {
                    return Ok(());
                }
                let entry = selected_entry!(self.tool_runs).expect("live slot");
                let wants_job = match entry.slot.state {
                    ToolRunState::Running => true,
                    ToolRunState::Paused => entry.pending_step,
                    _ => false,
                };
                if wants_job && entry.job.is_none() {
                    return self.admit_tool_run_job().await;
                }
                if wants_job {
                    self.step_tool_run_job(deadline)?;
                }
                Ok(())
            }
            ToolRunState::Finalizing => {
                if self.refresh_tool_run_member(deadline)? {
                    return Ok(());
                }
                self.finalize_tool_run_turn(deadline).await
            }
            ToolRunState::Finalized | ToolRunState::Aborted | ToolRunState::Faulted => Ok(()),
        }
    }

    /// 🔁️ `true` while a refold still owns this turn; a refold waiting only for its job's boundary lets the job step.
    fn refold_tool_run(&mut self, deadline: u64) -> bool {
        let Some(entry) = selected_entry_mut!(self.tool_runs).filter(|entry| entry.refold.is_some()) else { return false };
        if entry.job.is_none() {
            entry.settle_refold();
        }
        match entry.refold_turn(deadline) {
            ToolRunRefoldTurn::Pending => true,
            ToolRunRefoldTurn::AwaitingBoundary => false,
            ToolRunRefoldTurn::Swapped => {
                self.mark_tool_run_document_dirty();
                false
            }
        }
    }

    async fn admit_tool_run_job(&mut self) -> Result<(), Fault> {
        let Some(entry) = selected_entry!(self.tool_runs) else { return Ok(()) };
        let (run, generation, state) = (entry.slot.run, entry.slot.generation, entry.slot.state);
        entry.port.wake();
        match self.build_tool_run_job_slot(entry, ToolRunJobPurpose::Run) {
            Ok(Some(job)) => {
                selected_entry_mut!(self.tool_runs).expect("live slot").job = Some(job);
                if state == ToolRunState::Starting {
                    self.apply_tool_run_driver_event(ToolRunEvent::JobAdmitted { run, generation });
                }
            }
            Ok(None) | Err(_) => self.fault_tool_run(run, generation),
        }
        self.mark_tool_run_ui_dirty();
        Ok(())
    }

    fn fault_tool_run(&mut self, run: u64, generation: u32) {
        if self.apply_tool_run_driver_event(ToolRunEvent::JobFault { run, generation }) == Some(ToolRunEffect::DiscardProvisional) {
            self.tool_runs.close_current_job();
            self.tool_runs.discard_provisional();
            if let Some(entry) = selected_entry_mut!(self.tool_runs) {
                entry.framework_step(ToolRunStepKind::Danger, TOOL_RUN_REASON_CONFLICT, &[ToolRunStepArg::Unsigned(0)]);
            }
            self.mark_tool_run_document_dirty();
        }
    }

    /// 🦶️ Drives the current job until the turn deadline, a pause, a single step or a terminal outcome.
    fn step_tool_run_job(&mut self, deadline: u64) -> Result<(), Fault> {
        loop {
            let Some(entry) = selected_entry_mut!(self.tool_runs) else { return Ok(()) };
            let single = entry.slot.state == ToolRunState::Paused;
            let (run, generation, purpose) = (entry.slot.run, entry.slot.generation, entry.job.as_ref().map(|job| job.purpose));
            let Some(job) = entry.job.as_mut() else { return Ok(()) };
            let now = semio_framework_job::default_now_us().unwrap_or(0);
            let fuel = if single { 1 } else { semio_framework_job::INTERACTIVE_LANE_FUEL };
            let budget = semio_framework_job::StepBudget::from_duration(fuel, now, semio_framework_job::INTERACTIVE_LANE_WALL_US).unwrap_or(semio_framework_job::StepBudget::new(fuel, u64::MAX));
            let mut verdict = None;
            let interactive: &mut dyn semio_framework_job::InteractiveJob = match &mut job.job {
                ToolRunJobHandle::Plain(job) => job.as_mut(),
                ToolRunJobHandle::Retargetable(job) => job.as_mut(),
            };
            let mut outcome = semio_framework_job::drive_step(
                interactive,
                TOOL_RUN_JOB_SITE,
                job.operation,
                job.generation,
                semio_framework_job::InteractiveStage::InteractiveStep,
                budget,
                job.cancel.clone(),
                semio_framework_job::default_now_us,
                &mut job.preview_sequence,
                &mut verdict,
            );
            if single && !matches!(outcome, semio_framework_job::StepOutcome::Yield | semio_framework_job::StepOutcome::CheckpointReady(_)) {
                entry.pending_step = false;
            }
            let mut terminal = false;
            match &mut outcome {
                semio_framework_job::StepOutcome::Yield => {}
                semio_framework_job::StepOutcome::PreviewReady(payload) => {
                    let bytes = job_payload_bytes(payload, TOOL_RUN_TICK_BYTES_MAX);
                    close_job_payload(payload);
                    let tick = bytes
                        .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("toolRun.tick-bytes"), "tool run tick exceeds its byte cap"))
                        .and_then(|bytes| ToolRunTick::decode(&bytes).map_err(|error| Fault::new(FaultOrigin::Framework, FaultCode::new("toolRun.tick-decode"), format!("{error:?}"))));
                    let receipt = match tick {
                        Ok(tick) => entry.apply_tick(tick, &mut self.tool_runs.discarded),
                        Err(fault) => Err(fault),
                    };
                    match receipt {
                        Ok(receipt) => {
                            if let (Some(finalize), ToolRunJobPurpose::Revalidate) = (entry.finalize.as_mut(), purpose.unwrap_or(ToolRunJobPurpose::Run)) {
                                finalize.retracted = finalize.retracted.saturating_add(receipt.retracted);
                            }
                            if receipt.capped && purpose == Some(ToolRunJobPurpose::Run) {
                                self.complete_tool_run_job(run, generation);
                                terminal = true;
                            }
                            self.mark_tool_run_ui_dirty();
                        }
                        Err(_) => {
                            self.fault_tool_run(run, generation);
                            terminal = true;
                        }
                    }
                }
                semio_framework_job::StepOutcome::CheckpointReady(checkpoint) => {
                    entry.checkpoint = job_payload_bytes(&checkpoint.state, semio_framework_job::JOB_PAYLOAD_OPERATION_BYTES);
                    close_job_payload(&mut checkpoint.state);
                    entry.settle_refold();
                }
                semio_framework_job::StepOutcome::Complete(_) => {
                    close_step_outcome(&mut outcome);
                    entry.settle_refold();
                    match purpose {
                        Some(ToolRunJobPurpose::Revalidate) => self.complete_tool_run_revalidation(),
                        _ => self.complete_tool_run_job(run, generation),
                    }
                    terminal = true;
                }
                semio_framework_job::StepOutcome::Cancelled | semio_framework_job::StepOutcome::Fault(_) => {
                    close_step_outcome(&mut outcome);
                    self.fault_tool_run(run, generation);
                    terminal = true;
                }
            }
            self.drain_tool_run_port();
            if terminal || single || selected_entry!(self.tool_runs).is_none_or(|entry| entry.port.is_waiting()) || semio_framework_job::default_now_us().is_none_or(|now| now >= deadline) {
                return Ok(());
            }
            if !selected_entry!(self.tool_runs).is_some_and(|entry| entry.job.is_some() && matches!(entry.slot.state, ToolRunState::Running | ToolRunState::Finalizing)) {
                return Ok(());
            }
        }
    }

    /// 🏁️ A finished job's completion — and, for a READ-ONLY run, its finalization too.
    ///
    /// 🪪️ `Complete` means "the job is done and the run awaits the finalize that publishes its
    /// provisional edits". A run that declares `mutating: false` authors no provisional edit at all, so
    /// there is nothing for a finalize to publish and nothing for a user to review: leaving it parked in
    /// `Complete` only holds the tool's single run slot open, and a `toolRunStart` against a non-terminal
    /// run is `ToolRunRejection::Busy`. That is how generation3d's read-only `previewEval` ran exactly
    /// ONCE per session — every later start, whether a poll's or a gesture's own, was refused by the
    /// finished run still sitting in the slot, and the 3d preview stopped re-evaluating
    /// (`📓️preview-rearm-after-inspector-edit-2026-09-14.md`, `📋️tool-run-contract.md` §2.2). Asking a
    /// read-only run's owner to dispatch a finalize it has nothing to finalize is a round trip the host
    /// can always lose: it happens on the host's own refresh cadence, and a run action that publishes
    /// nothing moves no UI that would provoke the next pass.
    fn complete_tool_run_job(&mut self, run: u64, generation: u32) {
        let resident = selected_entry_mut!(self.tool_runs).is_some_and(|entry| entry.definition.mutating && entry.job.as_mut().is_some_and(|job| job.retargetable().is_some()));
        if resident {
            selected_entry_mut!(self.tool_runs).expect("a resident job has a slot").settle_refold();
        } else {
            self.tool_runs.close_current_job();
        }
        self.apply_tool_run_driver_event(ToolRunEvent::JobComplete { run, generation });
        if let Some(entry) = selected_entry_mut!(self.tool_runs) {
            entry.pending_step = false;
        }
        if selected_entry!(self.tool_runs).is_some_and(|entry| !entry.definition.mutating && entry.slot.state == ToolRunState::Complete) {
            let (run, generation) = self.tool_runs.slot().map(|slot| (slot.run, slot.generation)).expect("a complete run has a slot");
            if let Some(ToolRunEffect::BeginFinalize) = self.apply_tool_run_driver_event(ToolRunEvent::Finalize { run, generation }) {
                if let Some(entry) = selected_entry_mut!(self.tool_runs) {
                    entry.finalize = Some(ToolRunFinalize { phase: ToolRunFinalizePhase::Pending, publication: None, retracted: 0, published: false });
                }
            }
        }
        self.mark_tool_run_document_dirty();
    }

    fn complete_tool_run_revalidation(&mut self) {
        self.tool_runs.close_current_job();
        let Some(entry) = selected_entry_mut!(self.tool_runs) else { return };
        let (run, generation) = (entry.slot.run, entry.slot.generation);
        let retracted = entry.finalize.as_ref().map_or(0, |finalize| finalize.retracted);
        if retracted == 0 {
            if let Some(finalize) = entry.finalize.as_mut() {
                finalize.phase = ToolRunFinalizePhase::Publishing;
            }
            return;
        }
        entry.conflicts = entry.conflicts.saturating_add(retracted);
        entry.framework_step(ToolRunStepKind::Danger, TOOL_RUN_REASON_CONFLICT, &[ToolRunStepArg::Unsigned(u64::from(retracted))]);
        let finalize = entry.finalize.take();
        self.tool_runs.retire_owners(None, Vec::new(), finalize);
        self.apply_tool_run_driver_event(ToolRunEvent::RevalidationConflicts { run, generation });
        self.mark_tool_run_document_dirty();
    }

    /// 🏁️ Finalize (§2.7.4): freshness refold on the head, optional revalidate job, one outbound batched `Edit`.
    async fn finalize_tool_run_turn(&mut self, deadline: u64) -> Result<(), Fault> {
        let store_generation = self.store.generation();
        let member_generation = self.tool_run_member_generation();
        let entry = selected_entry_mut!(self.tool_runs).expect("finalizing slot");
        let phase = entry.finalize.as_ref().map_or(ToolRunFinalizePhase::Pending, |finalize| finalize.phase);
        let moved = match (entry.member.as_ref(), member_generation) {
            (Some(member), Some(generation)) => member.base_generation != generation,
            (Some(_), None) => false,
            (None, _) => entry.base_generation != store_generation,
        };
        let republish = matches!(phase, ToolRunFinalizePhase::Pending | ToolRunFinalizePhase::Revalidating) || (phase == ToolRunFinalizePhase::Publishing && entry.member.is_some());
        if moved && republish {
            entry.replace_base(self.store.snapshot_owner());
            entry.base_generation = store_generation;
            entry.begin_refold(true);
            if let (Some(member), Some(generation)) = (entry.member.as_mut(), member_generation) {
                member.base_generation = generation;
                member.rebase = true;
                member.emit = None;
            }
            entry.framework_step(ToolRunStepKind::Warning, TOOL_RUN_REASON_REBASING, &[]);
            if let Some(finalize) = entry.finalize.as_mut() {
                finalize.phase = ToolRunFinalizePhase::Pending;
                finalize.retracted = 0;
            }
            self.tool_runs.close_current_job();
            return Ok(());
        }
        if self.refold_tool_run(deadline) {
            return Ok(());
        }
        match phase {
            ToolRunFinalizePhase::Pending => {
                if selected_entry!(self.tool_runs).is_some_and(|entry| entry.job.as_ref().is_some_and(|job| job.purpose == ToolRunJobPurpose::Run)) {
                    self.tool_runs.close_current_job();
                    return Ok(());
                }
                let entry = selected_entry!(self.tool_runs).expect("finalizing slot");
                let (run, generation) = (entry.slot.run, entry.slot.generation);
                let next = if entry.definition.revalidate_job.is_some() && !(entry.provisional.is_empty() && entry.member.as_ref().is_none_or(|member| member.ops.is_empty())) {
                    match self.build_tool_run_job_slot(entry, ToolRunJobPurpose::Revalidate) {
                        Ok(Some(job)) => {
                            selected_entry_mut!(self.tool_runs).expect("finalizing slot").job = Some(job);
                            ToolRunFinalizePhase::Revalidating
                        }
                        Ok(None) | Err(_) => return self.reject_tool_run_publication(run, generation),
                    }
                } else {
                    ToolRunFinalizePhase::Publishing
                };
                if let Some(finalize) = selected_entry_mut!(self.tool_runs).and_then(|entry| entry.finalize.as_mut()) {
                    finalize.phase = next;
                }
                Ok(())
            }
            ToolRunFinalizePhase::Revalidating => self.step_tool_run_job(deadline),
            ToolRunFinalizePhase::Publishing => self.publish_tool_run(deadline).await,
            ToolRunFinalizePhase::Closing => self.close_tool_run_publication(),
        }
    }

    fn reject_tool_run_publication(&mut self, run: u64, generation: u32) -> Result<(), Fault> {
        let Some(entry) = selected_entry_mut!(self.tool_runs) else { return Ok(()) };
        entry.framework_step(ToolRunStepKind::Danger, TOOL_RUN_REASON_CONFLICT, &[ToolRunStepArg::Unsigned(entry.provisional.len() as u64)]);
        let finalize = entry.finalize.take();
        self.tool_runs.close_current_job();
        self.tool_runs.retire_owners(None, Vec::new(), finalize);
        self.apply_tool_run_driver_event(ToolRunEvent::StoreRejected { run, generation });
        self.mark_tool_run_ui_dirty();
        Ok(())
    }

    /// 🏷️ The history row label of a transaction a finalized run published (`<appId>#<toolId>` of a declared tool
    /// run): the tool's own label in every locale, so the row reads the same after a reload.
    pub(crate) fn tool_run_transaction_label(&self, app_id: &str, transaction: &protocol::TransactionRef) -> Option<LocalizedLabel> {
        let tool_id = transaction.tool.strip_prefix(app_id)?.strip_prefix('#')?;
        self.registry.tool_run(tool_id).map(|(label, _)| label.clone())
    }

    /// ♻️ Each folded op leaves the root it was prepared against returned to the Store; reclaim it before the
    /// next fold, or a large finalize keeps one whole document per op (see `reclaim_document_snapshot_read_returns`).
    async fn publish_tool_run(&mut self, deadline: u64) -> Result<(), Fault> {
        if selected_entry!(self.tool_runs).is_some_and(|entry| entry.member.is_some()) {
            return self.publish_tool_run_member(deadline).await;
        }
        let entry = selected_entry_mut!(self.tool_runs).expect("finalizing slot");
        let (run, generation) = (entry.slot.run, entry.slot.generation);
        if entry.provisional.is_empty() {
            entry.finalize.as_mut().expect("finalize owner").phase = ToolRunFinalizePhase::Closing;
            return Ok(());
        }
        if entry.finalize.as_ref().is_some_and(|finalize| finalize.publication.is_none()) {
            let transaction = tool_run_transaction(self.app.instance_id().await, &entry.tool_id, &entry.actor, run);
            self.store.set_local_actor_id(Some(entry.actor.clone())).map_err(|error| error.into_fault())?;
            match self.store.begin_outbound_apply_batch(
                semio_framework_job::allocate_operation_id(),
                entry.base_generation,
                self.store.content_revision(),
                entry.actor.clone(),
                entry.provisional.clone(),
                None,
                self.artifact_one_item_factory.as_ref(),
                Some(transaction),
            ) {
                Ok(publication) => entry.finalize.as_mut().expect("finalize owner").publication = Some(publication),
                Err(_) => return self.reject_tool_run_publication(run, generation),
            }
        }
        loop {
            if !self.reclaim_document_snapshot_read_returns(PUBLICATION_SNAPSHOT_READ_RECLAIM_STEPS)? {
                if semio_framework_job::default_now_us().is_none_or(|now| now >= deadline) {
                    return Ok(());
                }
                continue;
            }
            let entry = selected_entry_mut!(self.tool_runs).expect("finalizing slot");
            let publication = entry.finalize.as_mut().and_then(|finalize| finalize.publication.as_mut()).expect("admitted publication");
            match self.store.advance_apply_batch(publication, TOOL_RUN_PUBLICATION_GRANT) {
                Ok(store::ArtifactStoreOneItemAdvance::Published(_)) => {
                    let group_id = entry.identity.id.group_id();
                    let tool_id = entry.tool_id.clone();
                    let actor = entry.actor.clone();
                    self.store.stamp_tail_group_id(&group_id).await.map_err(|error| error.into_fault())?;
                    let publication = selected_entry_mut!(self.tool_runs).and_then(|entry| entry.finalize.as_mut()).and_then(|finalize| finalize.publication.as_mut()).expect("published publication");
                    self.store.flush_published_apply_batch(publication).await.map_err(|error| error.into_fault())?;
                    publication.acknowledge();
                    let edit_id = self.store.envelope().vcs.edits.last().map(|edit| edit.id.clone());
                    let label = self.registry.tool_run(&tool_id).map(|(label, _)| label.clone());
                    self.record_command(&tool_id, ActionKind::Mutation, label, edit_id, Vec::new(), None);
                    self.revalidate_interaction_state_after_document_change(&ActionMeta { actor, instance_id: self.live_runtime_instance_id.unwrap_or(1), view_state: None }).await?;
                    let entry = selected_entry_mut!(self.tool_runs).expect("finalizing slot");
                    let finalize = entry.finalize.as_mut().expect("finalize owner");
                    finalize.published = true;
                    finalize.phase = ToolRunFinalizePhase::Closing;
                    return Ok(());
                }
                Ok(store::ArtifactStoreOneItemAdvance::Blocked) => return Ok(()),
                Ok(_) => {}
                Err(_) => return self.reject_tool_run_publication(run, generation),
            }
            if semio_framework_job::default_now_us().is_none_or(|now| now >= deadline) {
                return Ok(());
            }
        }
    }

    /// 🎨️ The finalize SUCCEEDED, so the provisional ops are released — but the run's payload is
    /// its result, not provisional work, and its declared windows keep rendering it once the run
    /// is `Finalized`. See `ToolRunLedger::release_provisional`.
    fn close_tool_run_publication(&mut self) -> Result<(), Fault> {
        let entry = selected_entry_mut!(self.tool_runs).expect("finalizing slot");
        let (run, generation) = (entry.slot.run, entry.slot.generation);
        let finalize = entry.finalize.as_mut().expect("finalize owner");
        if let Some(publication) = finalize.publication.as_mut() {
            match publication.close_step(TOOL_RUN_PUBLICATION_GRANT).map_err(|error| plugin_sdk_fault(error.into_message()))? {
                store::SnapshotRetirementStep::Complete if publication.terminal_is_empty() => finalize.publication = None,
                store::SnapshotRetirementStep::Complete => return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("toolRun.publication-close"), "tool run publication closed without its terminal-empty witness")),
                _ => return Ok(()),
            }
            return Ok(());
        }
        entry.finalize = None;
        if self.apply_tool_run_driver_event(ToolRunEvent::PublicationComplete { run, generation }) == Some(ToolRunEffect::ReleaseProvisional) {
            let store_generation = self.store.generation();
            let member_generation = self.tool_run_member_generation();
            let head = self.store.snapshot_owner();
            self.tool_runs.release_provisional(true);
            let entry = selected_entry_mut!(self.tool_runs).expect("finalized slot");
            entry.replace_base(head);
            let overlay = Arc::clone(&entry.base);
            entry.replace_overlay(overlay);
            entry.base_generation = store_generation;
            if let (Some(member), Some(generation)) = (entry.member.as_mut(), member_generation) {
                member.base_generation = generation;
            }
        }
        self.mark_tool_run_document_dirty();
        Ok(())
    }

    /// 🧩️ The member a run declaring `ToolRunDefinition::member` edits: the one live owned child composed under `slot`, with
    /// the member store generation the run rests on. No such child, or several, refuse the start by name.
    fn tool_run_member_target(&self, slot: &str) -> Result<ToolRunMemberRun, Fault> {
        let mut candidates = self.children.entries().filter(|entry| entry.owner.slot == slot);
        let (Some(entry), None) = (candidates.next(), candidates.next()) else {
            return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("toolRun.member-unavailable"), format!("a member tool run needs exactly one live owned child in slot '{slot}'")));
        };
        Ok(ToolRunMemberRun {
            slot: slot.to_string(),
            child_id: entry.owner.child_id.clone(),
            dialect: entry.reference.dialect.clone(),
            base_generation: entry.member.visit_member(ToolRunMemberGeneration),
            ops: Vec::new(),
            shown: 0,
            rebase: false,
            owners: None,
            children: None,
            stale: Vec::new(),
            emit: None,
        })
    }

    /// 🔢️ The live generation of the member the selected run edits; `None` for a document run or a member that is gone.
    fn tool_run_member_generation(&self) -> Option<u64> {
        let member = selected_entry!(self.tool_runs)?.member.as_ref()?;
        self.children.get(&(member.slot.clone(), member.child_id.clone())).map(|child| child.member.visit_member(ToolRunMemberGeneration))
    }

    /// 🔁️ Brings the selected member run's composed read up to its provisional ops within the turn wall budget: retires the
    /// reads it replaced, folds the ops the overlay does not show yet (all of them after a rebase) and leases the overlay in
    /// the member's place once every op is shown. `true` while the fold still owns this turn; a fold that cannot apply its
    /// ops (they do not decode as the member's vocabulary) faults the run.
    fn refresh_tool_run_member(&mut self, deadline: u64) -> Result<bool, Fault> {
        let Some(mut member) = selected_entry_mut!(self.tool_runs).and_then(|entry| entry.member.take()) else { return Ok(false) };
        let outcome = self.refresh_member_overlay(&mut member, deadline);
        let entry = selected_entry_mut!(self.tool_runs).expect("a member run keeps its slot");
        entry.member = Some(member);
        let (run, generation) = (entry.slot.run, entry.slot.generation);
        match outcome {
            Ok(Some((pending, conflicts, rebased))) => {
                entry.conflicts = entry.conflicts.saturating_add(conflicts);
                if !pending {
                    if rebased {
                        self.mark_tool_run_document_dirty();
                    } else {
                        self.mark_tool_run_ui_dirty();
                    }
                }
                Ok(pending)
            }
            Ok(None) => Ok(false),
            Err(_) => {
                self.fault_tool_run(run, generation);
                Ok(false)
            }
        }
    }

    /// 🔁️ [`Self::refresh_tool_run_member`] on a member taken out of its entry: `(fold pending, conflicts, rebased)`, or
    /// `None` when the overlay already shows every op.
    fn refresh_member_overlay(&mut self, member: &mut ToolRunMemberRun, deadline: u64) -> Result<Option<(bool, u32, bool)>, Fault> {
        let stale = std::mem::take(&mut member.stale);
        self.retire_tool_run_views(stale, &mut member.stale)?;
        if !member.rebase && member.shown == member.ops.len() {
            return Ok(None);
        }
        let child = self.children.get(&(member.slot.clone(), member.child_id.clone())).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("toolRun.member-gone"), format!("the member {}/{} a tool run edits is gone", member.slot, member.child_id)))?;
        let rebased = member.rebase;
        let folded = child.member.visit_member(ToolRunMemberFold { owners: &mut member.owners, ops: &member.ops, shown: member.shown, rebase: member.rebase, deadline_us: deadline })?;
        member.rebase = false;
        member.shown = folded.shown;
        let pending = folded.shown < member.ops.len();
        if !pending {
            let next = match folded.read {
                Some((read, revision)) => Some(self.child_content_root.with_member_read(&member.slot, &member.child_id, &member.dialect, revision, read)?),
                None => None,
            };
            if let Some(previous) = std::mem::replace(&mut member.children, next) {
                self.retire_tool_run_views(vec![previous], &mut member.stale)?;
            }
        }
        Ok(Some((pending, folded.conflicts, rebased)))
    }

    /// 🧹️ Retires a member run's composed reads in order through the child-content retirements, one admitted generation
    /// each; a refused admission hands the view it could not retire and every later one back to `unretired`.
    fn retire_tool_run_views(&mut self, views: Vec<ChildContentView>, unretired: &mut Vec<ChildContentView>) -> Result<(), Fault> {
        let mut views = views.into_iter();
        while let Some(view) = views.next() {
            match self.admit_child_content_publication() {
                Ok(generation) => {
                    self.child_content_retirements.insert_admitted(generation, ChildContentRetirement::new(view, false));
                    self.child_content_generation = generation;
                }
                Err(fault) => {
                    unretired.push(view);
                    unretired.extend(views);
                    return Err(fault);
                }
            }
        }
        Ok(())
    }

    /// 🏁️ A member run's finalize (§12, §20.14): its provisional ops — at most `TOOL_RUN_MEMBER_OPS_MAX` — decoded through
    /// the member's own vocabulary within the turn wall budget, then published as ONE composite group whose member edit
    /// carries the run's `TransactionRef` and group id: one history row whose mutations are the member's leaves, editable on
    /// that member store. A member that is gone or ops that do not decode reject the publication like a conflicting parent
    /// batch.
    async fn publish_tool_run_member(&mut self, deadline: u64) -> Result<(), Fault> {
        let app_instance_id = self.app.instance_id().await;
        let entry = selected_entry_mut!(self.tool_runs).expect("finalizing slot");
        let (run, generation) = (entry.slot.run, entry.slot.generation);
        let member = entry.member.as_mut().expect("a member run");
        if member.ops.is_empty() {
            entry.finalize.as_mut().expect("finalize owner").phase = ToolRunFinalizePhase::Closing;
            return Ok(());
        }
        let decoded = self.children.get(&(member.slot.clone(), member.child_id.clone())).map(|child| child.member.visit_member(ToolRunMemberEmit { slot: &member.slot, child_id: &member.child_id, ops: &member.ops, emit: &mut member.emit, deadline_us: deadline }));
        match decoded {
            Some(Ok(true)) => {}
            Some(Ok(false)) => return Ok(()),
            _ => return self.reject_tool_run_publication(run, generation),
        }
        let entry = selected_entry_mut!(self.tool_runs).expect("finalizing slot");
        let emit = entry.member.as_mut().and_then(|member| member.emit.take()).expect("a decoded member emission");
        let transaction = tool_run_transaction(app_instance_id, &entry.tool_id, &entry.actor, run);
        let (tool_id, group_id) = (entry.tool_id.clone(), entry.identity.id.group_id());
        let meta = ActionMeta { actor: entry.actor.clone(), instance_id: self.live_runtime_instance_id.unwrap_or(1), view_state: None };
        if self.dispatch_emit_group(&tool_id, &[], std::slice::from_ref(&emit), None, Vec::new(), Vec::new(), UiDirtyScope::Full, &meta, Some(group_id), Some(transaction)).await.is_err() {
            return self.reject_tool_run_publication(run, generation);
        }
        self.revalidate_interaction_state_after_document_change(&meta).await?;
        let finalize = selected_entry_mut!(self.tool_runs).and_then(|entry| entry.finalize.as_mut()).expect("finalize owner");
        finalize.published = true;
        finalize.phase = ToolRunFinalizePhase::Closing;
        Ok(())
    }

    /// ♻️ One bounded unit of member-run retirement: one alias of a member run's typed owners handed to its member store's
    /// alias retirement (displaced aliases of live runs, every alias of a run that left its slot), else the composed reads of
    /// a fully retired member run. `None` when nothing member-owned is retiring or an alias retirement is still stepping.
    fn tool_run_member_retire_step(&mut self) -> Result<Option<PluginCloseStep>, Fault> {
        if self.tool_runs.snapshot_retirement.is_some() {
            return Ok(None);
        }
        let VcsArtifactApp { tool_runs, children, .. } = self;
        let live = tool_runs.entries.iter_mut().filter_map(|entry| entry.member.as_mut()).map(|member| (member, false));
        let retired = tool_runs.retired_members.iter_mut().map(|member| (member, true));
        for (member, everything) in live.chain(retired) {
            let Some(child) = children.get(&(member.slot.clone(), member.child_id.clone())) else {
                member.owners = None;
                continue;
            };
            let Some(owners) = member.owners.as_deref_mut().filter(|owners| everything || owners.has_displaced()) else { continue };
            if let Some(retirement) = child.member.visit_member(ToolRunMemberRetire { owners, everything })? {
                tool_runs.snapshot_retirement = Some(retirement);
                return Ok(Some(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }));
            }
        }
        let Some(index) = self.tool_runs.retired_members.iter().position(|member| member.owners.as_deref().is_none_or(ToolRunMemberOwners::is_empty)) else { return Ok(None) };
        let mut member = self.tool_runs.retired_members.swap_remove(index);
        let views = member.children.take().into_iter().chain(std::mem::take(&mut member.stale)).collect();
        if let Err(fault) = self.retire_tool_run_views(views, &mut member.stale) {
            self.tool_runs.retired_members.push(member);
            return Err(fault);
        }
        Ok(Some(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }))
    }

    /// ♻️ One bounded retirement unit of the tool run ledger, member-owned aliases and reads first.
    fn tool_run_retire_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<Option<PluginCloseStep>, Fault> {
        match self.tool_run_member_retire_step()? {
            Some(step) => Ok(Some(step)),
            None => self.tool_runs.retire_step(&mut self.store, maximum_items, maximum_bytes),
        }
    }

    /// 🚪️ One bounded close unit of the tool run ledger (document close, retirement, reload): every run ends as an abort and
    /// its owners — member-owned ones against their member store — retire.
    pub(crate) fn tool_run_close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
        self.tool_runs.begin_close();
        Ok(self.tool_run_retire_step(maximum_items, maximum_bytes)?.unwrap_or(PluginCloseStep::Complete))
    }
}

/// 🧾️ The transaction a finalized run publishes as: tool `<appId>#<toolId>`, id minted from the run's actor, the host
/// clock and the run counter, so every op of the run's one edit is one history row that time travel can open.
pub(crate) fn tool_run_transaction(app_id: &str, tool_id: &str, actor: &str, run: u64) -> protocol::TransactionRef {
    let clock = semio_framework_tool_machine::authoring_clock(run);
    protocol::TransactionRef::mint(&ActorId(actor.to_string()), &clock, format!("{app_id}#{tool_id}"))
}
//#endregion 🔖️Driver

//#region 🔖️Panel
fn tool_run_step_text(definition: &ToolRunDefinition, step: &ToolRunStep, locale: Locale) -> String {
    let template = match ToolRunLabel::for_reason(step.reason) {
        Some(label) => label.text(locale).to_string(),
        None => definition.reason(step.reason).map_or_else(|| step.reason.to_string(), |reason| reason.template.resolve(Terminology::Native, locale).to_string()),
    };
    let text = tool_run_format(&template, |name| name.parse::<usize>().ok().and_then(|index| step.args.get(index)).map(|arg| arg.to_plain_string()));
    if step.repeat > 1 {
        format!("{text} ×{}", step.repeat)
    } else {
        text
    }
}

fn tool_run_step_tone(kind: ToolRunStepKind) -> Tone {
    match kind {
        ToolRunStepKind::Info => Tone::Info,
        ToolRunStepKind::Success => Tone::Success,
        ToolRunStepKind::Warning => Tone::Warning,
        ToolRunStepKind::Danger => Tone::Danger,
    }
}

fn tool_run_verdict_tone(verdict: ToolRunVerdict) -> Tone {
    match verdict {
        ToolRunVerdict::Testing => Tone::Neutral,
        ToolRunVerdict::Success => Tone::Success,
        ToolRunVerdict::Warning => Tone::Warning,
        ToolRunVerdict::Danger => Tone::Danger,
    }
}

fn tool_run_state_label(state: ToolRunState) -> ToolRunLabel {
    state.label()
}

impl<A: ArtifactApp> ToolRunLedger<A> {
    /// 🪧️ The framework ToolRun panel (§2.6) as a `ComponentTree` root `framework.toolRun`: a ready group
    /// `framework.toolRun.ready` with an enabled Start for `ready_tool` (the active run-declaring tool) while this
    /// instance holds no run of it, then one group `framework.toolRun.<run>` per run, oldest first, labelled by
    /// `tool_label` of its tool.
    pub fn panel(&mut self, controller_id: &str, locale: Locale, ready_tool: Option<&str>, tool_label: impl Fn(&str) -> Option<String>) -> UiAssemblyResult<BuiltNode> {
        let error = ui_assembly_error;
        let mut groups = BuiltChildren::default();
        if let Some(tool_id) = ready_tool.filter(|tool_id| !self.entries.iter().any(|entry| entry.tool_id == *tool_id)) {
            let label = tool_label(tool_id).unwrap_or_else(|| tool_id.to_string());
            groups.try_push(tool_run_panel_ready_group(tool_id, controller_id, locale, &label)?).map_err(|_| error("tool-run-panel.groups"))?;
        }
        for entry in &mut self.entries {
            let label = tool_label(&entry.tool_id).unwrap_or_else(|| entry.tool_id.clone());
            groups.try_push(tool_run_panel_group(entry, controller_id, locale, &label)?).map_err(|_| error("tool-run-panel.groups"))?;
        }
        column()
            .try_label(if locale == Locale::De { "Werkzeugläufe" } else { "Tool runs" })
            .map_err(|_| error("tool-run-panel.label"))?
            .try_id(semio_framework_tool_run::TOOL_RUN_PANEL_ID)
            .map_err(|_| error("tool-run-panel.id"))?
            .try_children(groups)
            .map_err(|_| error("tool-run-panel.groups"))?
            .try_build()
            .map_err(|_| error("tool-run-panel.build"))
    }
}

/// ▶️ The ready group of a run-declaring tool with no run yet: its status and a real Start button carrying the tool id.
fn tool_run_panel_ready_group(tool_id: &str, controller_id: &str, locale: Locale, label: &str) -> UiAssemblyResult<BuiltNode> {
    let error = ui_assembly_error;
    let scope = format!("{}.ready", semio_framework_tool_run::TOOL_RUN_PANEL_ID);
    let status = text(Label(UiText::clipped(ToolRunLabel::ReadyToStart.text(locale))))
        .live(Liveness::Polite)
        .try_id(format!("{scope}.status"))
        .map_err(|_| error("tool-run-panel.ready-status-id"))?
        .try_build()
        .map_err(|_| error("tool-run-panel.ready-status"))?;
    let mut arguments = UiMapBuilder::try_new().ok_or_else(|| error("tool-run-panel.ready-args"))?;
    arguments.push(TOOL_RUN_ARG_TOOL_ID.to_string(), UiValue::Text(UiText::clipped(tool_id))).map_err(|_| error("tool-run-panel.ready-args"))?;
    let action = ToolRunAction::Start;
    let action_id = ActionId::try_v1(controller_id, action.id()).ok_or_else(|| error("tool-run-panel.action-id"))?;
    let start = button(Label(UiText::clipped(action.label().text(locale))))
        .try_id(format!("{scope}.{}", action.id()))
        .map_err(|_| error("tool-run-panel.button-id"))?
        .try_shortcut(action.chord())
        .map_err(|_| error("tool-run-panel.button-shortcut"))?
        .try_on_with(Trigger::Activate, action_id, UiValue::Map(arguments.finish()))
        .map_err(|_| error("tool-run-panel.button-binding"))?
        .try_build()
        .map_err(|_| error("tool-run-panel.button"))?;
    let mut buttons = BuiltChildren::default();
    buttons.try_push(start).map_err(|_| error("tool-run-panel.buttons"))?;
    let toolbar = row().try_id(format!("{scope}.actions")).map_err(|_| error("tool-run-panel.actions-id"))?.try_children(buttons).map_err(|_| error("tool-run-panel.actions"))?.try_build().map_err(|_| error("tool-run-panel.actions-build"))?;
    let mut children = BuiltChildren::default();
    for child in [status, toolbar] {
        children.try_push(child).map_err(|_| error("tool-run-panel.children"))?;
    }
    column()
        .try_label(label)
        .map_err(|_| error("tool-run-panel.label"))?
        .try_id(scope)
        .map_err(|_| error("tool-run-panel.id"))?
        .try_children(children)
        .map_err(|_| error("tool-run-panel.children"))?
        .try_build()
        .map_err(|_| error("tool-run-panel.build"))
}

/// 🪧️ One run's panel group (§2.6): polite status, progressbar, real buttons with `aria-keyshortcuts` addressing the
/// run by id, step log (live off) and a keyboard-navigable trace list; every id is scoped `framework.toolRun.<run>.`.
///
/// 👁️ The throttle belongs to the ANNOUNCEMENT, never to the text. Publishing the last ANNOUNCED
/// string froze the visible pill at whatever stage the run was in when it was first announced:
/// a `Finalized` run still read `Evaluating nodes (1/2)` on 6021 at 18:28 while its own progress
/// bar had moved on (ticket 26/09/09/PROCEDURAL-3D-END-TO-END). A sighted reader is watching the
/// same string a reader hears, so the string is always current and only `live` is rationed.
fn tool_run_panel_group<A: ArtifactApp>(entry: &mut ToolRunEntry<A>, controller_id: &str, locale: Locale, label: &str) -> UiAssemblyResult<BuiltNode> {
    let error = ui_assembly_error;
    let scope = semio_framework_tool_run::tool_run_panel_group_id(entry.slot.run);
    let state = entry.slot.state;
    let stage_count = entry.definition.stages.len();
    let stage_label = entry.definition.stage(entry.stage).map_or_else(String::new, |stage| stage.label.resolve(Terminology::Native, locale).to_string());
    let status = format!("{} · {stage_label} ({}/{stage_count})", tool_run_state_label(state).text(locale), usize::from(entry.stage) + 1);
    let now_ms = semio_framework_job::default_now_ms().unwrap_or(0);
    let announce = match entry.announced.as_ref() {
        Some((announced_state, at, announced)) => *announced_state != state || (*announced != status && now_ms.saturating_sub(*at) >= TOOL_RUN_STATUS_ANNOUNCE_INTERVAL_MS),
        None => true,
    };
    if announce {
        entry.announced = Some((state, now_ms, status.clone()));
    }
    let live = if !announce {
        Liveness::Off
    } else if state == ToolRunState::Faulted || entry.conflicts > 0 {
        Liveness::Assertive
    } else {
        Liveness::Polite
    };
    let status_node = text(Label(UiText::clipped(&status))).live(live).try_id(format!("{scope}.status")).map_err(|_| error("tool-run-panel.status-id"))?.try_build().map_err(|_| error("tool-run-panel.status"))?;
    let unit = entry.definition.unit.resolve(Terminology::Native, locale).to_string();
    let value_text = match entry.total {
        Some(total) => {
            let percent = if total == 0 { 100 } else { entry.completed.saturating_mul(100) / total };
            tool_run_format(ToolRunLabel::ProgressValueText.text(locale), |name| match name {
                "stage" => Some(stage_label.clone()),
                "i" => Some((usize::from(entry.stage) + 1).to_string()),
                "n" => Some(stage_count.to_string()),
                "completed" => Some(entry.completed.to_string()),
                "total" => Some(total.to_string()),
                "unit" => Some(unit.clone()),
                "pct" => Some(percent.to_string()),
                _ => None,
            })
        }
        None => format!("{stage_label} ({}/{stage_count}): {} {unit}", usize::from(entry.stage) + 1, entry.completed),
    };
    let mut bar = progress(entry.completed as f64, Label(UiText::clipped(&value_text)));
    if let Some(total) = entry.total {
        bar = bar.total(total as f64);
    }
    let bar = bar.try_id(format!("{scope}.progress")).map_err(|_| error("tool-run-panel.progress-id"))?.try_build().map_err(|_| error("tool-run-panel.progress"))?;
    let (run, generation) = (entry.slot.run, entry.slot.generation);
    let mut buttons = BuiltChildren::default();
    let toggle = if state == ToolRunState::Paused { ToolRunAction::Resume } else { ToolRunAction::Pause };
    let actions = if state.is_terminal() { vec![ToolRunAction::Start, ToolRunAction::Dismiss] } else { vec![toggle, ToolRunAction::Step, ToolRunAction::Abort, ToolRunAction::Finalize] };
    for action in actions {
        let mut arguments = UiMapBuilder::try_new().ok_or_else(|| error("tool-run-panel.args"))?;
        let pushed = match action {
            ToolRunAction::Start => arguments.push(TOOL_RUN_ARG_TOOL_ID.to_string(), UiValue::Text(UiText::clipped(&entry.tool_id))).is_ok(),
            _ => arguments.push(TOOL_RUN_ARG_RUN_ID.to_string(), UiValue::Text(UiText::clipped(&run.to_string()))).is_ok() && arguments.push(TOOL_RUN_ARG_GENERATION.to_string(), UiValue::Number(f64::from(generation))).is_ok(),
        };
        if !pushed {
            return Err(error("tool-run-panel.args"));
        }
        let action_id = ActionId::try_v1(controller_id, action.id()).ok_or_else(|| error("tool-run-panel.action-id"))?;
        let legal = action.is_legal_in(Some(state));
        let mut builder = button(Label(UiText::clipped(action.label().text(locale)))).disabled(!legal);
        builder = builder.try_id(format!("{scope}.{}", action.id())).map_err(|_| error("tool-run-panel.button-id"))?;
        builder = builder.try_shortcut(action.chord()).map_err(|_| error("tool-run-panel.button-shortcut"))?;
        if action == ToolRunAction::Finalize && !legal {
            builder = builder.try_describe(ToolRunLabel::FinalizeDisabled.text(locale)).map_err(|_| error("tool-run-panel.finalize-description"))?;
        }
        let node = builder.try_on_with(Trigger::Activate, action_id, UiValue::Map(arguments.finish())).map_err(|_| error("tool-run-panel.button-binding"))?.try_build().map_err(|_| error("tool-run-panel.button"))?;
        buttons.try_push(node).map_err(|_| error("tool-run-panel.buttons"))?;
    }
    let toolbar = row().try_id(format!("{scope}.actions")).map_err(|_| error("tool-run-panel.actions-id"))?.try_children(buttons).map_err(|_| error("tool-run-panel.actions"))?.try_build().map_err(|_| error("tool-run-panel.actions-build"))?;
    let mut step_rows = BuiltChildren::default();
    let newest_steps: Vec<&ToolRunStep> = entry.steps.iter().collect();
    for step in newest_steps.into_iter().rev().take(TOOL_RUN_PANEL_STEP_ROWS) {
        let row = text(Label(UiText::clipped(&tool_run_step_text(&entry.definition, step, locale))))
            .tone(tool_run_step_tone(step.kind))
            .try_id(format!("{scope}.step.{}", step.sequence))
            .map_err(|_| error("tool-run-panel.step-id"))?
            .try_build()
            .map_err(|_| error("tool-run-panel.step"))?;
        step_rows.try_push(row).map_err(|_| error("tool-run-panel.steps"))?;
    }
    let steps = column()
        .live(Liveness::Off)
        .try_label(if locale == Locale::De { "Schritte" } else { "Steps" })
        .map_err(|_| error("tool-run-panel.steps-label"))?
        .try_id(format!("{scope}.steps"))
        .map_err(|_| error("tool-run-panel.steps-id"))?
        .try_children(step_rows)
        .map_err(|_| error("tool-run-panel.steps-children"))?
        .try_build()
        .map_err(|_| error("tool-run-panel.steps-build"))?;
    let mut trace_rows = BuiltChildren::default();
    for key in entry.recent_trace.iter().rev() {
        let Some(record) = entry.trace.record(*key) else { continue };
        let reason = ToolRunStep { sequence: 0, kind: ToolRunStepKind::Info, stage: entry.stage, reason: record.reason, subject: Some(*key), repeat: 1, args: Vec::new() };
        let item = ui::tree_item(Label(UiText::clipped(&tool_run_step_text(&entry.definition, &reason, locale))))
            .tone(tool_run_verdict_tone(record.verdict))
            .try_id(format!("{scope}.trace.{key}"))
            .map_err(|_| error("tool-run-panel.trace-id"))?
            .try_build()
            .map_err(|_| error("tool-run-panel.trace-item"))?;
        trace_rows.try_push(item).map_err(|_| error("tool-run-panel.trace-rows"))?;
    }
    let trace = tree()
        .try_label(if locale == Locale::De { "Versuche" } else { "Attempts" })
        .map_err(|_| error("tool-run-panel.trace-label"))?
        .try_id(format!("{scope}.trace"))
        .map_err(|_| error("tool-run-panel.trace-id"))?
        .try_children(trace_rows)
        .map_err(|_| error("tool-run-panel.trace"))?
        .try_build()
        .map_err(|_| error("tool-run-panel.trace-build"))?;
    let mut children = BuiltChildren::default();
    for child in [status_node, bar, toolbar, steps, trace] {
        children.try_push(child).map_err(|_| error("tool-run-panel.children"))?;
    }
    column()
        .try_label(label)
        .map_err(|_| error("tool-run-panel.label"))?
        .try_id(scope)
        .map_err(|_| error("tool-run-panel.id"))?
        .try_children(children)
        .map_err(|_| error("tool-run-panel.children"))?
        .try_build()
        .map_err(|_| error("tool-run-panel.build"))
}
//#endregion 🔖️Panel

regions.before:
let previous = state.base.replace(store.snapshot_owner());
state.displaced.extend(previous);
state.displaced.extend(state.overlay.take());

let outcome = <Mu as ::protocol::Mutation<P>>::diff(&op, source);
let next = outcome.is_applicable(protocol::MergePolicy::default()).then(|| <<Mu as ::protocol::Mutation<P>>::Diff as ::protocol::MutationDiff<P>>::apply(outcome.diff(), source).ok()).flatten();
<Mu as ::protocol::Mutation<P>>::retire_cold(op);
match next {
    Some(next) => state.displaced.extend(state.overlay.replace(Arc::new(next))),
    None => conflicts = conflicts.saturating_add(1),
}

regions.after:
let next = store.derive_provisional_snapshot(source, &op);
<Mu as ::protocol::Mutation<P>>::retire_cold(op);
match next.map_err(|error| error.into_fault())? {
    Some(next) => state.displaced.extend(state.overlay.replace(next).map(store::ArtifactDerivedSnapshot::into_snapshot_owner)),
    None => conflicts = conflicts.saturating_add(1),
}

