        assert_eq!(round_trip.apply(&before).unwrap(), expected);
        let restore = DemoMutation::RestoreN(RestoreN { n: before.n });
        assert_eq!(restore.diff(&actual).diff().apply(&actual).unwrap(), before);
    }
}

