/// 🎟️ A lease is returned EXACTLY ONCE, on either of the registry's two return paths, and the
/// path a return takes is decided by whether its root is still aliased outside the registry.
///
/// An aliased root has nothing for the retirement pump to dispose, so `try_release_aliased`
/// reclaims its slot on the returning thread and the pump never sees it. A sole-owner root is the
/// last `Arc` in the process, so it is counted into `returned` and handed to the pump, which
/// retires its domain tree in bounded steps. Both paths must refuse a second return of the same
/// generation: a lease that answered twice once leaked a `returned` credit against a slot that had
/// already been freed and reissued.
#[test]
fn snapshot_read_double_return_is_counted_once_and_reclaimed_once() {
    let registry = Arc::new(SnapshotReadLeaseRegistry::new());
    let aliased_root = Arc::new(11u32);
    let mut aliased = registry.try_issue(aliased_root.clone()).expect("exact aliased lease");
    assert!(aliased.return_now());
    assert!(!aliased.return_now(), "the same generation cannot be returned twice on the aliased path");
    assert_eq!(registry.returned.load(std::sync::atomic::Ordering::Acquire), 0, "an aliased root is reclaimed on the returning thread, not charged to the pump");
    assert_eq!(Arc::strong_count(&aliased_root), 1, "the aliased slot released its own owner alias in the same call");
    assert!(registry.try_take_one_returned::<u32>().expect("one fixed return probe").is_none(), "the pump has nothing to reclaim for an aliased return");
    drop(aliased);
    drop(aliased_root);
    assert!(registry.terminal_is_empty());

    let mut lease = registry.try_issue(Arc::new(11u32)).expect("exact sole-owner lease");
    assert!(lease.return_now());
    assert!(!lease.return_now(), "the same generation cannot be returned twice on the pump path");
    assert_eq!(registry.returned.load(std::sync::atomic::Ordering::Acquire), 1);
    let mut reclaimed = None;
    for _ in 0..SNAPSHOT_READ_LEASE_CAPACITY {
        if let Some(owner) = registry.try_take_one_returned::<u32>().expect("one fixed return probe") {
            reclaimed = Some(owner);
            break;
        }
    }
    assert_eq!(reclaimed.as_deref(), Some(&11));
    assert_eq!(registry.returned.load(std::sync::atomic::Ordering::Acquire), 0);
    assert!(registry.try_take_one_returned::<u32>().expect("one fixed return probe").is_none(), "a reclaimed generation is never handed out a second time");
    drop(reclaimed);
    drop(lease);
    assert!(registry.terminal_is_empty());
}

#[test]
fn stale_snapshot_read_generation_cannot_aba_remove_a_reused_slot() {
    let registry = Arc::new(SnapshotReadLeaseRegistry::new());
    let owner = Arc::new(1u16);
    let first = registry.try_issue(owner.clone()).expect("first exact lease");
    let stale_index = first.index;
    let stale_generation = first.generation;
    let first_read = ErasedSnapshotRead::new(owner, first);
    drop(match first_read.into_typed::<u16>(&registry) {
        Ok(owner) => owner,
        Err(_) => panic!("first exact lease retires"),
    });

    let mut reads = Vec::with_capacity(SNAPSHOT_READ_LEASE_CAPACITY);
    let mut reused_generation = None;
    for value in 0..SNAPSHOT_READ_LEASE_CAPACITY {
        let owner = Arc::new(value as u16);
        let lease = registry.try_issue(owner.clone()).expect("fixed ring re-admits every slot");
        if lease.index == stale_index {
            reused_generation = Some(lease.generation);
        }
        reads.push(ErasedSnapshotRead::new(owner, lease));
    }
    assert!(reused_generation.is_some_and(|generation| generation != stale_generation));
    assert!(registry.try_take(stale_index, stale_generation).is_err(), "stale generation cannot remove the reused exact slot");
    for read in reads {
        drop(match read.into_typed::<u16>(&registry) {
            Ok(owner) => owner,
            Err(_) => panic!("every reused exact lease retires"),
        });
    }
    assert!(registry.terminal_is_empty());
}

/// 🧪️ A test store: `new` installs the document type's own retirement authorities (so it records
/// history like a production store) and the store closes itself on drop; `bare` leaves authorities to
/// the test, which then installs and closes them explicitly.
struct ArtifactStore<P, Mutation>(super::ArtifactStore<P, Mutation>, Option<fn(&mut super::ArtifactStore<P, Mutation>)>)
where
    P: Clone + ToValue + FromValue,
    Mutation: Clone + ToValue + FromValue + super::Mutation<P>;

impl<P, Mutation> ArtifactStore<P, Mutation>
where
    P: Clone + ToValue + FromValue + ArtifactPack + Send + 'static,
    Mutation: Clone + ToValue + FromValue + super::Mutation<P> + OpBinary + OpText + Send + 'static,
{
    async fn new(envelope: ArtifactEnvelope<P, Mutation>) -> Self
    where
        P: MemberStoreOwner<Mutation>,
    {
        let mut store = super::ArtifactStore::new(envelope).await.expect("test fixture history is valid");
        store.install_document_store_owners_exact(P::member_store_owners());
        Self(store, Some(close_test_store::<P, Mutation>))
    }

    async fn bare(envelope: ArtifactEnvelope<P, Mutation>) -> Self {
        Self(super::ArtifactStore::new(envelope).await.expect("test fixture history is valid"), None)
    }

    /// 🧹️ Arms the drop-close on a `bare` store once the test has installed its OWN owner catalog:
    /// a store that carries a disposer must still reach its terminal-empty witness before it drops.
    fn closes_on_drop(&mut self) {
        self.1 = Some(close_test_store::<P, Mutation>);
    }

    fn into_inner(self) -> super::ArtifactStore<P, Mutation> {
        let this = std::mem::ManuallyDrop::new(self);
        unsafe { std::ptr::read(&this.0) }
    }

    async fn current_checkpoint_id(&self) -> Option<&str> {
        self.0.current_checkpoint_id()
    }
}

impl<P, Mutation> std::ops::Deref for ArtifactStore<P, Mutation>
where
    P: Clone + ToValue + FromValue,
    Mutation: Clone + ToValue + FromValue + super::Mutation<P>,
{
    type Target = super::ArtifactStore<P, Mutation>;

    fn deref(&self) -> &Self::Target {
        &self.0
    }
}

impl<P, Mutation> std::ops::DerefMut for ArtifactStore<P, Mutation>
where
    P: Clone + ToValue + FromValue,
    Mutation: Clone + ToValue + FromValue + super::Mutation<P>,
{
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.0
    }
}

/// 🧹️ Drives a test store's owned close to its terminal-empty witness.
fn close_test_store<P, Mutation>(store: &mut super::ArtifactStore<P, Mutation>)
where
    P: Clone + ToValue + FromValue + ArtifactPack + Send + 'static,
    Mutation: Clone + ToValue + FromValue + super::Mutation<P> + OpBinary + OpText + Send + 'static,
{
    drop(store.detach_backbone().expect("a closing test store releases its backbone"));
    let mut last = SnapshotRetirementStep::Complete;
    for _ in 0..1 << 24 {
        if store.close_owned_terminal_is_empty() {
            return;
        }
        last = store.close_owned_step(1, 4_096).expect("test store closes under its bounded owner grant");
        if last == SnapshotRetirementStep::Complete {
            return;
        }
    }
    panic!("test store did not reach its exact terminal-empty witness; last step {last:?}");
}

impl<P, Mutation> Drop for ArtifactStore<P, Mutation>
where
    P: Clone + ToValue + FromValue,
    Mutation: Clone + ToValue + FromValue + super::Mutation<P>,
{
    fn drop(&mut self) {
        if let Some(close) = self.1.take() {
            if !std::thread::panicking() {
                close(&mut self.0);
            }
        }
    }
}

