async fn publish_demo_batch_with(
    store: &mut ArtifactStore<DemoSnapshot, DemoMutation>,
    operation: u64,
    mutations: Vec<DemoMutation>,
    description: Option<String>,
    app_factory: DemoOneItemPreparationFactory,
