    let read = ErasedSnapshotRead::new(rejected, lease);
    drop(match read.into_typed::<String>(&registry) {
        Ok(owner) => owner,
        Err(_) => panic!("retried exact owner handback succeeds"),
    });
    assert!(registry.terminal_is_empty());
}

