    let mut close = store.begin_retirement(Arc::new(DemoSnapshot { n: Some(0) }), |value| value.n == Some(0)).ok().unwrap();
    for _ in 0..2048 {
        if close.close_step(1, 4096).unwrap() == SnapshotRetirementStep::Complete {
            break;
        }
    }
    assert!(close.terminal_is_empty());
}

